    pub fn update_image_blob_hash(
        &mut self,
        block_id: impl AsRef<str>,
        blob_hash: impl AsRef<str>,
    ) -> Result<AppDocument, AppApiError> {
        let hash = opendoc_core::HashRef::parse(blob_hash.as_ref().trim())
            .map_err(|err| AppApiError::Model(err.to_string()))?
            .to_string();
        if !self.blobs.iter().any(|blob| blob.hash == hash) {
            return Err(AppApiError::NotFound("blob was not found".to_string()));
        }
        Ok(self.apply(
            "update-image-blob-hash",
            "image blob replacement",
            OperationKind::UpdateImageBlobHash {
                block_id: parse_id(block_id.as_ref())?,
                blob_hash: hash,
            },
        ))
    }

    pub fn set_spreadsheet_cell(
        &mut self,
        address: impl AsRef<str>,
        value: impl Into<String>,
    ) -> Result<AppDocument, AppApiError> {
        self.signatures.clear();
        self.saved_projection = None;
        let address = normalize_cell_address(address.as_ref())?;
        let value = value.into();
        let sheet_id = self
            .workbook
            .sheets
            .first()
            .map(|sheet| sheet.id.clone())
            .unwrap_or_else(|| "sheet-1".to_string());
        self.workbook.set_cell(&address, value.clone());
        if !self.defer_spreadsheet_evaluation {
            self.workbook = self.workbook.evaluated();
        }
        self.push_spreadsheet_operation(
            "set-spreadsheet-cell",
            &format!("set {address}"),
            AppSpreadsheetOperation::SetCell {
                sheet_id,
                address,
                value,
            },
        );
        Ok(self.document())
    }

