    pub fn set_spreadsheet_cells(
        &mut self,
        entries: Vec<(String, String)>,
    ) -> Result<AppDocument, AppApiError> {
        self.signatures.clear();
        self.saved_projection = None;
        let sheet_id = self
            .workbook
            .sheets
            .first()
            .map(|sheet| sheet.id.clone())
            .unwrap_or_else(|| "sheet-1".to_string());
        let entries = entries
            .into_iter()
            .map(|(address, value)| {
                normalize_cell_address(&address).map(|address| (address, value))
            })
            .collect::<Result<Vec<_>, _>>()?;
        for (address, value) in &entries {
            self.workbook.set_cell(address, value.clone());
        }
        self.workbook = self.workbook.evaluated();
        for (address, value) in entries {
            self.push_spreadsheet_operation(
                "set-spreadsheet-cell",
                &format!("set {address}"),
                AppSpreadsheetOperation::SetCell {
                    sheet_id: sheet_id.clone(),
                    address,
                    value,
                },
            );
        }
        Ok(self.document())
    }

