    fn apply(&mut self, operation_kind: &str, summary: &str, kind: OperationKind) -> AppDocument {
        self.signatures.clear();
        self.saved_projection = None;
        let seq = self.next_seq;
        let op = Operation {
            id: OperationId {
                actor: ActorId(self.actor_id.clone()),
                seq,
            },
            kind: kind.clone(),
        };
        self.next_seq += 1;
        if let Ok(result) = merge_operations(&self.document, &[vec![op]]) {
            self.document = result.document;
            let record = AppOperationRecord {
                actor: self.actor_id.clone(),
                seq,
                kind: operation_kind.to_string(),
                summary: summary.to_string(),
                created_at_ms: now_ms(),
            };
            self.operation_journal.push(record.clone());
            self.operation_envelopes.push(AppOperationEnvelope {
                record,
                operation: Some(Operation {
                    id: OperationId {
                        actor: ActorId(self.actor_id.clone()),
                        seq,
                    },
                    kind,
                }),
                spreadsheet: None,
                blob: None,
            });
        }
        self.document()
    }

    fn apply_batch(&mut self, operations: Vec<(&str, &str, OperationKind)>) -> AppDocument {
        self.signatures.clear();
        self.saved_projection = None;
        let mut merge_ops = Vec::new();
        let mut records = Vec::new();
        for (offset, (operation_kind, summary, kind)) in operations.into_iter().enumerate() {
            let seq = self.next_seq + offset as u64;
            merge_ops.push(Operation {
                id: OperationId {
                    actor: ActorId(self.actor_id.clone()),
                    seq,
                },
                kind: kind.clone(),
            });
            records.push((operation_kind.to_string(), summary.to_string(), seq, kind));
        }
        if let Ok(result) = merge_operations(&self.document, &[merge_ops]) {
            self.document = result.document;
            self.next_seq += records.len() as u64;
            for (operation_kind, summary, seq, kind) in records {
                let record = AppOperationRecord {
                    actor: self.actor_id.clone(),
                    seq,
                    kind: operation_kind,
                    summary,
                    created_at_ms: now_ms(),
                };
                self.operation_journal.push(record.clone());
                self.operation_envelopes.push(AppOperationEnvelope {
                    record,
                    operation: Some(Operation {
                        id: OperationId {
                            actor: ActorId(self.actor_id.clone()),
                            seq,
                        },
                        kind,
                    }),
                    spreadsheet: None,
                    blob: None,
                });
            }
        }
        self.document()
    }

    fn push_app_operation(&mut self, operation_kind: &str, summary: &str) {
        let seq = self.next_seq;
        self.next_seq += 1;
        let record = AppOperationRecord {
            actor: self.actor_id.clone(),
            seq,
            kind: operation_kind.to_string(),
            summary: summary.to_string(),
            created_at_ms: now_ms(),
        };
        self.operation_journal.push(record.clone());
        self.operation_envelopes.push(AppOperationEnvelope {
            record,
            operation: None,
            spreadsheet: None,
            blob: None,
        });
    }

