#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct AppDeletedRowPayload {
    pub row_axis: AppSheetAxis,
    pub cells: Vec<AppCell>,
    pub merges: Vec<AppSheetMerge>,
    pub filters: Vec<AppSheetFilter>,
    pub protected_ranges: Vec<AppSheetProtectedRange>,
    pub named_ranges: Vec<AppNamedRange>,
}

impl AppDeletedRowPayload {
    fn validate_source(&self, row: &str) -> Result<(), AppApiError> {
        let row = normalize_row_label(row)?;
        if self.row_axis.label != row {
            return Err(AppApiError::Format(format!(
                "deleted row payload axis {} does not match row {}",
                self.row_axis.label, row
            )));
        }
        if self.row_axis.id.trim().is_empty() {
            return Err(AppApiError::Format(
                "deleted row payload axis id is empty".to_string(),
            ));
        }
        for cell in &self.cells {
            let (_, cell_row) = split_cell_address(&cell.address);
            cell.format.validate_source()?;
            if let Some(validation) = &cell.validation {
                validation.validate_source()?;
            }
            for dependency in &cell.dependencies {
                normalize_cell_address(dependency)?;
            }
            for comment in &cell.comments {
                comment.validate_source()?;
            }
            if cell_row != row {
                return Err(AppApiError::Format(format!(
                    "deleted row payload cell {} is outside row {}",
                    cell.address, row
                )));
            }
        }
        for merge in &self.merges {
            merge.validate_source()?;
            if !range_contains_row(&merge.range, &row) {
                return Err(AppApiError::Format(format!(
                    "deleted row payload merge {} is outside row {}",
                    merge.range, row
                )));
            }
        }
        for filter in &self.filters {
            filter.validate_source()?;
            if !range_contains_row(&filter.range, &row) {
                return Err(AppApiError::Format(format!(
                    "deleted row payload filter {} is outside row {}",
                    filter.range, row
                )));
            }
        }
        for protected_range in &self.protected_ranges {
            protected_range.validate_source()?;
            if !range_contains_row(&protected_range.range, &row) {
                return Err(AppApiError::Format(format!(
                    "deleted row payload protected range {} is outside row {}",
                    protected_range.range, row
                )));
            }
        }
        for named_range in &self.named_ranges {
            named_range.validate_source()?;
            if !range_contains_row(&named_range.range, &row) {
                return Err(AppApiError::Format(format!(
                    "deleted row payload named range {} is outside row {}",
                    named_range.name, row
                )));
            }
        }
        Ok(())
    }
}

