fn column_to_number(column: &str) -> Option<u32> {
    let mut value = 0u32;
    for ch in column.chars() {
        if !ch.is_ascii_alphabetic() {
            return None;
        }
        value = value
            .checked_mul(26)?
            .checked_add((ch.to_ascii_uppercase() as u8 - b'A' + 1) as u32)?;
    }
    Some(value)
}

fn number_to_column(mut value: u32) -> Option<String> {
    if value == 0 {
        return None;
    }
    let mut chars = Vec::new();
    while value > 0 {
        value -= 1;
        chars.push((b'A' + (value % 26) as u8) as char);
        value /= 26;
    }
    chars.reverse();
    Some(chars.into_iter().collect())
}

fn trim_number(value: f64) -> String {
    if value.fract() == 0.0 {
        format!("{}", value as i64)
    } else {
        value.to_string()
    }
}

fn arg_string(args: &Value, name: &str) -> Result<String, AppApiError> {
    args.get(name)
        .and_then(Value::as_str)
        .map(ToString::to_string)
        .ok_or_else(|| AppApiError::Format(format!("missing string argument {name}")))
}

fn parse_runtime_mode(mode: &str) -> Result<OpenDocRuntimeMode, AppApiError> {
    match mode {
        "tauri-local" => Ok(OpenDocRuntimeMode::TauriLocal),
        "browser-local" => Ok(OpenDocRuntimeMode::BrowserLocal),
        "hpc-single-user" => Ok(OpenDocRuntimeMode::HpcSingleUser),
        "multi-user-service" => Ok(OpenDocRuntimeMode::MultiUserService),
        other => Err(AppApiError::Format(format!(
            "unsupported runtime mode {other}"
        ))),
    }
}

fn runtime_profile_from_args(args: &Value) -> Result<OpenDocRuntimeProfile, AppApiError> {
    Ok(OpenDocRuntimeProfile::for_mode_with_capabilities(
        parse_runtime_mode(&arg_string(args, "mode")?)?,
        arg_runtime_storage_backends(args, "storageBackends")?,
        arg_optional_bool(args, "signingEnabled")?,
    ))
}

/// Gestures that extend the previous undo step when repeated quickly on the
/// same block: plain typing and single-character deletes.
fn undo_coalesce_key(command: &str, args: &Value) -> Option<String> {
    if command != "apply_editor_input" {
        return None;
    }
    let input_type = args.get("input_type")?.as_str()?;
    if !matches!(
        input_type,
        "insertText" | "insertCompositionText" | "deleteContentBackward" | "deleteContentForward"
    ) {
        return None;
    }
    let block_id = args
        .get("selection")?
        .get("focus")?
        .get("block_id")?
        .as_str()?;
    Some(format!("{input_type}:{block_id}"))
}

/// Every command name accepted by [`OpenDocApp::dispatch_command`], read
/// from the shared `commands.v0.json` contract.
pub fn command_names() -> Vec<String> {
    let contract: Value =
        serde_json::from_str(include_str!("../../../apps/desktop/commands.v0.json"))
            .unwrap_or(Value::Null);
    contract
        .get("commands")
        .and_then(Value::as_array)
        .map(|commands| {
            commands
                .iter()
                .filter_map(|command| command.get("name").and_then(Value::as_str))
                .map(str::to_string)
                .collect()
        })
        .unwrap_or_default()
}

