    #[test]
    fn sample_document_projects_full_schema_surface() {
        let mut app = OpenDocApp::new_sample();
        app.add_mention("@alice").unwrap();
        app.add_footnote_ref();
        let doc = app.document();
        assert!(doc.blocks.iter().any(|block| block.kind == "table"));
        assert!(doc.blocks.iter().any(|block| block
            .content
            .iter()
            .any(|inline| inline.kind == "mention" && inline.text == "@alice")));
        assert!(doc.blocks.iter().any(|block| block
            .content
            .iter()
            .any(|inline| inline.kind == "footnote-ref")));
        assert_eq!(doc.footnotes.len(), 1);
        assert_eq!(doc.footnotes[0].body[0].text, "New footnote");
        assert!(!doc.comments.is_empty());
        assert!(!doc.suggestions.is_empty());
        assert_eq!(doc.citations.references.len(), 1);
        assert!(doc.visible_text.contains("(see Doe 2020, page 42)"));
        assert_eq!(doc.signature_state, "unsigned");
    }

    #[test]
    fn mention_label_update_is_operation_backed_and_persists() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-mention-label-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();

        assert!(matches!(
            app.add_mention(" "),
            Err(AppApiError::Format(message)) if message == "mention label is empty"
        ));
        let doc = app.add_mention(" @alice ").unwrap();
        let mention_id = first_inline_id(&doc, "mention");
        assert!(doc.blocks.iter().any(|block| block
            .content
            .iter()
            .any(|inline| inline.kind == "mention" && inline.text == "@alice")));
        assert!(matches!(
            app.update_mention_label(&mention_id, " "),
            Err(AppApiError::Format(message)) if message == "mention label is empty"
        ));
        assert!(matches!(
            app.update_mention_label(first_editable_inline_id(&doc), "@nope"),
            Err(AppApiError::Format(_))
        ));

        let updated = app.update_mention_label(&mention_id, " @bob ").unwrap();
        assert!(updated.blocks.iter().any(|block| block
            .content
            .iter()
            .any(|inline| inline.kind == "mention" && inline.text == "@bob")));
        assert!(updated
            .operations
            .iter()
            .any(|operation| operation.kind == "update-mention-label"));

        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert!(opened.blocks.iter().any(|block| block
            .content
            .iter()
            .any(|inline| inline.kind == "mention" && inline.text == "@bob")));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn compact_local_repository_is_projection_warning_without_source_mutation() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-local-compact-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        app.add_paragraph("compact me");
        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Pack Signer")
            .unwrap();
        let before = app.document();
        let before_operation_count = before.operation_count;
        let before_signature_count = before.signatures.len();
        assert_eq!(before.signature_state, "signed");

        let saved = app.save_to_local_repository(&root).unwrap();
        assert!(saved.last_manifest.is_some());
        let compacted = app.compact_local_repository(&root, "main-pack").unwrap();
        assert!(root.join("packs").join("main-pack.pack").is_file());
        assert!(root.join("packs").join("main-pack.idx").is_file());
        assert!(compacted
            .warnings
            .iter()
            .any(|warning| warning.code == "local-repository-compacted"));
        assert_eq!(compacted.signature_state, "signed");
        assert_eq!(compacted.signatures.len(), before_signature_count);
        assert_eq!(compacted.operation_count, before_operation_count);

        let after = app.document();
        assert_eq!(after.signature_state, "signed");
        assert_eq!(after.signatures.len(), before_signature_count);
        assert_eq!(after.operation_count, before_operation_count);
        assert!(!after
            .warnings
            .iter()
            .any(|warning| warning.code == "local-repository-compacted"));
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert!(opened.visible_text.contains("compact me"));
        assert_eq!(opened.signature_state, "signed");
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn compacted_local_repository_opens_after_loose_objects_are_removed() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-local-compact-packed-open-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        app.add_paragraph("packed repository survives without loose objects");
        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Packed Signer")
            .unwrap();
        let saved = app.save_to_local_repository(&root).unwrap();
        app.compact_local_repository(&root, "main-pack").unwrap();
        std::fs::remove_dir_all(root.join("objects")).unwrap();

        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert!(opened
            .visible_text
            .contains("packed repository survives without loose objects"));
        assert_eq!(opened.signature_state, "signed");
        assert_eq!(
            reopened
                .verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "trusted"
        );
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn runtime_profiles_encode_shell_policy_not_document_source() {
        let cases = [
            (
                OpenDocRuntimeMode::TauriLocal,
                false,
                true,
                false,
                vec![
                    OpenDocStorageBackend::Local,
                    OpenDocStorageBackend::Flat,
                    OpenDocStorageBackend::OpenDalFs,
                ],
                "./opendoc-repo",
                "bucket/prefix",
            ),
            (
                OpenDocRuntimeMode::BrowserLocal,
                false,
                false,
                true,
                vec![OpenDocStorageBackend::Flat],
                "./opendoc-repo",
                "bucket/prefix",
            ),
            (
                OpenDocRuntimeMode::HpcSingleUser,
                false,
                true,
                false,
                vec![
                    OpenDocStorageBackend::Local,
                    OpenDocStorageBackend::Flat,
                    OpenDocStorageBackend::OpenDalFs,
                ],
                "./opendoc-hpc-repo",
                "hpc/opendoc",
            ),
            (
                OpenDocRuntimeMode::MultiUserService,
                true,
                false,
                false,
                vec![
                    OpenDocStorageBackend::Local,
                    OpenDocStorageBackend::Flat,
                    OpenDocStorageBackend::OpenDalFs,
                ],
                "./opendoc-service-cache",
                "service/opendoc",
            ),
        ];
        for (
            mode,
            permissions_enabled,
            signing_enabled,
            browser_signing_deferred,
            storage_backends,
            default_repository_root,
            default_flat_namespace,
        ) in cases
        {
            let profile = OpenDocRuntimeProfile::for_mode(mode);
            assert_eq!(profile.mode, mode);
            assert_eq!(profile.label, mode.label());
            assert_eq!(profile.permissions_enabled, permissions_enabled);
            assert_eq!(profile.signing_enabled, signing_enabled);
            assert_eq!(profile.browser_signing_deferred, browser_signing_deferred);
            assert_eq!(profile.storage_backends, storage_backends);
            assert_eq!(profile.default_repository_root, default_repository_root);
            assert_eq!(profile.default_flat_namespace, default_flat_namespace);
        }

        let app = OpenDocApp::new_sample();
        let before = app.snapshot_payload().unwrap();
        let _service_policy = OpenDocRuntimeProfile::for_mode(OpenDocRuntimeMode::MultiUserService);
        let after = app.snapshot_payload().unwrap();
        assert_eq!(before, after);
    }

