    #[test]
    fn runtime_session_dispatch_is_available_without_open_document() {
        let mut app = OpenDocApp::new_sample();
        app.close_document();
        let session = expect_runtime_session(app.dispatch_command(
            "get_runtime_session",
            serde_json::json!({
                "mode": "hpc-single-user",
                "subject": "hpc-user",
                "documentUuid": null,
                "presence": []
            }),
        ));
        assert_eq!(session.profile.mode, OpenDocRuntimeMode::HpcSingleUser);
        assert!(!session.profile.permissions_enabled);
        assert_eq!(session.authenticated_subject.as_deref(), Some("hpc-user"));
        assert!(session.permissions.is_empty());
        assert_eq!(session.presence.len(), 1);

        let err = app
            .dispatch_command(
                "get_runtime_session",
                serde_json::json!({ "mode": "multi-user-service", "presence": {} }),
            )
            .unwrap_err();
        assert!(err
            .to_string()
            .contains("argument presence must be a presence-peer array"));

        let normalized = expect_runtime_session(app.dispatch_command(
            "get_runtime_session",
            serde_json::json!({
                "mode": "multi-user-service",
                "subject": " alice ",
                "documentUuid": " doc-1 ",
                "presence": [
                    "not-a-peer",
                    { "subject": " " },
                    {
                        "subject": " bob ",
                        "display_name": " ",
                        "role": " ",
                        "cursor_anchor": " inline-1 ",
                        "last_seen_ms": -9
                    },
                    {
                        "subject": " carol ",
                        "display_name": " Carol ",
                        "role": " viewer ",
                        "cursor_anchor": " ",
                        "last_seen_ms": 9.9
                    }
                ]
            }),
        ));
        assert!(normalized.presence.iter().any(|peer| peer.subject == "bob"
            && peer.display_name == "bob"
            && peer.role == "viewer"
            && peer.cursor_anchor.as_deref() == Some("inline-1")
            && peer.last_seen_ms == 0));
        assert!(normalized.presence.iter().any(|peer| {
            peer.subject == "carol"
                && peer.display_name == "Carol"
                && peer.role == "viewer"
                && peer.cursor_anchor.is_none()
                && peer.last_seen_ms == 9
        }));
    }

    #[test]
    fn runtime_session_dispatch_preserves_supplied_service_grants() {
        let mut app = OpenDocApp::new_sample();
        app.close_document();
        let session = expect_runtime_session(app.dispatch_command(
            "get_runtime_session",
            serde_json::json!({
                "mode": "multi-user-service",
                "subject": "carol",
                "documentUuid": "doc-2",
                "presence": [],
                "permissions": [
                    "not-a-grant",
                    {
                        "subject": " ",
                        "action": "read",
                        "scope": "document",
                        "document_uuid": "doc-2"
                    },
                    {
                        "subject": " carol ",
                        "action": " read ",
                        "scope": " document ",
                        "document_uuid": " doc-2 "
                    },
                    {
                        "subject": "carol",
                        "action": "comment",
                        "scope": "document",
                        "document_uuid": "doc-2"
                    }
                ]
            }),
        ));
        assert_eq!(session.profile.mode, OpenDocRuntimeMode::MultiUserService);
        assert_eq!(session.permissions.len(), 2);
        assert_eq!(
            session
                .permissions
                .iter()
                .map(|grant| grant.action.as_str())
                .collect::<Vec<_>>(),
            vec!["read", "comment"]
        );
        assert!(session
            .permissions
            .iter()
            .all(|grant| grant.subject == "carol"
                && grant.scope == "document"
                && grant.document_uuid.as_deref() == Some("doc-2")));

        let authorized = expect_authorization_decision(app.dispatch_command(
            "authorize_runtime_command",
            serde_json::json!({
                "mode": "multi-user-service",
                "subject": " carol ",
                "documentUuid": " doc-2 ",
                "commandName": "get_document",
                "permissions": [
                    false,
                    {
                        "subject": "carol",
                        "action": " ",
                        "scope": "document",
                        "document_uuid": "doc-2"
                    },
                    {
                        "subject": " carol ",
                        "action": " read ",
                        "scope": " document ",
                        "document_uuid": " doc-2 "
                    }
                ]
            }),
        ));
        assert!(authorized.allowed);
        assert_eq!(authorized.subject.as_deref(), Some("carol"));
        assert_eq!(authorized.document_uuid.as_deref(), Some("doc-2"));
    }

