    #[test]
    fn runtime_authorization_applies_runtime_capabilities_without_document_permissions() {
        let local = OpenDocAuthorizationDecision::for_command(
            OpenDocRuntimeMode::HpcSingleUser,
            Some("cluster-user".to_string()),
            None,
            "save_opendal_fs_repository",
            Vec::new(),
        );
        assert!(local.allowed);
        assert_eq!(
            local.reason,
            "runtime does not enforce document-level permissions"
        );
        let browser_signing = OpenDocAuthorizationDecision::for_command(
            OpenDocRuntimeMode::BrowserLocal,
            Some("browser-user".to_string()),
            None,
            "sign_with_openssh_private_key",
            Vec::new(),
        );
        assert!(!browser_signing.allowed);
        assert!(browser_signing.reason.contains("private-key signing"));
        let browser_verify_single = OpenDocAuthorizationDecision::for_command(
            OpenDocRuntimeMode::BrowserLocal,
            Some("browser-user".to_string()),
            None,
            "verify_current_signature",
            Vec::new(),
        );
        assert!(browser_verify_single.allowed);
        assert_eq!(browser_verify_single.required_action, "read");
        let browser_verify_all = OpenDocAuthorizationDecision::for_command(
            OpenDocRuntimeMode::BrowserLocal,
            Some("browser-user".to_string()),
            None,
            "verify_current_signatures",
            Vec::new(),
        );
        assert!(browser_verify_all.allowed);
        assert_eq!(browser_verify_all.required_action, "read");
        let browser_local_store = OpenDocAuthorizationDecision::for_command(
            OpenDocRuntimeMode::BrowserLocal,
            Some("browser-user".to_string()),
            None,
            "save_local_repository",
            Vec::new(),
        );
        assert!(!browser_local_store.allowed);
        assert!(browser_local_store
            .reason
            .contains("local object repositories"));
        let browser_flat_store = OpenDocAuthorizationDecision::for_command(
            OpenDocRuntimeMode::BrowserLocal,
            Some("browser-user".to_string()),
            None,
            "save_flat_repository",
            Vec::new(),
        );
        assert!(browser_flat_store.allowed);
        assert_eq!(browser_flat_store.required_action, "write");
        let unknown = OpenDocAuthorizationDecision::for_command(
            OpenDocRuntimeMode::TauriLocal,
            Some("local-user".to_string()),
            None,
            "not_a_command",
            Vec::new(),
        );
        assert!(!unknown.allowed);
        assert_eq!(unknown.required_action, "unknown");
    }

