    #[test]
    fn runtime_share_invite_creates_service_grants_outside_source() {
        let app = OpenDocApp::new_sample();
        let before = app.snapshot_payload().unwrap();
        let document_uuid = app.document().uuid;
        let issuer_permissions =
            OpenDocPermissionGrant::service_default_grants("alice", &Some(document_uuid.clone()));
        let invite = OpenDocShareInvite::for_runtime(
            OpenDocRuntimeMode::MultiUserService,
            Some("alice".to_string()),
            Some(document_uuid.clone()),
            Some("bob".to_string()),
            vec![
                "read".to_string(),
                "comment".to_string(),
                "write".to_string(),
                "unknown".to_string(),
                "read".to_string(),
            ],
            issuer_permissions,
            123,
        );
        assert!(invite.authorization.allowed);
        assert_eq!(invite.issuer.as_deref(), Some("alice"));
        assert_eq!(invite.target_subject.as_deref(), Some("bob"));
        assert_eq!(
            invite.document_uuid.as_deref(),
            Some(document_uuid.as_str())
        );
        assert_eq!(invite.created_at_ms, 123);
        assert_eq!(
            invite
                .grants
                .iter()
                .map(|grant| grant.action.as_str())
                .collect::<Vec<_>>(),
            vec!["read", "comment", "write"]
        );
        assert!(invite.grants.iter().all(|grant| {
            grant.subject == "bob"
                && grant.scope == "document"
                && grant.document_uuid.as_deref() == Some(document_uuid.as_str())
        }));
        assert_eq!(before, app.snapshot_payload().unwrap());
    }

