    #[test]
    fn footnote_body_updates_are_operation_backed_and_persist() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-footnote-body-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let added = app.add_footnote_ref();
        let footnote_id = added.footnotes[0].id.clone();
        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Footnote Signer")
            .unwrap();

        let updated = app
            .update_footnote_body(&footnote_id, "Footnote source body")
            .unwrap();
        assert_eq!(updated.signature_state, "unsigned");
        assert_eq!(updated.footnotes[0].body[0].text, "Footnote source body");
        assert!(updated
            .operations
            .iter()
            .any(|operation| operation.kind == "upsert-footnote"));
        let operation_count = app.document().operations.len();
        let empty_body = app.update_footnote_body(&footnote_id, " ");
        assert!(matches!(
            empty_body,
            Err(AppApiError::Format(message)) if message == "footnote body is empty"
        ));
        assert_eq!(app.document().operations.len(), operation_count);

        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert!(opened.footnotes.iter().any(|footnote| {
            footnote.id == footnote_id
                && footnote
                    .body
                    .iter()
                    .any(|inline| inline.text == "Footnote source body")
        }));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn deleting_footnote_reference_hides_footnote_and_persists_warning() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-footnote-delete-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let added = app.add_footnote_ref();
        let footnote_id = added.footnotes[0].id.clone();
        let reference_id = first_inline_id(&added, "footnote-ref");

        let deleted = app.delete_inline(&reference_id).unwrap();
        assert!(deleted
            .footnotes
            .iter()
            .any(|footnote| footnote.id == footnote_id && footnote.deleted));
        assert!(deleted
            .warnings
            .iter()
            .any(|warning| warning.code == "footnote-reference-missing"));

        let saved = app.save_to_local_repository(&root).unwrap();
        let opened = OpenDocApp::new_sample()
            .open_saved_projection(&root, &saved.uuid)
            .unwrap();
        assert!(opened
            .footnotes
            .iter()
            .any(|footnote| footnote.id == footnote_id && footnote.deleted));
        assert!(opened
            .warnings
            .iter()
            .any(|warning| warning.code == "footnote-reference-missing"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn creates_blank_document_with_fresh_state() {
        let mut app = OpenDocApp::new_sample();
        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();

        let created = app.new_document("Fresh document");
        assert_eq!(created.title, "Fresh document");
        assert_eq!(created.blocks.len(), 1);
        assert_eq!(created.blocks[0].kind, "paragraph");
        assert_eq!(created.blocks[0].content.len(), 1);
        assert_eq!(created.blocks[0].content[0].kind, "text");
        assert_eq!(created.blocks[0].content[0].text, "");
        assert!(created.comments.is_empty());
        assert!(created.suggestions.is_empty());
        assert!(created.citations.references.is_empty());
        assert!(created.doi.is_none());
        assert_eq!(created.operation_count, 0);
        assert_eq!(created.signature_state, "unsigned");
        assert!(created.signature.is_none());
        assert!(created.signatures.is_empty());
        assert!(created.repository_root.is_none());
        assert!(created.repository_backend.is_none());
        assert!(created.repository_namespace.is_none());
        assert!(created.last_manifest.is_none());
        assert!(!created.workbook.sheets.is_empty());

        let added = app.add_paragraph("after create");
        assert!(added.visible_text.contains("after create"));
        assert_eq!(added.operation_count, 1);
    }

