    #[test]
    fn saves_and_opens_projection_through_local_object_repository() {
        let root = std::env::temp_dir().join(format!("opendoc-app-api-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let inline_id = first_editable_inline_id(&app.document());
        app.update_inline_text(&inline_id, "Edited opening line")
            .unwrap();
        let saved = app.save_to_local_repository(&root).unwrap();
        assert_eq!(
            saved.repository_root,
            Some(root.to_string_lossy().to_string())
        );
        assert_eq!(saved.repository_backend.as_deref(), Some("local"));
        assert_eq!(saved.repository_namespace, None);
        assert_eq!(saved.recent_documents.len(), 1);
        assert_eq!(saved.recent_documents[0].uuid, saved.uuid);
        assert_eq!(saved.recent_documents[0].repository_backend, "local");
        assert_eq!(saved.recent_documents[0].repository_namespace, None);
        assert!(saved
            .last_manifest
            .as_ref()
            .is_some_and(|hash| hash.starts_with("sha256:")));
        assert!(saved.operation_count > 0);
        assert!(saved
            .operations
            .iter()
            .any(|operation| operation.kind == "upsert-citation-group"));
        let manifest_hash =
            opendoc_core::HashRef::parse(saved.last_manifest.as_deref().unwrap()).unwrap();
        let repo = Repository::new(LocalObjectStore::new(&root));
        let manifest = repo
            .read_manifest(&manifest_hash)
            .unwrap()
            .expect("saved manifest exists");
        let snapshot_bytes = repo
            .store()
            .get(&manifest.snapshot)
            .unwrap()
            .expect("saved snapshot exists");
        assert_eq!(
            snapshot_bytes[..5],
            [b'O', b'D', b'F', b'0', SnapshotRecord::<Vec<u8>>::TAG]
        );
        let segment_hash = manifest.operation_segments.last().unwrap();
        let segment_bytes = repo
            .store()
            .get(segment_hash)
            .unwrap()
            .expect("saved operation segment exists");
        assert_eq!(
            segment_bytes[..5],
            [
                b'O',
                b'D',
                b'F',
                b'0',
                OperationSegmentRecord::<Vec<u8>>::TAG
            ]
        );

        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert_eq!(opened.uuid, saved.uuid);
        assert_eq!(opened.visible_text, saved.visible_text);
        assert!(opened.visible_text.contains("Edited opening line"));
        assert_eq!(opened.last_manifest, saved.last_manifest);
        assert_eq!(opened.repository_backend.as_deref(), Some("local"));
        assert_eq!(opened.repository_namespace, None);
        assert_eq!(opened.recent_documents[0].uuid, saved.uuid);
        assert_eq!(opened.citations.references.len(), 1);
        assert_eq!(opened.operation_count, saved.operation_count);
        assert_eq!(opened.operations, saved.operations);
        assert!(opened
            .operations
            .iter()
            .any(|operation| operation.kind == "update-inline-text"));
        let edited = reopened.add_paragraph("after reopen");
        assert_eq!(edited.uuid, saved.uuid);
        assert!(edited.visible_text.contains("after reopen"));
        let autosaved = reopened.autosave_current_repository().unwrap();
        assert_eq!(autosaved.repository_backend.as_deref(), Some("local"));
        assert!(autosaved.visible_text.contains("after reopen"));
        let autosaved_reopened = OpenDocApp::new_sample()
            .open_saved_projection(&root, &saved.uuid)
            .unwrap();
        assert!(autosaved_reopened.visible_text.contains("after reopen"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn scans_local_repository_into_recent_documents_without_opening_document() {
        let root =
            std::env::temp_dir().join(format!("opendoc-app-api-local-scan-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);

        let mut first = OpenDocApp::new_sample();
        first.set_document_title("Repository Scan One").unwrap();
        first.set_document_doi("10.5555/opendoc-scan-one").unwrap();
        let first_saved = first.save_to_local_repository(&root).unwrap();

        let mut second = OpenDocApp::new_sample();
        second.new_document("Repository Scan Two");
        let second_saved = second.save_to_local_repository(&root).unwrap();

        let mut home = OpenDocApp::new_sample();
        home.close_document();
        let scanned = home.scan_local_repository(&root).unwrap();

        assert!(!scanned.is_open);
        assert_eq!(scanned.title, "No document open");
        assert_eq!(
            scanned.repository_root,
            Some(root.to_string_lossy().to_string())
        );
        assert_eq!(scanned.repository_backend.as_deref(), Some("local"));
        assert!(scanned.recent_documents.iter().any(|entry| {
            entry.uuid == first_saved.uuid
                && entry.title == "Repository Scan One"
                && entry.doi.as_deref() == Some("10.5555/opendoc-scan-one")
                && entry.last_manifest == first_saved.last_manifest
        }));
        assert!(scanned.recent_documents.iter().any(|entry| {
            entry.uuid == second_saved.uuid
                && entry.title == "Repository Scan Two"
                && entry.last_manifest == second_saved.last_manifest
        }));

        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn save_state_tracks_unsaved_operations_across_repository_lifecycle() {
        let root =
            std::env::temp_dir().join(format!("opendoc-app-api-save-state-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();

        let fresh = app.new_document("Save State");
        assert!(!fresh.has_unsaved_changes);
        let edited = app.add_paragraph("dirty edit");
        assert!(edited.has_unsaved_changes);

        let saved = app.save_to_local_repository(&root).unwrap();
        assert!(!saved.has_unsaved_changes);

        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert!(!opened.has_unsaved_changes);

        let edited_after_open = reopened.add_paragraph("dirty after open");
        assert!(edited_after_open.has_unsaved_changes);
        let autosaved = reopened.autosave_current_repository().unwrap();
        assert!(!autosaved.has_unsaved_changes);

        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn close_document_preserves_recent_and_requires_reopen_before_editing() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-close-reopen-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        app.add_paragraph("before close");
        let saved = app.save_to_local_repository(&root).unwrap();

        let closed = app.close_document();
        assert!(!closed.is_open);
        assert_eq!(closed.title, "No document open");
        assert!(closed.blocks.is_empty());
        assert!(closed.repository_root.is_none());
        assert!(closed.last_manifest.is_none());
        assert_eq!(closed.recent_documents.len(), 1);
        assert_eq!(closed.recent_documents[0].uuid, saved.uuid);

        let edit_error = app
            .dispatch_command("add_paragraph", serde_json::json!({ "text": "blocked" }))
            .unwrap_err();
        assert!(edit_error.to_string().contains("no document is open"));

        let reopened = app.open_saved_projection(&root, &saved.uuid).unwrap();
        assert!(reopened.is_open);
        assert_eq!(reopened.uuid, saved.uuid);
        assert!(reopened.visible_text.contains("before close"));

        let edited = app.add_paragraph("after reopen");
        assert!(edited.visible_text.contains("after reopen"));
        let _ = std::fs::remove_dir_all(root);
    }

