    #[test]
    fn add_link_rejects_empty_text_or_href() {
        let mut app = OpenDocApp::new_sample();
        let initial_operation_count = app.document().operations.len();

        let added = app
            .add_link("Source", " https://example.invalid/source ")
            .unwrap();
        assert!(added.blocks.iter().any(|block| block
            .content
            .iter()
            .any(|inline| inline.kind == "link"
                && inline.href.as_deref() == Some("https://example.invalid/source"))));

        let empty_text = app.add_link(" ", "https://example.invalid/empty-text");
        assert!(matches!(
            empty_text,
            Err(AppApiError::Format(message)) if message == "link text is empty"
        ));

        let empty_href = app.add_link("Empty href", " ");
        assert!(matches!(
            empty_href,
            Err(AppApiError::Format(message)) if message == "link href is empty"
        ));

        assert_eq!(app.document().operations.len(), initial_operation_count + 1);
    }

