    #[test]
    fn join_paragraph_with_previous_moves_inlines_and_persists() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-join-paragraph-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let first = app.add_paragraph("Alpha ").blocks.last().cloned().unwrap();
        let second = app.add_paragraph("Beta").blocks.last().cloned().unwrap();
        let first_id = first.id.clone();
        let second_id = second.id.clone();
        let moved_inline_id = second.content[0].id.clone();

        let joined = app.join_paragraph_with_previous(&second_id).unwrap();
        let first_after_join = joined
            .blocks
            .iter()
            .find(|block| block.id == first_id)
            .expect("previous paragraph survives join");
        assert_eq!(first_after_join.kind, "paragraph");
        assert_eq!(first_after_join.content.len(), 2);
        assert_eq!(first_after_join.content[0].text, "Alpha ");
        assert_eq!(first_after_join.content[1].id, moved_inline_id);
        assert_eq!(first_after_join.content[1].text, "Beta");
        assert!(!joined.blocks.iter().any(|block| block.id == second_id));
        assert!(joined
            .operations
            .iter()
            .any(|operation| operation.kind == "move-inline-to-block"));
        assert!(joined
            .operations
            .iter()
            .any(|operation| operation.kind == "delete-block"));

        let saved = app.save_to_local_repository(&root).unwrap();
        let opened = OpenDocApp::new_sample()
            .open_saved_projection(&root, &saved.uuid)
            .unwrap();
        let reopened_first = opened
            .blocks
            .iter()
            .find(|block| block.id == first_id)
            .expect("joined paragraph persists");
        assert_eq!(reopened_first.content[1].id, moved_inline_id);
        assert_eq!(reopened_first.content[1].text, "Beta");
        assert!(!opened.blocks.iter().any(|block| block.id == second_id));
        let _ = std::fs::remove_dir_all(root);
    }

