    #[test]
    fn set_block_text_style_converts_text_blocks_and_persists_ids() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-set-block-text-style-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let paragraph = app.add_paragraph("Convertible paragraph");
        let block = paragraph.blocks.last().cloned().unwrap();
        let block_id = block.id.clone();
        let inline_id = block.content[0].id.clone();

        let heading = app
            .set_block_text_style(&block_id, "heading", 3, false)
            .unwrap();
        let converted_heading = heading
            .blocks
            .iter()
            .find(|block| block.id == block_id)
            .unwrap();
        assert_eq!(converted_heading.kind, "heading");
        assert_eq!(converted_heading.level, Some(3));
        assert_eq!(converted_heading.content[0].id, inline_id);

        let list = app
            .set_block_text_style(&block_id, "list-item", 1, true)
            .unwrap();
        let converted_list = list
            .blocks
            .iter()
            .find(|block| block.id == block_id)
            .unwrap();
        assert_eq!(converted_list.kind, "list-item");
        assert_eq!(converted_list.level, Some(1));
        assert_eq!(converted_list.ordered, Some(true));
        assert_eq!(converted_list.content[0].id, inline_id);

        let normal = app
            .set_block_text_style(&block_id, "paragraph", 0, false)
            .unwrap();
        let converted_paragraph = normal
            .blocks
            .iter()
            .find(|block| block.id == block_id)
            .unwrap();
        assert_eq!(converted_paragraph.kind, "paragraph");
        assert_eq!(converted_paragraph.level, None);
        assert_eq!(converted_paragraph.ordered, None);
        assert_eq!(converted_paragraph.content[0].id, inline_id);
        assert!(normal
            .operations
            .iter()
            .any(|operation| operation.kind == "set-block-text-style"));

        let saved = app.save_to_local_repository(&root).unwrap();
        let opened = OpenDocApp::new_sample()
            .open_saved_projection(&root, &saved.uuid)
            .unwrap();
        let reopened = opened
            .blocks
            .iter()
            .find(|block| block.id == block_id)
            .unwrap();
        assert_eq!(reopened.kind, "paragraph");
        assert_eq!(reopened.content[0].id, inline_id);
        let _ = std::fs::remove_dir_all(root);
    }

