    #[test]
    fn local_repository_rejects_semantically_invalid_operation_segment_history() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-invalid-segment-envelope-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let app = OpenDocApp::new_sample();
        let repo = Repository::new(LocalObjectStore::new(&root));
        let invalid_segment = OperationSegmentRecord {
            kind: opendoc_format::OPERATION_SEGMENT_KIND.to_string(),
            document_uuid: app.document.uuid.to_string(),
            branch: String::new(),
            previous_segment: None,
            base_manifest: None,
            operations: Vec::<AppOperationEnvelope>::new(),
        };
        let bytes = encode_canonical_cbor(&invalid_segment).unwrap();
        let segment_hash = digest_bytes("sha256", &bytes).unwrap();
        repo.store().put_if_absent(&segment_hash, &bytes).unwrap();
        let manifest = ManifestRecord {
            document_uuid: app.document.uuid.to_string(),
            branch: SNAPSHOT_BRANCH.to_string(),
            parent: None,
            snapshot: opendoc_core::HashRef::parse("sha256:aaa").unwrap(),
            operation_segments: vec![segment_hash],
            signatures: Vec::new(),
            blobs: Vec::new(),
            created_at_ms: 1,
        };

        let err = app
            .read_operation_envelopes(&repo, &manifest)
            .unwrap_err()
            .to_string();
        assert!(err.contains("operation segment branch is empty"));

        let mut app = OpenDocApp::new_sample();
        app.set_document_title("Invalid operation base manifest")
            .unwrap();
        let invalid_segment = OperationSegmentRecord::new(
            app.document.uuid.to_string(),
            SNAPSHOT_BRANCH,
            None,
            Some(" sha256:manifest ".to_string()),
            vec![app.operation_envelopes.last().unwrap().clone()],
        );
        let bytes = encode_canonical_cbor(&invalid_segment).unwrap();
        let segment_hash = digest_bytes("sha256", &bytes).unwrap();
        repo.store().put_if_absent(&segment_hash, &bytes).unwrap();
        let manifest = ManifestRecord {
            document_uuid: app.document.uuid.to_string(),
            branch: SNAPSHOT_BRANCH.to_string(),
            parent: None,
            snapshot: opendoc_core::HashRef::parse("sha256:aaa").unwrap(),
            operation_segments: vec![segment_hash],
            signatures: Vec::new(),
            blobs: Vec::new(),
            created_at_ms: 2,
        };

        let err = app
            .read_operation_envelopes(&repo, &manifest)
            .unwrap_err()
            .to_string();
        assert!(err.contains("operation segment base_manifest has surrounding whitespace"));
        let _ = std::fs::remove_dir_all(root);
    }

