    #[test]
    fn save_rejects_invalid_operation_envelope_before_writing_objects() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-invalid-operation-save-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        app.add_paragraph("invalid operation should not be persisted");
        app.operation_envelopes
            .last_mut()
            .unwrap()
            .operation
            .as_mut()
            .unwrap()
            .id
            .seq += 1;

        let err = app.save_to_local_repository(&root).unwrap_err().to_string();
        assert!(err.contains("operation envelope record does not match"));
        assert!(
            !root.exists() || !root.join("objects").exists(),
            "invalid operation envelopes should be rejected before object writes"
        );
        let _ = std::fs::remove_dir_all(root);
    }

