    #[test]
    fn remove_text_mark_rejects_invalid_mark_payload() {
        let mut app = OpenDocApp::new_sample();
        let inline_id = first_editable_inline_id(&app.document());
        app.add_text_mark(&inline_id, "bold", None).unwrap();
        app.add_text_mark(&inline_id, "color", Some("#2255aa".to_string()))
            .unwrap();

        let err = app
            .remove_text_mark(&inline_id, "bold", Some("true".to_string()))
            .unwrap_err()
            .to_string();
        assert!(err.contains("boolean mark has value"));

        let doc = app.remove_text_mark(&inline_id, "color", None).unwrap();
        let inline = doc
            .blocks
            .iter()
            .flat_map(|block| block.content.iter())
            .find(|inline| inline.id == inline_id)
            .unwrap();
        assert!(!inline.marks.iter().any(|mark| mark.starts_with("color:")));
    }

