    #[test]
    fn save_rejects_operation_envelope_duplicate_from_parent_history() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-duplicate-operation-save-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        app.add_paragraph("first persisted operation");
        let first_save = app.save_to_local_repository(&root).unwrap();
        app.add_paragraph("duplicate operation should not be persisted");
        let envelope = app.operation_envelopes.last_mut().unwrap();
        envelope.record.seq = 1;
        envelope.operation.as_mut().unwrap().id.seq = 1;

        let err = app.save_to_local_repository(&root).unwrap_err().to_string();
        assert!(err.contains("duplicate operation envelope"));

        let repo = Repository::new(LocalObjectStore::new(&root));
        let head = repo
            .store()
            .read_head(&first_save.uuid, SNAPSHOT_BRANCH)
            .unwrap()
            .unwrap();
        assert_eq!(Some(head.to_string()), first_save.last_manifest);
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn local_repository_rejects_mismatched_operation_segment_history_envelope() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-invalid-operation-history-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        app.add_paragraph("hash-valid operation history must still validate");
        let mut envelope = app.operation_envelopes.last().unwrap().clone();
        envelope.record.seq += 1;
        let repo = Repository::new(LocalObjectStore::new(&root));
        let segment = OperationSegmentRecord::new(
            app.document.uuid.to_string(),
            SNAPSHOT_BRANCH,
            None,
            None,
            vec![envelope],
        );
        let bytes = encode_canonical_cbor(&segment).unwrap();
        let segment_hash = digest_bytes("sha256", &bytes).unwrap();
        repo.store().put_if_absent(&segment_hash, &bytes).unwrap();
        let manifest = ManifestRecord {
            document_uuid: app.document.uuid.to_string(),
            branch: SNAPSHOT_BRANCH.to_string(),
            parent: None,
            snapshot: opendoc_core::HashRef::parse("sha256:aaa").unwrap(),
            operation_segments: vec![segment_hash],
            signatures: Vec::new(),
            blobs: Vec::new(),
            created_at_ms: 1,
        };

        let err = app
            .read_operation_envelopes(&repo, &manifest)
            .unwrap_err()
            .to_string();
        assert!(err.contains("operation envelope record does not match"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn local_repository_rejects_empty_operation_audit_summary() {
        let cases = [
            (
                "empty-summary",
                "operation record summary is empty",
                Box::new(|envelope: &mut AppOperationEnvelope| {
                    envelope.record.summary.clear();
                }) as Box<dyn Fn(&mut AppOperationEnvelope)>,
            ),
            (
                "padded-summary",
                "operation record summary has surrounding whitespace",
                Box::new(|envelope: &mut AppOperationEnvelope| {
                    envelope.record.summary = format!(" {} ", envelope.record.summary);
                }),
            ),
            (
                "padded-kind",
                "operation record kind has surrounding whitespace",
                Box::new(|envelope: &mut AppOperationEnvelope| {
                    envelope.record.kind = format!(" {} ", envelope.record.kind);
                }),
            ),
            (
                "padded-actor",
                "operation record actor has surrounding whitespace",
                Box::new(|envelope: &mut AppOperationEnvelope| {
                    envelope.record.actor = format!(" {} ", envelope.record.actor);
                }),
            ),
            (
                "padded-payload-actor",
                "operation payload actor has surrounding whitespace",
                Box::new(|envelope: &mut AppOperationEnvelope| {
                    let operation = envelope.operation.as_mut().unwrap();
                    operation.id.actor.0 = format!(" {} ", operation.id.actor.0);
                }),
            ),
        ];

        for (name, expected, mutate) in cases {
            let root = std::env::temp_dir().join(format!(
                "opendoc-app-api-operation-audit-{name}-{}",
                std::process::id()
            ));
            let _ = std::fs::remove_dir_all(&root);
            let mut app = OpenDocApp::new_sample();
            app.add_paragraph("operation history audit records must stay meaningful");
            let mut envelope = app.operation_envelopes.last().unwrap().clone();
            mutate(&mut envelope);
            let repo = Repository::new(LocalObjectStore::new(&root));
            let segment = OperationSegmentRecord::new(
                app.document.uuid.to_string(),
                SNAPSHOT_BRANCH,
                None,
                None,
                vec![envelope],
            );
            let bytes = encode_canonical_cbor(&segment).unwrap();
            let segment_hash = digest_bytes("sha256", &bytes).unwrap();
            repo.store().put_if_absent(&segment_hash, &bytes).unwrap();
            let manifest = ManifestRecord {
                document_uuid: app.document.uuid.to_string(),
                branch: SNAPSHOT_BRANCH.to_string(),
                parent: None,
                snapshot: opendoc_core::HashRef::parse("sha256:aaa").unwrap(),
                operation_segments: vec![segment_hash],
                signatures: Vec::new(),
                blobs: Vec::new(),
                created_at_ms: 1,
            };

            let err = app
                .read_operation_envelopes(&repo, &manifest)
                .unwrap_err()
                .to_string();
            assert!(err.contains(expected), "{name}: {err}");
            let _ = std::fs::remove_dir_all(root);
        }
    }

