        let snapshot_hash = digest_bytes("sha256", &bytes).unwrap();
        repo.store().put_if_absent(&snapshot_hash, &bytes).unwrap();
        let manifest = ManifestRecord {
            document_uuid: app.document.uuid.to_string(),
            branch: SNAPSHOT_BRANCH.to_string(),
            parent: None,
            snapshot: snapshot_hash,
            operation_segments: Vec::new(),
            signatures: Vec::new(),
            blobs: Vec::new(),
            created_at_ms: 1,
        };
