    #[test]
    fn open_rejects_structurally_invalid_app_snapshot_source() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-invalid-app-source-open-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        app.add_binary_blob("valid.bin", "application/octet-stream", b"bytes".to_vec())
            .unwrap();
        let saved = app.save_to_local_repository(&root).unwrap();
        let manifest_hash =
            opendoc_core::HashRef::parse(saved.last_manifest.as_deref().unwrap()).unwrap();
        let repo = Repository::new(LocalObjectStore::new(&root));
        let mut manifest = repo
            .read_manifest(&manifest_hash)
            .unwrap()
            .expect("saved manifest exists");
        let snapshot_bytes = repo
            .store()
            .get(&manifest.snapshot)
            .unwrap()
            .expect("saved snapshot exists");
        let mut snapshot = OpenDocApp::decode_snapshot_object(&snapshot_bytes).unwrap();
        snapshot.source.blobs[0].signature_state = "signed".to_string();
        snapshot.source.blobs[0].signatures.push(AppSignature {
            target: "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
                .to_string(),
            signer: "ssh-ed25519 AAAAinvalidsource".to_string(),
            signer_display: "Invalid Source".to_string(),
            title: "invalid app source".to_string(),
            signed_at_ms: 11,
        });
        let invalid_snapshot_source = encode_canonical_cbor(&snapshot.source).unwrap();
        let invalid_snapshot_envelope = SnapshotRecord::new(
            snapshot.document_uuid,
            snapshot.source_format,
            invalid_snapshot_source,
        );
        invalid_snapshot_envelope.validate().unwrap();
        let invalid_snapshot_bytes = encode_record(&invalid_snapshot_envelope);
        let invalid_snapshot_hash = digest_bytes("sha256", &invalid_snapshot_bytes).unwrap();
        repo.store()
            .put_if_absent(&invalid_snapshot_hash, &invalid_snapshot_bytes)
            .unwrap();
        manifest.parent = Some(manifest_hash.clone());
        manifest.snapshot = invalid_snapshot_hash;
        manifest.signatures = Vec::new();
        let invalid_manifest_hash = repo.write_manifest(&manifest).unwrap();
        assert!(repo
            .store()
            .compare_and_swap_head(
                &saved.uuid,
                SNAPSHOT_BRANCH,
                Some(&manifest_hash),
                &invalid_manifest_hash,
            )
            .unwrap());

        let err = OpenDocApp::new_sample()
            .open_saved_projection(&root, &saved.uuid)
            .unwrap_err()
            .to_string();
        assert!(err.contains("blob signature target"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn local_repository_merges_divergent_candidate_operations() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-candidate-merge-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut base = OpenDocApp::new_sample();
        let saved_base = base.save_to_local_repository(&root).unwrap();

        let mut current = OpenDocApp::new_sample();
        current
            .open_saved_projection(&root, &saved_base.uuid)
            .unwrap();
        let mut candidate = OpenDocApp::new_sample();
        candidate
            .open_saved_projection(&root, &saved_base.uuid)
            .unwrap();

        current
            .set_document_title("Current Metadata Title")
            .unwrap();
        current.set_document_locale("sv-SE").unwrap();
        current.add_paragraph("current branch edit");
        let saved_current = current.save_to_local_repository(&root).unwrap();
        candidate
            .set_document_doi("10.4321/Candidate.Metadata")
            .unwrap();
        candidate.add_paragraph("candidate branch edit");
        let saved_candidate = candidate
            .save_to_local_repository_or_candidate(&root)
            .unwrap();
        assert_ne!(saved_candidate.last_manifest, saved_current.last_manifest);

        let repo = Repository::new(LocalObjectStore::new(&root));
        let plans = repo
            .plan_candidate_merges(&saved_base.uuid, SNAPSHOT_BRANCH)
            .unwrap();
        assert_eq!(plans.plans.len(), 1);

        let mut merger = OpenDocApp::new_sample();
        let merged = merger
            .merge_local_repository_candidates(&root, &saved_base.uuid)
            .unwrap();
        assert!(merged.visible_text.contains("current branch edit"));
        assert!(merged.visible_text.contains("candidate branch edit"));
        assert_eq!(merged.title, "Current Metadata Title");
        assert_eq!(merged.locale, "sv-SE");
        assert_eq!(merged.doi.as_deref(), Some("10.4321/Candidate.Metadata"));
        assert!(merged
            .operations
            .iter()
            .any(|operation| operation.kind == "set-document-title"));
        assert!(merged
            .operations
            .iter()
            .any(|operation| operation.kind == "set-document-locale"));
        assert!(merged
            .operations
            .iter()
            .any(|operation| operation.kind == "set-document-doi"));
        assert_ne!(merged.last_manifest, saved_current.last_manifest);
        let reopened = OpenDocApp::new_sample()
            .open_saved_projection(&root, &saved_base.uuid)
            .unwrap();
        assert_eq!(reopened.visible_text, merged.visible_text);
        assert_eq!(reopened.title, merged.title);
        assert_eq!(reopened.locale, merged.locale);
        assert_eq!(reopened.doi, merged.doi);
        let _ = std::fs::remove_dir_all(root);
    }

