    #[cfg(feature = "opendal-store")]
    #[test]
    fn opendal_fs_repository_save_open_doi_autosave_and_merge_candidates() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-opendal-fs-repository-{}",
            std::process::id()
        ));
        let namespace = "bucket/prefix";
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).unwrap();

        let mut base = OpenDocApp::new_sample();
        base.set_document_doi("10.1234/opendoc-opendal").unwrap();
        let saved = base
            .save_to_opendal_fs_repository(&root, namespace)
            .unwrap();
        assert_eq!(saved.repository_backend.as_deref(), Some("opendal-fs"));
        assert_eq!(saved.repository_namespace.as_deref(), Some(namespace));
        assert_eq!(saved.recent_documents.len(), 1);
        assert_eq!(saved.recent_documents[0].uuid, saved.uuid);
        assert_eq!(saved.recent_documents[0].repository_backend, "opendal-fs");
        assert_eq!(
            saved.recent_documents[0].repository_namespace.as_deref(),
            Some(namespace)
        );

        let opened = OpenDocApp::new_sample()
            .open_opendal_fs_projection(&root, namespace, &saved.uuid)
            .unwrap();
        assert_eq!(opened.uuid, saved.uuid);
        assert_eq!(opened.repository_backend.as_deref(), Some("opendal-fs"));
        assert_eq!(opened.repository_namespace.as_deref(), Some(namespace));
        assert_eq!(opened.recent_documents[0].uuid, saved.uuid);
        assert_eq!(
            opened.recent_documents[0].repository_namespace.as_deref(),
            Some(namespace)
        );
        let opened_by_doi = OpenDocApp::new_sample()
            .open_opendal_fs_projection_by_doi(&root, namespace, "10.1234/opendoc-opendal")
            .unwrap();
        assert_eq!(opened_by_doi.uuid, saved.uuid);
        assert_eq!(
            opened_by_doi.recent_documents[0]
                .repository_namespace
                .as_deref(),
            Some(namespace)
        );
        std::fs::remove_file(root.join(namespace).join(
            opendoc_store::ObjectStoreLayout::doi_lookup_key("10.1234/opendoc-opendal").unwrap(),
        ))
        .unwrap();
        let opened_by_scan = OpenDocApp::new_sample()
            .open_opendal_fs_projection_by_doi(&root, namespace, "10.1234/opendoc-opendal")
            .unwrap();
        assert_eq!(opened_by_scan.uuid, saved.uuid);
        assert!(opened_by_scan
            .warnings
            .iter()
            .any(|warning| warning.code == "doi-lookup-scan-fallback"));

        let mut wrong_app = OpenDocApp::new_sample();
        wrong_app.set_document_doi("10.9999/opendal-wrong").unwrap();
        let wrong_saved = wrong_app
            .save_to_opendal_fs_repository(&root, namespace)
            .unwrap();
        let repo = Repository::new(OpenDalObjectStore::from_fs_root(&root, namespace).unwrap());
        let wrong_lookup = repo
            .read_uuid_lookup(&wrong_saved.uuid)
            .unwrap()
            .expect("wrong uuid lookup exists");
        repo.store()
            .put_named(
                &opendoc_store::ObjectStoreLayout::doi_lookup_key("10.1234/opendoc-opendal")
                    .unwrap(),
                &opendoc_format::encode_record(&wrong_lookup),
            )
            .unwrap();
        let opened_with_stale_direct_index = OpenDocApp::new_sample()
            .open_opendal_fs_projection_by_doi(&root, namespace, "10.1234/opendoc-opendal")
            .unwrap();
        assert_eq!(opened_with_stale_direct_index.uuid, saved.uuid);
        assert_ne!(opened_with_stale_direct_index.uuid, wrong_saved.uuid);
        assert!(opened_with_stale_direct_index
            .warnings
            .iter()
            .any(|warning| warning.code == "doi-lookup-scan-fallback"));

        let mut current = OpenDocApp::new_sample();
        current
            .open_opendal_fs_projection(&root, namespace, &saved.uuid)
            .unwrap();
        current.add_paragraph("OpenDAL current edit");
        current
            .save_to_opendal_fs_repository_or_candidate(&root, namespace)
            .unwrap();

        let mut candidate = OpenDocApp::new_sample();
        candidate
            .open_opendal_fs_projection(&root, namespace, &saved.uuid)
            .unwrap();
        candidate.add_paragraph("OpenDAL candidate edit");
        candidate
            .save_to_opendal_fs_repository_or_candidate(&root, namespace)
            .unwrap();

        let mut merger = OpenDocApp::new_sample();
        let merged = merger
            .merge_opendal_fs_repository_candidates(&root, namespace, &saved.uuid)
            .unwrap();
        assert!(merged.visible_text.contains("OpenDAL current edit"));
        assert!(merged.visible_text.contains("OpenDAL candidate edit"));

        let autosaved = merger.autosave_current_repository().unwrap();
        assert_eq!(autosaved.repository_backend.as_deref(), Some("opendal-fs"));
        assert_eq!(autosaved.repository_namespace.as_deref(), Some(namespace));
        assert_eq!(autosaved.recent_documents[0].uuid, saved.uuid);
        assert_eq!(
            autosaved.recent_documents[0].repository_backend,
            "opendal-fs"
        );
        assert_eq!(
            autosaved.recent_documents[0]
                .repository_namespace
                .as_deref(),
            Some(namespace)
        );
        let reopened = OpenDocApp::new_sample()
            .open_opendal_fs_projection(&root, namespace, &saved.uuid)
            .unwrap();
        assert_eq!(reopened.visible_text, autosaved.visible_text);
        let _ = std::fs::remove_dir_all(root);
    }

    fn assert_rich_document_candidate_merge_round_trips(
        root: &std::path::Path,
        repository: RichMergeRepository<'_>,
    ) {
        let _ = std::fs::remove_dir_all(root);
        let mut base = OpenDocApp::new_sample();
        base.add_equation_inline("a=b").unwrap();
        base.add_equation_block("x=1").unwrap();
        let table_doc = base.add_table();
        base.add_sample_citation();
        base.add_comment("Reviewer", "Base comment").unwrap();
        base.add_suggestion("Reviewer", "Base suggestion").unwrap();
        let table = table_doc
            .blocks
            .iter()
            .find(|block| block.kind == "table")
            .expect("base table exists");
        let table_block_id = table.id.clone();
        let first_row_id = table.row_ids[0].clone();
        let first_cell_id = table.cell_ids[0][0].clone();
        let base_doc = base.document();
        let editable_inline_id = first_editable_inline_id(&base_doc);
        let inline_equation_id = first_inline_id(&base_doc, "equation");
        let equation_block_id = first_block_id(&base_doc, "equation-block");
        let comment_thread = base_doc.comments.last().expect("base comment exists");
        let comment_thread_id = comment_thread.id.clone();
        let comment_id = comment_thread.comments[0].id.clone();
        let suggestion_id = base_doc
            .suggestions
            .last()
            .expect("base suggestion exists")
            .id
            .clone();
        let saved_base = repository.save(&mut base, root);

        let mut current = OpenDocApp::new_sample();
        repository.open(&mut current, root, &saved_base.uuid);
        current.actor_id = "actor-current".to_string();

        let mut candidate = OpenDocApp::new_sample();
        repository.open(&mut candidate, root, &saved_base.uuid);
        candidate.actor_id = "actor-candidate".to_string();

        current
            .update_inline_equation_source(&inline_equation_id, "\\alpha + \\beta")
            .unwrap();
        current
            .update_comment(&comment_thread_id, &comment_id, "Current branch comment")
            .unwrap();
        current
            .add_table_row(
                &table_block_id,
                Some(first_row_id.clone()),
                "Current merged row",
            )
            .unwrap();
        current
            .add_format_suggestion("Current reviewer", &editable_inline_id, "bold", None)
            .unwrap();
        repository.save(&mut current, root);

        candidate
            .update_block_equation_source(&equation_block_id, "y=2")
            .unwrap();
        candidate
            .update_suggestion(&suggestion_id, "Candidate rewritten suggestion")
            .unwrap();
        candidate
            .add_table_cell(
                &table_block_id,
                &first_row_id,
                Some(first_cell_id),
                "Candidate merged cell",
            )
            .unwrap();
        candidate
            .insert_citation(
                "ref-doe-2020",
                Some(editable_inline_id),
                Some("42".to_string()),
                Some("page".to_string()),
                None,
                None,
                false,
            )
            .unwrap();
        repository.save_or_candidate(&mut candidate, root);

        let mut merger = OpenDocApp::new_sample();
        let merged = repository.merge(&mut merger, root, &saved_base.uuid);
        assert!(merged.blocks.iter().any(|block| {
            block
                .content
                .iter()
                .any(|inline| inline.kind == "equation" && inline.text == "\\alpha + \\beta")
        }));
        assert!(merged.blocks.iter().any(|block| {
            block.kind == "equation-block" && block.equation_source.as_deref() == Some("y=2")
        }));
        assert!(merged.comments.iter().any(|thread| {
            thread.id == comment_thread_id
                && thread.comments.iter().any(|comment| {
                    comment.id == comment_id && comment.body == "Current branch comment"
                })
        }));
        assert!(merged.suggestions.iter().any(|suggestion| {
            suggestion.id == suggestion_id && suggestion.text == "Candidate rewritten suggestion"
        }));
        assert!(merged.suggestions.iter().any(|suggestion| {
            suggestion.kind == "format" && suggestion.marks == ["bold:both"]
        }));
        assert!(merged.citations.citations.len() >= 2);
        assert!(
            merged
                .blocks
                .iter()
                .any(|block| block.kind == "table"
                    && table_contains_text(block, "Current merged row"))
        );
        assert!(merged
            .blocks
            .iter()
            .any(|block| block.kind == "table"
                && table_contains_text(block, "Candidate merged cell")));
        assert!(merged
            .operations
            .iter()
            .any(|operation| operation.actor == "actor-current"));
        assert!(merged
            .operations
            .iter()
            .any(|operation| operation.actor == "actor-candidate"));

        let mut reopened_app = OpenDocApp::new_sample();
        let reopened = repository.open(&mut reopened_app, root, &saved_base.uuid);
        assert_eq!(reopened.visible_text, merged.visible_text);
        assert_eq!(
            reopened.citations.citations.len(),
            merged.citations.citations.len()
        );
        assert!(reopened
            .blocks
            .iter()
            .any(|block| block.kind == "table"
                && table_contains_text(block, "Candidate merged cell")));
        let second_pass = repository.merge(&mut merger, root, &saved_base.uuid);
        assert_eq!(second_pass.visible_text, merged.visible_text);
        assert_eq!(second_pass.suggestions, merged.suggestions);
        assert_eq!(second_pass.comments, merged.comments);
        let _ = std::fs::remove_dir_all(root);
    }

    fn assert_table_deleted_anchor_candidate_merge(
        root: &std::path::Path,
        repository: RichMergeRepository<'_>,
    ) {
        let _ = std::fs::remove_dir_all(root);
        let mut base = OpenDocApp::new_sample();
        let table_doc = base.add_table();
        let table = table_doc
            .blocks
            .iter()
            .find(|block| block.kind == "table")
            .expect("base table exists");
        let table_block_id = table.id.clone();
        let deleted_row_id = table.row_ids[0].clone();
        let surviving_row_id = table.row_ids[1].clone();
        let deleted_cell_id = table.cell_ids[1][0].clone();
        let saved_base = repository.save(&mut base, root);

        let mut current = OpenDocApp::new_sample();
        repository.open(&mut current, root, &saved_base.uuid);
        current.actor_id = "actor-a-table".to_string();
        current
            .delete_table_row(&table_block_id, &deleted_row_id)
            .unwrap();
        current
            .delete_table_cell(&table_block_id, &surviving_row_id, &deleted_cell_id)
            .unwrap();
        repository.save(&mut current, root);

        let mut candidate = OpenDocApp::new_sample();
        repository.open(&mut candidate, root, &saved_base.uuid);
        candidate.actor_id = "actor-b-table".to_string();
        candidate
            .add_table_row(
                &table_block_id,
                Some(deleted_row_id.clone()),
                "Candidate row after deleted anchor",
            )
            .unwrap();
        candidate
            .add_table_cell(
                &table_block_id,
                &surviving_row_id,
                Some(deleted_cell_id.clone()),
                "Candidate cell after deleted anchor",
            )
            .unwrap();
        repository.save_or_candidate(&mut candidate, root);

        let mut merger = OpenDocApp::new_sample();
        let merged = repository.merge(&mut merger, root, &saved_base.uuid);
        let merged_table = merged
            .blocks
            .iter()
            .find(|block| block.id == table_block_id)
            .expect("merged table exists");
        assert!(table_contains_text(
            merged_table,
            "Candidate row after deleted anchor"
        ));
        assert!(table_contains_text(
            merged_table,
            "Candidate cell after deleted anchor"
        ));
        assert!(!merged_table.row_ids.contains(&deleted_row_id));
        assert!(!merged_table
            .cell_ids
            .iter()
            .flatten()
            .any(|cell_id| cell_id == &deleted_cell_id));
        assert!(merged
            .warnings
            .iter()
            .any(|warning| warning.code == "table-row-anchor-degraded"));
        assert!(merged
            .warnings
            .iter()
            .any(|warning| warning.code == "table-cell-anchor-degraded"));
        assert!(merged.operations.iter().any(|operation| {
            operation.actor == "actor-a-table" && operation.kind == "delete-table-row"
        }));
        assert!(merged.operations.iter().any(|operation| {
            operation.actor == "actor-b-table" && operation.kind == "insert-table-row"
        }));

        let mut reopened_app = OpenDocApp::new_sample();
        let reopened = repository.open(&mut reopened_app, root, &saved_base.uuid);
        let reopened_table = reopened
            .blocks
            .iter()
            .find(|block| block.id == table_block_id)
            .expect("reopened table exists");
        assert!(table_contains_text(
            reopened_table,
            "Candidate row after deleted anchor"
        ));
        assert!(table_contains_text(
            reopened_table,
            "Candidate cell after deleted anchor"
        ));
        assert!(reopened
            .warnings
            .iter()
            .any(|warning| warning.code == "table-row-anchor-degraded"));
        assert!(reopened
            .warnings
            .iter()
            .any(|warning| warning.code == "table-cell-anchor-degraded"));

        let second_pass = repository.merge(&mut merger, root, &saved_base.uuid);
        assert_eq!(second_pass.blocks, merged.blocks);
        assert_eq!(second_pass.warnings, merged.warnings);
        let _ = std::fs::remove_dir_all(root);
    }

    fn assert_citation_style_update_and_insert_candidate_merge(
        root: &std::path::Path,
        repository: RichMergeRepository<'_>,
    ) {
        let _ = std::fs::remove_dir_all(root);
        let mut base = OpenDocApp::new_sample();
        let base_doc = base.add_sample_citation();
        let citation_anchor_id = first_editable_inline_id(&base_doc);
        let saved_base = repository.save(&mut base, root);

        let mut current = OpenDocApp::new_sample();
        repository.open(&mut current, root, &saved_base.uuid);
        current.actor_id = "actor-a-citation".to_string();
        current.set_citation_style("ieee", "en-US").unwrap();
        repository.save(&mut current, root);

        let mut candidate = OpenDocApp::new_sample();
        repository.open(&mut candidate, root, &saved_base.uuid);
        candidate.actor_id = "actor-b-citation".to_string();
        candidate
            .insert_citation(
                "ref-doe-2020",
                Some(citation_anchor_id),
                Some("42".to_string()),
                Some("page".to_string()),
                Some("see".to_string()),
                None,
                false,
            )
            .unwrap();
        repository.save_or_candidate(&mut candidate, root);

        let mut merger = OpenDocApp::new_sample();
        let merged = repository.merge(&mut merger, root, &saved_base.uuid);
        assert_eq!(merged.citations.style, "ieee");
        assert_eq!(merged.citations.locale, "en-US");
        assert!(merged.citations.citations.len() >= 2);
        assert!(merged
            .citations
            .citations
            .iter()
            .filter(|citation| !citation.deleted)
            .all(|citation| citation.rendered_cache.is_some()));
        assert!(merged.visible_text.contains("[1]"));
        assert!(merged.operations.iter().any(|operation| {
            operation.actor == "actor-a-citation" && operation.kind == "set-citation-style"
        }));
        assert!(merged.operations.iter().any(|operation| {
            operation.actor == "actor-b-citation" && operation.kind == "upsert-citation-group"
        }));
        assert!(merged.operations.iter().any(|operation| {
            operation.actor == "actor-b-citation" && operation.kind == "insert-inline"
        }));

        let mut reopened_app = OpenDocApp::new_sample();
        let reopened = repository.open(&mut reopened_app, root, &saved_base.uuid);
        assert_eq!(reopened.citations.style, "ieee");
        assert_eq!(reopened.citations.locale, "en-US");
        assert_eq!(
            reopened.citations.citations.len(),
            merged.citations.citations.len()
        );
        assert_eq!(reopened.visible_text, merged.visible_text);

        let second_pass = repository.merge(&mut merger, root, &saved_base.uuid);
        assert_eq!(second_pass.citations, merged.citations);
        assert_eq!(second_pass.visible_text, merged.visible_text);
        let _ = std::fs::remove_dir_all(root);
    }

    fn assert_footnote_update_and_reference_delete_candidate_merge(
        root: &std::path::Path,
        repository: RichMergeRepository<'_>,
    ) {
        let _ = std::fs::remove_dir_all(root);
        let mut base = OpenDocApp::new_sample();
        let base_doc = base.add_footnote_ref();
        let footnote_id = base_doc.footnotes[0].id.clone();
        let footnote_ref_id = first_inline_id(&base_doc, "footnote-ref");
        let saved_base = repository.save(&mut base, root);

        let mut current = OpenDocApp::new_sample();
        repository.open(&mut current, root, &saved_base.uuid);
        current.actor_id = "actor-a-footnote".to_string();
        current
            .update_footnote_body(&footnote_id, "Current branch footnote body")
            .unwrap();
        repository.save(&mut current, root);

        let mut candidate = OpenDocApp::new_sample();
        repository.open(&mut candidate, root, &saved_base.uuid);
        candidate.actor_id = "actor-b-footnote".to_string();
        candidate.delete_inline(&footnote_ref_id).unwrap();
        repository.save_or_candidate(&mut candidate, root);

        let mut merger = OpenDocApp::new_sample();
        let merged = repository.merge(&mut merger, root, &saved_base.uuid);
        let footnote = merged
            .footnotes
            .iter()
            .find(|footnote| footnote.id == footnote_id)
            .unwrap();
        assert!(footnote.deleted);
        assert!(footnote
            .body
            .iter()
            .any(|inline| inline.text == "Current branch footnote body"));
        assert!(!merged
            .blocks
            .iter()
            .flat_map(|block| block.content.iter())
            .any(|inline| inline.id == footnote_ref_id));
        assert!(merged
            .warnings
            .iter()
            .any(|warning| warning.code == "footnote-reference-missing"));
        assert!(merged.operations.iter().any(|operation| {
            operation.actor == "actor-a-footnote" && operation.kind == "upsert-footnote"
        }));
        assert!(merged.operations.iter().any(|operation| {
            operation.actor == "actor-b-footnote" && operation.kind == "delete-inline"
        }));

        let mut reopened_app = OpenDocApp::new_sample();
        let reopened = repository.open(&mut reopened_app, root, &saved_base.uuid);
        let reopened_footnote = reopened
            .footnotes
            .iter()
            .find(|footnote| footnote.id == footnote_id)
            .unwrap();
        assert!(reopened_footnote.deleted);
        assert!(reopened
            .warnings
            .iter()
            .any(|warning| warning.code == "footnote-reference-missing"));

        let second_pass = repository.merge(&mut merger, root, &saved_base.uuid);
        assert_eq!(second_pass.footnotes, merged.footnotes);
        assert_eq!(second_pass.warnings, merged.warnings);
        let _ = std::fs::remove_dir_all(root);
    }

    fn assert_concurrent_suggestion_review_candidate_merge(
        root: &std::path::Path,
        repository: RichMergeRepository<'_>,
    ) {
        let _ = std::fs::remove_dir_all(root);
        let mut base = OpenDocApp::new_sample();
        let suggestion_id = base
            .add_suggestion("Reviewer", " candidate review text")
            .unwrap()
            .suggestions
            .last()
            .unwrap()
            .id
            .clone();
        let saved_base = repository.save(&mut base, root);

        let mut current = OpenDocApp::new_sample();
        repository.open(&mut current, root, &saved_base.uuid);
        current.actor_id = "actor-a-review".to_string();
        current.accept_suggestion(&suggestion_id, "Alice").unwrap();
        repository.save(&mut current, root);

        let mut candidate = OpenDocApp::new_sample();
        repository.open(&mut candidate, root, &saved_base.uuid);
        candidate.actor_id = "actor-b-review".to_string();
        candidate
            .reject_suggestion(&suggestion_id, "Carol")
            .unwrap();
        repository.save_or_candidate(&mut candidate, root);

        let mut merger = OpenDocApp::new_sample();
        let merged = repository.merge(&mut merger, root, &saved_base.uuid);
        let suggestion = merged
            .suggestions
            .iter()
            .find(|suggestion| suggestion.id == suggestion_id)
            .unwrap();
        assert_eq!(suggestion.state, "accepted");
        assert_eq!(suggestion.provenance, ["accepted-by:Alice"]);
        assert!(merged.visible_text.contains("candidate review text"));
        assert!(merged
            .warnings
            .iter()
            .any(|warning| warning.code == "resolved-suggestion"));
        assert!(merged.operations.iter().any(|operation| {
            operation.actor == "actor-a-review" && operation.kind == "accept-suggestion"
        }));
        assert!(merged.operations.iter().any(|operation| {
            operation.actor == "actor-b-review" && operation.kind == "reject-suggestion"
        }));

        let mut reopened_app = OpenDocApp::new_sample();
        let reopened = repository.open(&mut reopened_app, root, &saved_base.uuid);
        let reopened_suggestion = reopened
            .suggestions
            .iter()
            .find(|suggestion| suggestion.id == suggestion_id)
            .unwrap();
        assert_eq!(reopened_suggestion.state, "accepted");
        assert_eq!(reopened_suggestion.provenance, ["accepted-by:Alice"]);
        assert!(reopened.visible_text.contains("candidate review text"));
        assert!(reopened
            .warnings
            .iter()
            .any(|warning| warning.code == "resolved-suggestion"));

        let second_pass = repository.merge(&mut merger, root, &saved_base.uuid);
        assert_eq!(second_pass.visible_text, merged.visible_text);
        assert_eq!(second_pass.suggestions, merged.suggestions);
        assert_eq!(second_pass.warnings, merged.warnings);
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn audit_view_reports_invalid_candidate_heads_without_blocking_open() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-invalid-candidate-audit-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        app.add_paragraph("candidate-head audit visibility");
        let saved = app.save_to_local_repository(&root).unwrap();

        let repo = Repository::new(LocalObjectStore::new(&root));
        let malformed_hash = opendoc_core::HashRef::parse("sha256:badcafe").unwrap();
        repo.store()
            .put_named(
                &opendoc_store::ObjectStoreLayout::candidate_head_key(
                    &saved.uuid,
                    SNAPSHOT_BRANCH,
                    &malformed_hash,
                )
                .unwrap(),
                b"not a branch head record",
            )
            .unwrap();

        let mut reopened = OpenDocApp::new_sample();
        let doc = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert!(doc.visible_text.contains("candidate-head audit visibility"));
        let audit = reopened.audit_view();
        assert_eq!(audit.candidate_head_problems.len(), 1);
        assert!(audit.candidate_head_problems[0]
            .reason
            .contains("InvalidMagic"));
        let _ = std::fs::remove_dir_all(root);
    }

