    #[test]
    fn flat_repository_merges_divergent_candidate_operations() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-flat-candidate-merge-{}",
            std::process::id()
        ));
        let namespace = "bucket/prefix";
        let _ = std::fs::remove_dir_all(&root);
        let mut base = OpenDocApp::new_sample();
        let saved_base = base.save_to_flat_repository(&root, namespace).unwrap();

        let mut current = OpenDocApp::new_sample();
        current
            .open_flat_projection(&root, namespace, &saved_base.uuid)
            .unwrap();
        let mut candidate = OpenDocApp::new_sample();
        candidate
            .open_flat_projection(&root, namespace, &saved_base.uuid)
            .unwrap();

        current.add_paragraph("flat current branch edit");
        let saved_current = current.save_to_flat_repository(&root, namespace).unwrap();
        candidate.add_paragraph("flat candidate branch edit");
        let saved_candidate = candidate
            .save_to_flat_repository_or_candidate(&root, namespace)
            .unwrap();
        assert_ne!(saved_candidate.last_manifest, saved_current.last_manifest);

        let repo = Repository::new(FlatObjectStore::new(&root, namespace).unwrap());
        let plans = repo
            .plan_candidate_merges(&saved_base.uuid, SNAPSHOT_BRANCH)
            .unwrap();
        assert_eq!(plans.plans.len(), 1);

        let mut merger = OpenDocApp::new_sample();
        let merged = merger
            .merge_flat_repository_candidates(&root, namespace, &saved_base.uuid)
            .unwrap();
        assert!(merged.visible_text.contains("flat current branch edit"));
        assert!(merged.visible_text.contains("flat candidate branch edit"));
        assert_ne!(merged.last_manifest, saved_current.last_manifest);
        let reopened = OpenDocApp::new_sample()
            .open_flat_projection(&root, namespace, &saved_base.uuid)
            .unwrap();
        assert_eq!(reopened.visible_text, merged.visible_text);
        let _ = std::fs::remove_dir_all(root);
    }

