    #[test]
    fn local_repository_merges_divergent_spreadsheet_candidate_operations() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-spreadsheet-candidate-merge-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut base = OpenDocApp::new_sample();
        let saved_base = base.save_to_local_repository(&root).unwrap();

        let mut current = OpenDocApp::new_sample();
        current
            .open_saved_projection(&root, &saved_base.uuid)
            .unwrap();
        let mut candidate = OpenDocApp::new_sample();
        candidate
            .open_saved_projection(&root, &saved_base.uuid)
            .unwrap();

        current.set_spreadsheet_cell("B2", "7").unwrap();
        current.save_to_local_repository(&root).unwrap();
        candidate.set_spreadsheet_cell("C1", "=B2+1").unwrap();
        candidate
            .set_spreadsheet_cell_format("sheet-1", "C1", "bold", "true")
            .unwrap();
        candidate
            .save_to_local_repository_or_candidate(&root)
            .unwrap();

        let mut merger = OpenDocApp::new_sample();
        let merged = merger
            .merge_local_repository_candidates(&root, &saved_base.uuid)
            .unwrap();
        let sheet = &merged.workbook.sheets[0];
        let b2 = sheet
            .cells
            .iter()
            .find(|cell| cell.address == "B2")
            .expect("B2 exists after merge");
        let c1 = sheet
            .cells
            .iter()
            .find(|cell| cell.address == "C1")
            .expect("C1 exists after merge");
        assert_eq!(b2.user_value, "7");
        assert_eq!(c1.user_value, "=B2+1");
        assert_eq!(c1.computed_value, "8");
        assert!(c1.format.bold);
        let second_pass = merger
            .merge_local_repository_candidates(&root, &saved_base.uuid)
            .unwrap();
        assert_eq!(second_pass.workbook.sheets[0].cells, sheet.cells);
        let _ = std::fs::remove_dir_all(root);
    }

