    #[test]
    fn local_repository_merges_divergent_workbook_candidate_operations() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-workbook-candidate-merge-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut base = OpenDocApp::new_sample();
        let saved_base = base.save_to_local_repository(&root).unwrap();

        let mut current = OpenDocApp::new_sample();
        current
            .open_saved_projection(&root, &saved_base.uuid)
            .unwrap();
        let mut candidate = OpenDocApp::new_sample();
        candidate
            .open_saved_projection(&root, &saved_base.uuid)
            .unwrap();

        current.set_spreadsheet_cell("B2", "9").unwrap();
        current.save_to_local_repository(&root).unwrap();
        candidate
            .set_spreadsheet_workbook_metadata("Merged Workbook", "sv-SE", "Europe/Stockholm")
            .unwrap();
        let candidate_doc = candidate.add_spreadsheet_sheet("Data").unwrap();
        let data_sheet_id = candidate_doc
            .workbook
            .sheets
            .iter()
            .find(|sheet| sheet.title == "Data")
            .map(|sheet| sheet.id.clone())
            .expect("candidate added Data sheet");
        candidate
            .set_spreadsheet_cell_in_sheet(&data_sheet_id, "A1", "=1+2")
            .unwrap();
        candidate
            .copy_spreadsheet_range("sheet-1", "B2:B3", "C2")
            .unwrap();
        candidate
            .add_spreadsheet_named_range("sheet-1", "qty", "B2:B3")
            .unwrap();
        candidate
            .save_to_local_repository_or_candidate(&root)
            .unwrap();

        let mut merger = OpenDocApp::new_sample();
        let merged = merger
            .merge_local_repository_candidates(&root, &saved_base.uuid)
            .unwrap();
        assert_eq!(merged.workbook.title, "Merged Workbook");
        assert_eq!(merged.workbook.locale, "sv-SE");
        assert_eq!(merged.workbook.timezone, "Europe/Stockholm");
        assert!(merged
            .workbook
            .sheets
            .iter()
            .any(|sheet| sheet.id == data_sheet_id && sheet.title == "Data"));
        let sheet = &merged.workbook.sheets[0];
        let copied_formula = sheet
            .cells
            .iter()
            .find(|cell| cell.address == "C3")
            .expect("copied formula exists");
        assert_eq!(copied_formula.user_value, "=SUM(C2:C2)");
        assert_eq!(copied_formula.computed_value, "9");
        assert!(merged
            .workbook
            .named_ranges
            .iter()
            .any(|range| range.name == "QTY" && range.range == "B2:B3"));
        let data_sheet = merged
            .workbook
            .sheets
            .iter()
            .find(|sheet| sheet.id == data_sheet_id)
            .unwrap();
        assert_eq!(
            data_sheet
                .cells
                .iter()
                .find(|cell| cell.address == "A1")
                .unwrap()
                .computed_value,
            "3"
        );
        let _ = std::fs::remove_dir_all(root);
    }

