    #[test]
    fn local_repository_merges_racing_sheet_deletes_into_openable_workbook() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-sheet-delete-candidate-merge-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut base = OpenDocApp::new_sample();
        let base_doc = base.add_spreadsheet_sheet("Data").unwrap();
        let data_sheet_id = base_doc.workbook.sheets[1].id.clone();
        base.add_spreadsheet_named_range(&data_sheet_id, "raw", "A1:A1")
            .unwrap();
        let saved_base = base.save_to_local_repository(&root).unwrap();

        let mut current = OpenDocApp::new_sample();
        current
            .open_saved_projection(&root, &saved_base.uuid)
            .unwrap();
        let mut candidate = OpenDocApp::new_sample();
        candidate
            .open_saved_projection(&root, &saved_base.uuid)
            .unwrap();

        current.delete_spreadsheet_sheet("sheet-1").unwrap();
        current.save_to_local_repository(&root).unwrap();
        candidate.delete_spreadsheet_sheet(&data_sheet_id).unwrap();
        candidate
            .save_to_local_repository_or_candidate(&root)
            .unwrap();

        let mut merger = OpenDocApp::new_sample();
        let merged = merger
            .merge_local_repository_candidates(&root, &saved_base.uuid)
            .unwrap();
        assert_eq!(merged.workbook.sheets.len(), 1);
        let survivor_id = merged.workbook.sheets[0].id.as_str();
        assert!(survivor_id == "sheet-1" || survivor_id == data_sheet_id);
        assert!(merged
            .workbook
            .named_ranges
            .iter()
            .all(|range| range.sheet_id == survivor_id));
        assert!(merged
            .operations
            .iter()
            .any(|operation| operation.kind == "delete-spreadsheet-sheet"));

        let second_pass = merger
            .merge_local_repository_candidates(&root, &saved_base.uuid)
            .unwrap();
        assert_eq!(second_pass.workbook.sheets, merged.workbook.sheets);
        assert_eq!(
            second_pass.workbook.named_ranges,
            merged.workbook.named_ranges
        );
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn local_repository_writes_uuid_and_doi_lookup_records() {
        let root =
            std::env::temp_dir().join(format!("opendoc-app-api-lookup-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let with_doi = app.set_document_doi("10.1234/OpenDoc.Lookup").unwrap();
        assert_eq!(with_doi.doi.as_deref(), Some("10.1234/OpenDoc.Lookup"));
        let saved = app.save_to_local_repository(&root).unwrap();
        let repo = Repository::new(LocalObjectStore::new(&root));
        let uuid_lookup = repo
            .read_uuid_lookup(&saved.uuid)
            .unwrap()
            .expect("uuid lookup exists");
        assert_eq!(uuid_lookup.document_uuid, saved.uuid);
        assert_eq!(
            uuid_lookup.aliases,
            vec![LookupAliasRecord {
                scheme: "doi".to_string(),
                value: "10.1234/OpenDoc.Lookup".to_string(),
            }]
        );
        let doi_lookup = repo
            .read_doi_lookup("10.1234/opendoc.lookup")
            .unwrap()
            .expect("doi lookup is case-insensitive");
        assert_eq!(
            doi_lookup.manifest.to_string(),
            saved.last_manifest.unwrap()
        );
        let mut upper_scheme_lookup = uuid_lookup.clone();
        upper_scheme_lookup.aliases[0].scheme = "DOI".to_string();
        repo.write_lookup_record(&upper_scheme_lookup).unwrap();
        let padded_scheme_doi_lookup = repo
            .read_doi_lookup(" 10.1234/opendoc.lookup ")
            .unwrap()
            .expect("doi lookup normalizes padded query and uppercase DOI schemes");
        assert_eq!(padded_scheme_doi_lookup.aliases[0].scheme, "DOI");

        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened
            .open_saved_projection_by_doi(&root, " 10.1234/opendoc.lookup ")
            .unwrap();
        assert_eq!(opened.uuid, saved.uuid);
        assert_eq!(opened.doi.as_deref(), Some("10.1234/OpenDoc.Lookup"));
        assert!(!opened
            .warnings
            .iter()
            .any(|warning| warning.code == "doi-lookup-scan-fallback"));
        std::fs::remove_file(root.join(
            opendoc_store::ObjectStoreLayout::doi_lookup_key("10.1234/opendoc.lookup").unwrap(),
        ))
        .unwrap();
        repo.store()
            .put_named("indexes/by-uuid/zz/corrupt.idx", b"not a lookup record")
            .unwrap();
        let mut reopened_by_scan = OpenDocApp::new_sample();
        let opened_by_scan = reopened_by_scan
            .open_saved_projection_by_doi(&root, "10.1234/opendoc.lookup")
            .unwrap();
        assert_eq!(opened_by_scan.uuid, saved.uuid);
        assert!(opened_by_scan
            .warnings
            .iter()
            .any(|warning| warning.code == "doi-lookup-scan-fallback"));
        assert!(opened_by_scan.warnings.iter().any(|warning| {
            warning.code == "doi-lookup-scan-problem" && warning.message.contains("InvalidMagic")
        }));

        let mut wrong_app = OpenDocApp::new_sample();
        let wrong_saved = wrong_app.set_document_doi("10.9999/Wrong.Lookup").unwrap();
        assert_eq!(wrong_saved.doi.as_deref(), Some("10.9999/Wrong.Lookup"));
        let wrong_saved = wrong_app.save_to_local_repository(&root).unwrap();
        let wrong_lookup = repo
            .read_uuid_lookup(&wrong_saved.uuid)
            .unwrap()
            .expect("wrong uuid lookup exists");
        repo.store()
            .put_named(
                &opendoc_store::ObjectStoreLayout::doi_lookup_key("10.1234/opendoc.lookup")
                    .unwrap(),
                &opendoc_format::encode_record(&wrong_lookup),
            )
            .unwrap();
        let mut reopened_with_stale_direct_index = OpenDocApp::new_sample();
        let opened_with_stale_direct_index = reopened_with_stale_direct_index
            .open_saved_projection_by_doi(&root, "10.1234/opendoc.lookup")
            .unwrap();
        assert_eq!(opened_with_stale_direct_index.uuid, saved.uuid);
        assert_ne!(opened_with_stale_direct_index.uuid, wrong_saved.uuid);
        assert!(opened_with_stale_direct_index
            .warnings
            .iter()
            .any(|warning| warning.code == "doi-lookup-scan-fallback"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn binary_blobs_are_manifest_referenced_and_missing_blobs_warn_on_open() {
        let root =
            std::env::temp_dir().join(format!("opendoc-app-api-blobs-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let with_blob = app
            .add_binary_blob("figure.png", "image/png", b"fake-png-bytes".to_vec())
            .unwrap();
        assert_eq!(with_blob.blobs.len(), 1);
        assert!(with_blob.blobs[0].available);
        let blob_hash = opendoc_core::HashRef::parse(&with_blob.blobs[0].hash).unwrap();

        let saved = app.save_to_local_repository(&root).unwrap();
        let manifest_hash =
            opendoc_core::HashRef::parse(saved.last_manifest.as_deref().unwrap()).unwrap();
        let repo = Repository::new(LocalObjectStore::new(&root));
        let manifest = repo
            .read_manifest(&manifest_hash)
            .unwrap()
            .expect("manifest exists");
        assert_eq!(manifest.blobs, vec![blob_hash.clone()]);
        assert!(repo.store().exists(&blob_hash).unwrap());
        repo.write_tombstone(&opendoc_format::TombstoneRecord {
            object: blob_hash.clone(),
            archive_locator: "tape://pool-7/slot-42/figure.png".to_string(),
            restore_hint: "request archive recall for figure.png".to_string(),
            created_at_ms: 1234,
            signer: "archive-indexer".to_string(),
            signature: b"archive-index-signature".to_vec(),
        })
        .unwrap();

        let blob_path = root
            .join("objects")
            .join(blob_hash.algorithm())
            .join(&blob_hash.digest()[..2])
            .join(blob_hash.digest());
        std::fs::remove_file(blob_path).unwrap();

        let mut shallow = OpenDocApp::new_sample();
        let opened = shallow.open_saved_projection(&root, &saved.uuid).unwrap();
        assert_eq!(opened.blobs.len(), 1);
        assert!(!opened.blobs[0].available);
        let tombstone = opened.blobs[0]
            .archive_tombstone
            .as_ref()
            .expect("missing blob exposes archive tombstone");
        assert_eq!(
            tombstone.archive_locator,
            "tape://pool-7/slot-42/figure.png"
        );
        assert_eq!(tombstone.signer, "archive-indexer");
        let audit = shallow.audit_view();
        assert!(audit.blob_signatures.iter().any(|blob| blob
            .archive_tombstone
            .as_ref()
            .is_some_and(|tombstone| tombstone.restore_hint.contains("archive recall"))));
        assert!(opened
            .warnings
            .iter()
            .any(|warning| warning.code == "missing-blob"));
        assert!(opened.visible_text.contains("OpenDoc editing surface"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn shallow_clone_simulation_preserves_blob_refs_signatures_and_tombstones() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-shallow-sim-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let with_blob = app
            .add_binary_blob(
                "signed-shallow.fastq",
                "text/x-fastq",
                b"@read-1\nACGT\n+\n!!!!\n".to_vec(),
            )
            .unwrap();
        let blob_hash = with_blob.blobs[0].hash.clone();
        app.sign_blob_with_openssh_private_key(&blob_hash, TEST_ED25519_PRIVATE_KEY, "Blob Signer")
            .unwrap();
        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Version Signer")
            .unwrap();
        app.save_to_local_repository(&root).unwrap();
        app.record_blob_archive_tombstone(
            &blob_hash,
            "tape://pool/a/signed-shallow.fastq",
            "recall signed shallow FASTQ",
            "archive-indexer",
            b"archive-signature".to_vec(),
        )
        .unwrap();

        let shallow = app.simulate_shallow_clone();
        assert!(shallow.is_open);
        assert_eq!(shallow.blobs.len(), 1);
        assert!(!shallow.blobs[0].available);
        assert_eq!(shallow.blobs[0].signature_state, "signed");
        assert_eq!(shallow.signature_state, "signed");
        assert!(shallow.blobs[0].archive_tombstone.is_some());
        assert!(shallow
            .warnings
            .iter()
            .any(|warning| warning.code == "missing-blob"));
        assert!(app.blob_bytes.is_empty());
        let audit = app.audit_view();
        assert!(audit
            .blob_signatures
            .iter()
            .any(|entry| entry.blob_hash == blob_hash && entry.archive_tombstone.is_some()));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn flat_binary_blobs_missing_on_open_expose_archive_tombstones() {
        let root =
            std::env::temp_dir().join(format!("opendoc-app-api-flat-blobs-{}", std::process::id()));
        let namespace = "bucket/shallow";
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let with_blob = app
            .add_binary_blob("flat-figure.png", "image/png", b"flat-png-bytes".to_vec())
            .unwrap();
        let blob_hash = opendoc_core::HashRef::parse(&with_blob.blobs[0].hash).unwrap();

        let saved = app.save_to_flat_repository(&root, namespace).unwrap();
        let repo = Repository::new(FlatObjectStore::new(&root, namespace).unwrap());
        repo.write_tombstone(&opendoc_format::TombstoneRecord {
            object: blob_hash.clone(),
            archive_locator: "tape://flat-pool/slot-9/flat-figure.png".to_string(),
            restore_hint: "request flat archive recall for figure".to_string(),
            created_at_ms: 4321,
            signer: "flat-archive-indexer".to_string(),
            signature: b"flat-archive-index-signature".to_vec(),
        })
        .unwrap();

        let blob_path = root
            .join(namespace)
            .join(opendoc_store::ObjectStoreLayout::object_key(&blob_hash));
        std::fs::remove_file(blob_path).unwrap();

        let mut shallow = OpenDocApp::new_sample();
        let opened = shallow
            .open_flat_projection(&root, namespace, &saved.uuid)
            .unwrap();
        assert_eq!(opened.repository_backend.as_deref(), Some("flat"));
        assert_eq!(opened.repository_namespace.as_deref(), Some(namespace));
        assert_eq!(opened.blobs.len(), 1);
        assert!(!opened.blobs[0].available);
        let tombstone = opened.blobs[0]
            .archive_tombstone
            .as_ref()
            .expect("flat missing blob exposes archive tombstone");
        assert_eq!(
            tombstone.archive_locator,
            "tape://flat-pool/slot-9/flat-figure.png"
        );
        assert_eq!(tombstone.signer, "flat-archive-indexer");
        assert!(opened
            .warnings
            .iter()
            .any(|warning| warning.code == "missing-blob"
                && warning.message.contains("flat-figure.png")));

        let audit = shallow.audit_view();
        assert!(audit.blob_signatures.iter().any(|blob| blob
            .archive_tombstone
            .as_ref()
            .is_some_and(|tombstone| tombstone.restore_hint.contains("flat archive recall"))));
        assert!(audit.repository_tombstone_problems.is_empty());
        assert!(audit.repository_tombstones.iter().any(|entry| {
            entry.blob_hash == blob_hash.to_string()
                && entry.attached_to_blob_ref
                && entry.archive_tombstone.signer == "flat-archive-indexer"
        }));
        assert!(opened.visible_text.contains("OpenDoc editing surface"));
        let _ = std::fs::remove_dir_all(root);
    }

