    #[test]
    fn google_docs_app_export_import_preserves_comments_and_suggestions() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-google-docs-review-extension-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        app.add_comment("Reviewer", "Exported review comment")
            .unwrap();
        app.add_suggestion("Reviewer", "Exported review suggestion")
            .unwrap();

        let exported = app.export_google_docs_json_text().unwrap();
        let exported_value: Value = serde_json::from_str(&exported).unwrap();
        assert!(exported_value["opendocComments"]
            .as_array()
            .is_some_and(|comments| comments.iter().any(|thread| {
                thread["comments"].as_array().is_some_and(|items| {
                    items.iter().any(|comment| {
                        comment["body"].as_array().is_some_and(|body| {
                            body.iter().any(|inline| {
                                inline["textRun"]["content"] == "Exported review comment"
                            })
                        })
                    })
                })
            })));
        assert!(exported_value["opendocSuggestions"]
            .as_array()
            .is_some_and(|suggestions| suggestions.iter().any(|suggestion| {
                suggestion["author"] == "Reviewer"
                    && suggestion["kind"]["type"] == "insert"
                    && suggestion["kind"]["content"]
                        .as_array()
                        .is_some_and(|content| {
                            content.iter().any(|inline| {
                                inline["textRun"]["content"] == "Exported review suggestion"
                            })
                        })
            })));

        let mut imported = OpenDocApp::new_sample();
        let imported_doc = imported
            .import_google_docs_json_text("Imported review metadata", &exported)
            .unwrap();
        assert!(imported_doc.comments.iter().any(|thread| {
            thread
                .comments
                .iter()
                .any(|comment| comment.body == "Exported review comment")
        }));
        assert!(imported_doc
            .suggestions
            .iter()
            .any(|suggestion| suggestion.author == "Reviewer"
                && suggestion.text == "Exported review suggestion"));

        let saved = imported.save_to_local_repository(&root).unwrap();
        let reopened = OpenDocApp::new_sample()
            .open_saved_projection(&root, &saved.uuid)
            .unwrap();
        assert!(reopened.comments.iter().any(|thread| {
            thread
                .comments
                .iter()
                .any(|comment| comment.body == "Exported review comment")
        }));
        assert!(reopened
            .suggestions
            .iter()
            .any(|suggestion| suggestion.author == "Reviewer"
                && suggestion.text == "Exported review suggestion"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn malformed_google_docs_review_metadata_does_not_replace_current_document() {
        let mut app = OpenDocApp::new_sample();
        app.set_document_title("Current before malformed review import")
            .unwrap();
        app.add_paragraph("Current body must survive malformed review metadata");
        let before = app.document();

        let malformed_cases = [
            (
                "Bad comments collection",
                r#"{
                    "opendocComments": {},
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "opendocComments must be an array",
            ),
            (
                "Bad suggestions collection",
                r#"{
                    "opendocSuggestions": {},
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "opendocSuggestions must be an array",
            ),
            (
                "Bad comment thread",
                r#"{
                    "opendocComments": ["bad"],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "comment thread must be an object",
            ),
            (
                "Bad comment",
                r#"{
                    "opendocComments": [{ "id": "thread-one", "comments": ["bad"] }],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "comment must be an object",
            ),
            (
                "Bad comment timestamp",
                r#"{
                    "opendocComments": [{
                        "id": "thread-one",
                        "comments": [{
                            "id": "comment-one",
                            "author": "Ada",
                            "body": [{ "textRun": { "content": "Body", "textStyle": {} } }],
                            "createdAtMs": "17"
                        }]
                    }],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "createdAtMs must be a non-negative integer",
            ),
            (
                "Bad comment deleted flag",
                r#"{
                    "opendocComments": [{
                        "id": "thread-one",
                        "deleted": "false",
                        "comments": [{
                            "id": "comment-one",
                            "author": "Ada",
                            "body": [{ "textRun": { "content": "Body", "textStyle": {} } }]
                        }]
                    }],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "deleted must be a boolean",
            ),
            (
                "Bad comment author",
                r#"{
                    "opendocComments": [{
                        "id": "thread-one",
                        "comments": [{
                            "id": "comment-one",
                            "author": 7,
                            "body": [{ "textRun": { "content": "Body", "textStyle": {} } }]
                        }]
                    }],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "comment missing required string field author",
            ),
            (
                "Padded comment author",
                r#"{
                    "opendocComments": [{
                        "id": "thread-one",
                        "comments": [{
                            "id": "comment-one",
                            "author": " Ada ",
                            "body": [{ "textRun": { "content": "Body", "textStyle": {} } }]
                        }]
                    }],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "comment author has surrounding whitespace",
            ),
            (
                "Bad comment anchor",
                r#"{
                    "opendocComments": [{
                        "id": "thread-one",
                        "anchor": "bad",
                        "comments": [{
                            "id": "comment-one",
                            "author": "Ada",
                            "body": [{ "textRun": { "content": "Body", "textStyle": {} } }]
                        }]
                    }],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "anchor must be an object",
            ),
            (
                "Padded nearest-block warning",
                r#"{
                    "opendocComments": [{
                        "id": "thread-one",
                        "anchor": {
                            "type": "nearestBlock",
                            "blockId": "block-one",
                            "warning": " imported degraded anchor "
                        },
                        "comments": [{
                            "id": "comment-one",
                            "author": "Ada",
                            "body": [{ "textRun": { "content": "Body", "textStyle": {} } }]
                        }]
                    }],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "nearest block anchor warning has surrounding whitespace",
            ),
            (
                "Bad suggestion",
                r#"{
                    "opendocSuggestions": ["bad"],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "suggestion must be an object",
            ),
            (
                "Bad suggestion provenance",
                r#"{
                    "opendocSuggestions": [{
                        "id": "suggest-one",
                        "author": "Grace",
                        "kind": { "type": "delete", "range": { "start": "text-start", "end": "text-end" } },
                        "provenance": ["ok", 7]
                    }],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "suggestion provenance entries must be strings",
            ),
            (
                "Padded suggestion provenance",
                r#"{
                    "opendocSuggestions": [{
                        "id": "suggest-one",
                        "author": "Grace",
                        "kind": { "type": "delete", "range": { "start": "text-start", "end": "text-end" } },
                        "provenance": [" imported "]
                    }],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "suggestion provenance entry has surrounding whitespace",
            ),
            (
                "Bad suggestion author",
                r#"{
                    "opendocSuggestions": [{
                        "id": "suggest-one",
                        "author": 7,
                        "kind": { "type": "delete", "range": { "start": "text-start", "end": "text-end" } }
                    }],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "suggestion missing required string field author",
            ),
            (
                "Padded suggestion author",
                r#"{
                    "opendocSuggestions": [{
                        "id": "suggest-one",
                        "author": " Grace ",
                        "kind": { "type": "delete", "range": { "start": "text-start", "end": "text-end" } }
                    }],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "suggestion author has surrounding whitespace",
            ),
            (
                "Bad suggestion kind",
                r#"{
                    "opendocSuggestions": [{
                        "id": "suggest-one",
                        "author": "Grace",
                        "kind": "delete"
                    }],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "suggestion kind must be an object",
            ),
            (
                "Bad suggestion state type",
                r#"{
                    "opendocSuggestions": [{
                        "id": "suggest-one",
                        "author": "Grace",
                        "kind": { "type": "delete", "range": { "start": "text-start", "end": "text-end" } },
                        "state": 7
                    }],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "state must be a string",
            ),
            (
                "Bad suggestion state",
                r#"{
                    "opendocSuggestions": [{
                        "id": "suggest-one",
                        "author": "Grace",
                        "kind": { "type": "delete", "range": { "start": "text-start", "end": "text-end" } },
                        "state": "resolved"
                    }],
                    "body": { "content": [{ "paragraph": { "elements": [{ "textRun": { "content": "Replacement\n", "textStyle": {} } }] } }] }
                }"#,
                "unsupported suggestion state resolved",
            ),
        ];

        for (title, json_text, expected) in malformed_cases {
            let err = app
                .import_google_docs_json_text(title, json_text)
                .unwrap_err()
                .to_string();

            assert!(err.contains(expected), "{title}: {err}");
            assert_eq!(app.document(), before, "{title}");
        }

        let err = app
            .import_google_docs_json_text(
                "Duplicate comment import",
                r#"{
                    "opendocComments": [{
                        "id": "thread-duplicate",
                        "comments": [{
                            "id": "comment-one",
                            "author": "Contract Reviewer",
                            "body": [{ "textRun": { "content": "First comment" } }],
                            "deleted": false
                        }],
                        "deleted": false
                    }, {
                        "id": "thread-duplicate",
                        "comments": [{
                            "id": "comment-two",
                            "author": "Contract Reviewer",
                            "body": [{ "textRun": { "content": "Second comment" } }],
                            "deleted": false
                        }],
                        "deleted": false
                    }],
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{
                                    "textRun": {
                                        "content": "Duplicate comment replacement\n",
                                        "textStyle": {}
                                    }
                                }]
                            }
                        }]
                    }
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(err.contains("duplicate comment thread id"), "{err}");
        assert_eq!(app.document(), before);

        let err = app
            .import_google_docs_json_text(
                "Malformed suggestion import",
                r#"{
                    "opendocSuggestions": [{
                        "id": "suggest-malformed",
                        "author": "Contract Reviewer",
                        "kind": {
                            "type": "resolve",
                            "range": { "start": "text-start", "end": "text-end" }
                        },
                        "state": "proposed"
                    }],
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{
                                    "textRun": {
                                        "content": "Malformed suggestion replacement\n",
                                        "textStyle": {}
                                    }
                                }]
                            }
                        }]
                    }
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(err.contains("unsupported suggestion kind resolve"), "{err}");
        assert_eq!(app.document(), before);
    }

    #[test]
    fn malformed_google_docs_inline_extension_ids_do_not_replace_current_document() {
        let mut app = OpenDocApp::new_sample();
        app.set_document_title("Current before malformed inline extension import")
            .unwrap();
        app.add_paragraph("Current body must survive malformed inline extension IDs");
        let before = app.document();

        let err = app
            .import_google_docs_json_text(
                "Malformed inline extension import",
                r#"{
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{
                                    "opendocMention": {
                                        "inlineId": " ",
                                        "label": "@reviewer"
                                    }
                                }]
                            }
                        }]
                    }
                }"#,
            )
            .unwrap_err()
            .to_string();

        assert!(err.contains("empty"), "{err}");
        assert_eq!(app.document(), before);

        let err = app
            .import_google_docs_json_text(
                "Malformed citation inline extension import",
                r#"{
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{
                                    "opendocCitation": {
                                        "citationId": 7,
                                        "renderedCache": "[Bad]"
                                    }
                                }]
                            }
                        }]
                    }
                }"#,
            )
            .unwrap_err()
            .to_string();

        assert!(
            err.contains("OpenDoc citation element missing citationId"),
            "{err}"
        );
        assert_eq!(app.document(), before);

        let err = app
            .import_google_docs_json_text(
                "Malformed mention label extension import",
                r#"{
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{
                                    "opendocMention": {
                                        "inlineId": "mention-import",
                                        "label": 7
                                    }
                                }]
                            }
                        }]
                    }
                }"#,
            )
            .unwrap_err()
            .to_string();

        assert!(
            err.contains("OpenDoc mention element missing label"),
            "{err}"
        );
        assert_eq!(app.document(), before);

        let err = app
            .import_google_docs_json_text(
                "Malformed inline equation extension import",
                r#"{
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{
                                    "opendocEquation": {
                                        "inlineId": "inline-eq-import",
                                        "equationId": " ",
                                        "sourceFormat": "latex-like",
                                        "source": "x+y"
                                    }
                                }]
                            }
                        }]
                    }
                }"#,
            )
            .unwrap_err()
            .to_string();

        assert!(err.contains("empty"), "{err}");
        assert_eq!(app.document(), before);

        let err = app
            .import_google_docs_json_text(
                "Malformed inline equation source import",
                r#"{
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{
                                    "opendocEquation": {
                                        "inlineId": "inline-eq-import",
                                        "equationId": "eq-import",
                                        "sourceFormat": "latex-like",
                                        "source": 7
                                    }
                                }]
                            }
                        }]
                    }
                }"#,
            )
            .unwrap_err()
            .to_string();

        assert!(
            err.contains("OpenDoc inline equation missing source"),
            "{err}"
        );
        assert_eq!(app.document(), before);

        let err = app
            .import_google_docs_json_text(
                "Unsupported inline equation format import",
                r#"{
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{
                                    "opendocEquation": {
                                        "inlineId": "inline-eq-import",
                                        "equationId": "eq-import",
                                        "sourceFormat": "mathml",
                                        "source": "x+y"
                                    }
                                }]
                            }
                        }]
                    }
                }"#,
            )
            .unwrap_err()
            .to_string();

        assert!(
            err.contains("unsupported OpenDoc equation source format mathml"),
            "{err}"
        );
        assert_eq!(app.document(), before);

        let err = app
            .import_google_docs_json_text(
                "Malformed image extension import",
                r#"{
                    "body": {
                        "content": [{
                            "opendocImage": {
                                "blockId": " ",
                                "blobHash": "sha256:imported",
                                "altText": "Imported figure"
                            }
                        }]
                    }
                }"#,
            )
            .unwrap_err()
            .to_string();

        assert!(err.contains("empty"), "{err}");
        assert_eq!(app.document(), before);

        let err = app
            .import_google_docs_json_text(
                "Malformed block equation source import",
                r#"{
                    "body": {
                        "content": [{
                            "opendocEquationBlock": {
                                "blockId": "block-eq-import",
                                "equationId": "eq-import",
                                "sourceFormat": "latex-like",
                                "source": 7
                            }
                        }]
                    }
                }"#,
            )
            .unwrap_err()
            .to_string();

        assert!(
            err.contains("OpenDoc block equation missing source"),
            "{err}"
        );
        assert_eq!(app.document(), before);

        let err = app
            .import_google_docs_json_text(
                "Unsupported block equation format import",
                r#"{
                    "body": {
                        "content": [{
                            "opendocEquationBlock": {
                                "blockId": "block-eq-import",
                                "equationId": "eq-import",
                                "sourceFormat": "mathml",
                                "source": "x+y"
                            }
                        }]
                    }
                }"#,
            )
            .unwrap_err()
            .to_string();

        assert!(
            err.contains("unsupported OpenDoc equation source format mathml"),
            "{err}"
        );
        assert_eq!(app.document(), before);
    }

    #[test]
    fn malformed_google_docs_footnote_metadata_does_not_replace_current_document() {
        let mut app = OpenDocApp::new_sample();
        app.set_document_title("Current before malformed footnote import")
            .unwrap();
        app.add_paragraph("Current body must survive malformed footnote metadata");
        let before = app.document();

        let malformed_cases = [
            (
                "Bad footnotes object",
                r#"{
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{ "textRun": { "content": "replacement\n", "textStyle": {} } }]
                            }
                        }]
                    },
                    "footnotes": "bad"
                }"#,
                "footnotes must be an object",
            ),
            (
                "Bad footnote object",
                r#"{
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{ "textRun": { "content": "replacement\n", "textStyle": {} } }]
                            }
                        }]
                    },
                    "footnotes": { "fn-1": "bad" }
                }"#,
                "footnote must be an object",
            ),
            (
                "Bad footnote id",
                r#"{
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{ "textRun": { "content": "replacement\n", "textStyle": {} } }]
                            }
                        }]
                    },
                    "footnotes": {
                        "fn-1": { "footnoteId": 7, "content": [] }
                    }
                }"#,
                "footnoteId must be a string",
            ),
            (
                "Bad footnote content",
                r#"{
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{ "textRun": { "content": "replacement\n", "textStyle": {} } }]
                            }
                        }]
                    },
                    "footnotes": {
                        "fn-1": { "footnoteId": "fn-1", "content": "bad" }
                    }
                }"#,
                "footnote missing required array field content",
            ),
            (
                "Bad footnote content element",
                r#"{
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{ "textRun": { "content": "replacement\n", "textStyle": {} } }]
                            }
                        }]
                    },
                    "footnotes": {
                        "fn-1": { "footnoteId": "fn-1", "content": ["bad"] }
                    }
                }"#,
                "footnote content element must be an object",
            ),
            (
                "Unsupported footnote content",
                r#"{
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{ "textRun": { "content": "replacement\n", "textStyle": {} } }]
                            }
                        }]
                    },
                    "footnotes": {
                        "fn-1": { "footnoteId": "fn-1", "content": [{ "table": {} }] }
                    }
                }"#,
                "only paragraph footnote content is supported",
            ),
            (
                "Bad footnote paragraph elements",
                r#"{
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{ "textRun": { "content": "replacement\n", "textStyle": {} } }]
                            }
                        }]
                    },
                    "footnotes": {
                        "fn-1": { "footnoteId": "fn-1", "content": [{ "paragraph": {} }] }
                    }
                }"#,
                "paragraph.elements must be an array",
            ),
        ];

        for (title, json_text, expected) in malformed_cases {
            let err = app
                .import_google_docs_json_text(title, json_text)
                .unwrap_err()
                .to_string();

            assert!(err.contains(expected), "{title}: {err}");
            assert_eq!(app.document(), before, "{title}");
        }

        let err = app
            .import_google_docs_json_text(
                "Duplicate footnote import",
                r#"{
                    "body": {
                        "content": [{
                            "paragraph": {
                                "elements": [{
                                    "textRun": {
                                        "content": "Duplicate footnote replacement\n",
                                        "textStyle": {}
                                    }
                                }]
                            }
                        }]
                    },
                    "footnotes": {
                        "fn-a": {
                            "footnoteId": "fn-duplicate",
                            "content": [{
                                "paragraph": {
                                    "elements": [{
                                        "textRun": {
                                            "content": "First footnote",
                                            "textStyle": {}
                                        }
                                    }]
                                }
                            }]
                        },
                        "fn-b": {
                            "footnoteId": "fn-duplicate",
                            "content": [{
                                "paragraph": {
                                    "elements": [{
                                        "textRun": {
                                            "content": "Second footnote",
                                            "textStyle": {}
                                        }
                                    }]
                                }
                            }]
                        }
                    }
                }"#,
            )
            .unwrap_err()
            .to_string();

        assert!(err.contains("duplicate footnote id"), "{err}");
        assert_eq!(app.document(), before);
    }

    #[test]
    fn malformed_google_docs_paragraph_metadata_does_not_replace_current_document() {
        let mut app = OpenDocApp::new_sample();
        app.set_document_title("Current before malformed paragraph import")
            .unwrap();
        app.add_paragraph("Current body must survive malformed paragraph metadata");
        let before = app.document();

        let cases = [
            (
                "Bad paragraph style",
                r#"{
                    "body": { "content": [{
                        "paragraph": {
                            "paragraphStyle": "bad",
                            "elements": [{ "textRun": { "content": "replacement\n", "textStyle": {} } }]
                        }
                    }] }
                }"#,
                "paragraphStyle must be an object",
            ),
            (
                "Bad named style",
                r#"{
                    "body": { "content": [{
                        "paragraph": {
                            "paragraphStyle": { "namedStyleType": 7 },
                            "elements": [{ "textRun": { "content": "replacement\n", "textStyle": {} } }]
                        }
                    }] }
                }"#,
                "namedStyleType must be a string",
            ),
            (
                "Bad paragraph elements",
                r#"{
                    "body": { "content": [{
                        "paragraph": { "elements": {} }
                    }] }
                }"#,
                "paragraph.elements must be an array",
            ),
            (
                "Bad text style",
                r#"{
                    "body": { "content": [{
                        "paragraph": {
                            "elements": [{
                                "textRun": {
                                    "content": "replacement\n",
                                    "textStyle": "linked"
                                }
                            }]
                        }
                    }] }
                }"#,
                "textStyle must be an object",
            ),
            (
                "Bad link style",
                r#"{
                    "body": { "content": [{
                        "paragraph": {
                            "elements": [{
                                "textRun": {
                                    "content": "replacement\n",
                                    "textStyle": { "link": [] }
                                }
                            }]
                        }
                    }] }
                }"#,
                "link must be an object",
            ),
            (
                "Bad link URL",
                r#"{
                    "body": { "content": [{
                        "paragraph": {
                            "elements": [{
                                "textRun": {
                                    "content": "replacement\n",
                                    "textStyle": { "link": { "url": 7 } }
                                }
                            }]
                        }
                    }] }
                }"#,
                "url must be a string",
            ),
            (
                "Empty link URL",
                r#"{
                    "body": { "content": [{
                        "paragraph": {
                            "elements": [{
                                "textRun": {
                                    "content": "replacement\n",
                                    "textStyle": { "link": { "url": " " } }
                                }
                            }]
                        }
                    }] }
                }"#,
                "Google Docs link url is empty",
            ),
            (
                "Unsupported paragraph element",
                r#"{
                    "body": { "content": [{
                        "paragraph": {
                            "elements": [{ "person": { "personId": "p1" } }]
                        }
                    }] }
                }"#,
                "unsupported high-risk Google Docs paragraph element",
            ),
            (
                "Bad bullet",
                r#"{
                    "body": { "content": [{
                        "paragraph": {
                            "bullet": "bad",
                            "elements": [{ "textRun": { "content": "replacement\n", "textStyle": {} } }]
                        }
                    }] }
                }"#,
                "bullet must be an object",
            ),
            (
                "Bad list id",
                r#"{
                    "body": { "content": [{
                        "paragraph": {
                            "bullet": { "listId": 7 },
                            "elements": [{ "textRun": { "content": "replacement\n", "textStyle": {} } }]
                        }
                    }] }
                }"#,
                "listId must be a string",
            ),
            (
                "Bad nesting level",
                r#"{
                    "body": { "content": [{
                        "paragraph": {
                            "bullet": { "nestingLevel": "2" },
                            "elements": [{ "textRun": { "content": "replacement\n", "textStyle": {} } }]
                        }
                    }] }
                }"#,
                "nestingLevel must be a non-negative integer",
            ),
            (
                "Unsupported nesting level",
                r#"{
                    "body": { "content": [{
                        "paragraph": {
                            "bullet": { "nestingLevel": 9 },
                            "elements": [{ "textRun": { "content": "replacement\n", "textStyle": {} } }]
                        }
                    }] }
                }"#,
                "nestingLevel is outside 0..=8",
            ),
            (
                "Bad ordered flag",
                r#"{
                    "body": { "content": [{
                        "paragraph": {
                            "bullet": { "ordered": "true" },
                            "elements": [{ "textRun": { "content": "replacement\n", "textStyle": {} } }]
                        }
                    }] }
                }"#,
                "ordered must be a boolean",
            ),
            (
                "Mixed page break",
                r#"{
                    "body": { "content": [{
                        "paragraph": {
                            "elements": [
                                { "textRun": { "content": "Before" } },
                                { "pageBreak": {} }
                            ]
                        }
                    }] }
                }"#,
                "mixed Google Docs page break paragraph is unsupported",
            ),
        ];

        for (title, json_text, expected) in cases {
            let err = app
                .import_google_docs_json_text(title, json_text)
                .unwrap_err()
                .to_string();

            assert!(err.contains(expected), "{title}: {err}");
            assert_eq!(app.document(), before, "{title}");
        }
    }

    #[test]
    fn malformed_google_docs_structural_metadata_does_not_replace_current_document() {
        let mut app = OpenDocApp::new_sample();
        app.set_document_title("Current before malformed structural import")
            .unwrap();
        app.add_paragraph("Current body must survive malformed structural metadata");
        let before = app.document();

        let cases = [
            (
                "Missing body content",
                r#"{ "body": {} }"#,
                "missing body.content array",
            ),
            (
                "Bad body content",
                r#"{ "body": { "content": {} } }"#,
                "missing body.content array",
            ),
            (
                "Bad structural element",
                r#"{
                    "body": { "content": ["bad"] }
                }"#,
                "unsupported high-risk Google Docs structural element",
            ),
            (
                "Unknown structural element",
                r#"{
                    "body": { "content": [{ "person": { "personId": "p1" } }] }
                }"#,
                "unsupported high-risk Google Docs structural element",
            ),
            (
                "Bad table",
                r#"{
                    "body": { "content": [{ "table": {} }] }
                }"#,
                "malformed Google Docs table",
            ),
            (
                "Bad table row",
                r#"{
                    "body": { "content": [{
                        "table": { "tableRows": [{ "tableCells": {} }] }
                    }] }
                }"#,
                "malformed Google Docs table row",
            ),
            (
                "Bad table cell",
                r#"{
                    "body": { "content": [{
                        "table": { "tableRows": [{ "tableCells": [{ "content": {} }] }] }
                    }] }
                }"#,
                "malformed Google Docs table cell",
            ),
            (
                "Nested table",
                r#"{
                    "body": { "content": [{
                        "table": {
                            "tableRows": [{
                                "tableCells": [{
                                    "content": [{ "table": { "tableRows": [] } }]
                                }]
                            }]
                        }
                    }] }
                }"#,
                "nested Google Docs tables are unsupported",
            ),
        ];

        for (title, json_text, expected) in cases {
            let err = app
                .import_google_docs_json_text(title, json_text)
                .unwrap_err()
                .to_string();

            assert!(err.contains(expected), "{title}: {err}");
            assert_eq!(app.document(), before, "{title}");
        }
    }

    #[test]
    fn google_docs_table_import_has_stable_row_cell_ids_and_persists() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-google-docs-table-import-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let imported = app
            .import_google_docs_json_text(
                "Google table import",
                r#"{
                    "body": {
                        "content": [{
                            "table": {
                                "tableRows": [{
                                    "tableCells": [{
                                        "content": [{
                                            "paragraph": {
                                                "elements": [{
                                                    "textRun": {
                                                        "content": "A1",
                                                        "textStyle": {}
                                                    }
                                                }]
                                            }
                                        }]
                                    }, {
                                        "content": [{
                                            "paragraph": {
                                                "elements": [{
                                                    "textRun": {
                                                        "content": "B1",
                                                        "textStyle": {}
                                                    }
                                                }]
                                            }
                                        }]
                                    }]
                                }]
                            }
                        }]
                    }
                }"#,
            )
            .unwrap();
        let table = imported
            .blocks
            .iter()
            .find(|block| block.kind == "table")
            .expect("Google Docs table imports as table block");
        assert_eq!(table.rows.len(), 1);
        assert_eq!(table.row_ids.len(), 1);
        assert_eq!(table.rows[0].len(), 2);
        assert_eq!(table.cell_ids[0].len(), 2);
        assert_ne!(table.cell_ids[0][0], table.cell_ids[0][1]);
        assert!(!table.row_ids[0].trim().is_empty());
        assert!(!table.cell_ids[0][0].trim().is_empty());
        assert!(imported.visible_text.contains("A1"));
        assert!(imported.visible_text.contains("B1"));
        assert!(imported
            .operations
            .iter()
            .any(|operation| operation.kind == "import-google-docs-json"));

        let saved = app.save_to_local_repository(&root).unwrap();
        let reopened = OpenDocApp::new_sample()
            .open_saved_projection(&root, &saved.uuid)
            .unwrap();
        let reopened_table = reopened
            .blocks
            .iter()
            .find(|block| block.kind == "table")
            .expect("reopened Google Docs table");
        assert_eq!(reopened_table.row_ids, table.row_ids);
        assert_eq!(reopened_table.cell_ids, table.cell_ids);
        assert!(reopened.visible_text.contains("A1"));
        assert!(reopened.visible_text.contains("B1"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn fastq_typed_blob_signature_persists_and_verifies_after_open() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-fastq-typed-signature-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let with_blob = app
            .add_binary_blob(
                "reads.fastq",
                "text/x-fastq",
                b"@read-1\nACGT\n+\n!!!!\n".to_vec(),
            )
            .unwrap();
        let blob_hash = with_blob.blobs[0].hash.clone();
        let signed = app
            .sign_fastq_blob_with_openssh_private_key(
                &blob_hash,
                "sequence",
                TEST_ED25519_PRIVATE_KEY,
                "FASTQ Signer",
            )
            .unwrap();
        assert_eq!(signed.blobs[0].typed_signatures.len(), 1);
        assert_eq!(
            signed.blobs[0].typed_signatures[0].profile,
            "opendoc.fastq.sequence.v0"
        );
        assert_eq!(
            signed.blobs[0].typed_signatures[0].included_fields,
            vec!["read_id".to_string(), "sequence".to_string()]
        );
        assert_eq!(
            signed.blobs[0].typed_signatures[0].signature_state,
            "signed"
        );

        let saved = app.save_to_local_repository(&root).unwrap();
        let opened = OpenDocApp::new_sample()
            .open_saved_projection(&root, &saved.uuid)
            .unwrap();
        assert_eq!(
            opened.blobs[0].typed_signatures[0].signature_state,
            "signed"
        );
        assert_eq!(
            opened.blobs[0].typed_signatures[0].signature.signer_display,
            "FASTQ Signer"
        );

        let mut tampered = OpenDocApp::new_sample();
        tampered.open_saved_projection(&root, &saved.uuid).unwrap();
        tampered
            .blob_bytes
            .insert(blob_hash, b"@read-1\nAGGT\n+\n!!!!\n".to_vec());
        let projected = tampered.document();
        assert_eq!(
            projected.blobs[0].typed_signatures[0].signature_state,
            "broken"
        );
        assert!(projected
            .warnings
            .iter()
            .any(|warning| warning.code == "broken-typed-blob-signature"));

        let mut tampered = OpenDocApp::new_sample();
        tampered.open_saved_projection(&root, &saved.uuid).unwrap();
        tampered.blobs[0].typed_signatures[0].source_blob =
            "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa".to_string();
        let projected = tampered.document();
        assert_eq!(
            projected.blobs[0].typed_signatures[0].signature_state,
            "broken"
        );
        assert!(projected
            .warnings
            .iter()
            .any(|warning| warning.code == "broken-typed-blob-signature"));

        let mut tampered = OpenDocApp::new_sample();
        tampered.open_saved_projection(&root, &saved.uuid).unwrap();
        tampered.blobs[0].typed_signatures[0].signature.target =
            "sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb".to_string();
        let projected = tampered.document();
        assert_eq!(
            projected.blobs[0].typed_signatures[0].signature_state,
            "broken"
        );
        let audit = tampered.audit_view();
        assert!(audit
            .warnings
            .iter()
            .any(|warning| warning.code == "broken-typed-blob-signature"));
        let _ = std::fs::remove_dir_all(root);
    }

