    #[test]
    fn image_pixel_typed_blob_signature_persists_and_verifies_after_open() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-image-typed-signature-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let with_blob = app
            .add_binary_blob("figure.png", "image/png", b"encoded-png-bytes".to_vec())
            .unwrap();
        let blob_hash = with_blob.blobs[0].hash.clone();
        let signed = app
            .sign_image_pixels_blob_with_openssh_private_key(
                &blob_hash,
                1,
                1,
                vec![10, 20, 30, 255],
                TEST_ED25519_PRIVATE_KEY,
                "Image Signer",
            )
            .unwrap();
        assert_eq!(signed.blobs[0].typed_signatures.len(), 1);
        assert_eq!(
            signed.blobs[0].typed_signatures[0].profile,
            "opendoc.image.pixels.v0"
        );
        assert_eq!(
            signed.blobs[0].typed_signatures[0].included_fields,
            vec![
                "width".to_string(),
                "height".to_string(),
                "color_model".to_string(),
                "normalized_pixels".to_string()
            ]
        );
        assert_eq!(
            signed.blobs[0].typed_signatures[0].signature_state,
            "signed"
        );

        let saved = app.save_to_local_repository(&root).unwrap();
        let opened = OpenDocApp::new_sample()
            .open_saved_projection(&root, &saved.uuid)
            .unwrap();
        assert_eq!(
            opened.blobs[0].typed_signatures[0].signature_state,
            "signed"
        );
        assert_eq!(
            opened.blobs[0].typed_signatures[0].signature.signer_display,
            "Image Signer"
        );

        let mut tampered = opened.clone();
        let payload = tampered.blobs[0].typed_signatures[0]
            .profile_payload
            .as_mut()
            .unwrap();
        let last_pixel_byte = payload.len() - 2;
        payload[last_pixel_byte] = 31;
        let mut app = OpenDocApp::new_sample();
        app.blobs = tampered.blobs;
        app.blob_bytes
            .insert(blob_hash, b"encoded-png-bytes".to_vec());
        let projected = app.document();
        assert_eq!(
            projected.blobs[0].typed_signatures[0].signature_state,
            "broken"
        );
        let _ = std::fs::remove_dir_all(root);
    }

