        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Manifest Signer")
            .unwrap();
        app.sign_blob_with_openssh_private_key(&blob_hash, TEST_ED25519_PRIVATE_KEY, "Blob Signer")
            .unwrap();

        let updated = app
            .update_binary_blob_metadata(&blob_hash, "renamed.fastq", "text/x-fastq")
            .unwrap();
