    #[test]
    fn binary_blob_delete_removes_current_state_and_retains_history() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-blob-delete-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let added = app
            .add_binary_blob("remove.fastq", "text/x-fastq", b"@r\nAC\n+\n!!\n".to_vec())
            .unwrap();
        let blob_hash = added.blobs[0].hash.clone();
        app.sign_blob_with_openssh_private_key(&blob_hash, TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();
        app.sign_fastq_blob_with_openssh_private_key(
            &blob_hash,
            "sequence",
            TEST_ED25519_PRIVATE_KEY,
            "FASTQ Alice",
        )
        .unwrap();

        let deleted = app.delete_binary_blob(&blob_hash).unwrap();
        assert!(deleted.blobs.is_empty());
        assert!(deleted
            .operations
            .iter()
            .any(|operation| operation.kind == "delete-binary-blob"));
        assert!(matches!(
            app.delete_binary_blob(&blob_hash),
            Err(AppApiError::NotFound(message)) if message.contains("blob was not found")
        ));

        let saved = app.save_to_local_repository(&root).unwrap();
        let repo = Repository::new(LocalObjectStore::new(&root));
        let parsed_hash = opendoc_core::HashRef::parse(&blob_hash).unwrap();
        assert_eq!(
            repo.store().get(&parsed_hash).unwrap().as_deref(),
            Some(b"@r\nAC\n+\n!!\n".as_slice())
        );
        assert_eq!(
            repo.read_blob_signature(&parsed_hash)
                .unwrap()
                .unwrap()
                .signer_display,
            "Alice"
        );
        let reopened = OpenDocApp::new_sample()
            .open_saved_projection(&root, &saved.uuid)
            .unwrap();
        assert!(reopened.blobs.is_empty());
        assert!(reopened
            .operations
            .iter()
            .any(|operation| operation.kind == "add-binary-blob"));
        assert!(reopened
            .operations
            .iter()
            .any(|operation| operation.kind == "delete-binary-blob"));
        let mut reopened_app = OpenDocApp::new_sample();
        reopened_app
            .open_saved_projection(&root, &saved.uuid)
            .unwrap();
        let audit = reopened_app.audit_view();
        let deleted_blob = audit
            .blob_signatures
            .iter()
            .find(|blob| blob.blob_hash == blob_hash)
            .expect("deleted blob remains visible in audit");
        assert!(deleted_blob.deleted);
        assert_eq!(deleted_blob.blob_name, "remove.fastq");
        assert_eq!(deleted_blob.signature_state, "signed");
        assert_eq!(deleted_blob.signatures[0].signer_display, "Alice");
        assert_eq!(deleted_blob.typed_signatures.len(), 1);
        assert_eq!(
            deleted_blob.typed_signatures[0].profile,
            "opendoc.fastq.sequence.v0"
        );
        assert_eq!(deleted_blob.typed_signatures[0].signature_state, "signed");
        assert_eq!(
            deleted_blob.typed_signatures[0].signature.signer_display,
            "FASTQ Alice"
        );
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn binary_blob_restore_reactivates_deleted_audit_entry() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-blob-restore-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let added = app
            .add_binary_blob("restore.fastq", "text/x-fastq", b"@r\nAC\n+\n!!\n".to_vec())
            .unwrap();
        let blob_hash = added.blobs[0].hash.clone();
        app.sign_blob_with_openssh_private_key(&blob_hash, TEST_ED25519_PRIVATE_KEY, "Blob Alice")
            .unwrap();
        app.sign_fastq_blob_with_openssh_private_key(
            &blob_hash,
            "sequence",
            TEST_ED25519_PRIVATE_KEY,
            "FASTQ Alice",
        )
        .unwrap();

        app.delete_binary_blob(&blob_hash).unwrap();
        assert!(app.document().blobs.is_empty());
        assert!(app
            .audit_view()
            .blob_signatures
            .iter()
            .any(|blob| blob.blob_hash == blob_hash && blob.deleted));

        let restored = app.restore_binary_blob(&blob_hash).unwrap();
        let blob = restored
            .blobs
            .iter()
            .find(|blob| blob.hash == blob_hash)
            .expect("deleted blob was restored to current state");
        assert_eq!(blob.name, "restore.fastq");
        assert_eq!(blob.media_type, "text/x-fastq");
        assert!(blob.available);
        assert_eq!(blob.signature_state, "signed");
        assert_eq!(blob.signatures[0].signer_display, "Blob Alice");
        assert_eq!(blob.typed_signatures[0].signature_state, "signed");
        assert!(restored
            .operations
            .iter()
            .any(|operation| operation.kind == "restore-binary-blob"));
        assert!(!app
            .audit_view()
            .blob_signatures
            .iter()
            .any(|blob| blob.blob_hash == blob_hash && blob.deleted));

        let saved = app.save_to_local_repository(&root).unwrap();
        let reopened = OpenDocApp::new_sample()
            .open_saved_projection(&root, &saved.uuid)
            .unwrap();
        let reopened_blob = reopened
            .blobs
            .iter()
            .find(|blob| blob.hash == blob_hash)
            .expect("restored blob persisted through save/open");
        assert_eq!(reopened_blob.name, "restore.fastq");
        assert_eq!(reopened_blob.media_type, "text/x-fastq");
        assert_eq!(reopened_blob.signature_state, "signed");
        assert_eq!(reopened_blob.typed_signatures[0].signature_state, "signed");
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn app_api_records_archive_tombstones_for_current_and_deleted_blobs() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-archive-tombstone-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let first_hash = app
            .add_binary_blob(
                "current.bin",
                "application/octet-stream",
                b"current".to_vec(),
            )
            .unwrap()
            .blobs[0]
            .hash
            .clone();
        let second_hash = app
            .add_binary_blob(
                "deleted.bin",
                "application/octet-stream",
                b"deleted".to_vec(),
            )
            .unwrap()
            .blobs
            .iter()
            .find(|blob| blob.name == "deleted.bin")
            .unwrap()
            .hash
            .clone();
        let saved = app.save_to_local_repository(&root).unwrap();

        let with_current_tombstone = app
            .record_blob_archive_tombstone(
                &first_hash,
                " tape://set-a/slot-1/current.bin ",
                " request current.bin recall ",
                " archive-indexer ",
                b"current tombstone signature".to_vec(),
            )
            .unwrap();
        assert!(with_current_tombstone.blobs.iter().any(|blob| {
            blob.hash == first_hash
                && blob.archive_tombstone.as_ref().is_some_and(|tombstone| {
                    tombstone.archive_locator == "tape://set-a/slot-1/current.bin"
                        && tombstone.signer == "archive-indexer"
                })
        }));
        assert_eq!(
            with_current_tombstone
                .operations
                .last()
                .map(|operation| operation.kind.as_str()),
            Some("record-blob-archive-tombstone")
        );

        app.delete_binary_blob(&second_hash).unwrap();
        let with_deleted_tombstone = app
            .record_blob_archive_tombstone(
                &second_hash,
                " tape://set-a/slot-2/deleted.bin ",
                " request deleted.bin recall ",
                " archive-indexer ",
                b"deleted tombstone signature".to_vec(),
            )
            .unwrap();
        assert_eq!(
            with_deleted_tombstone
                .operations
                .last()
                .map(|operation| operation.kind.as_str()),
            Some("record-blob-archive-tombstone")
        );

        let saved_after_tombstones = app.save_to_local_repository(&root).unwrap();
        let orphan_hash = opendoc_core::HashRef::parse(
            "sha256:eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee",
        )
        .unwrap();
        let repo = Repository::new(LocalObjectStore::new(&root));
        repo.write_tombstone(&opendoc_format::TombstoneRecord {
            object: orphan_hash.clone(),
            archive_locator: "tape://set-a/slot-3/orphan.bin".to_string(),
            restore_hint: "request orphan.bin recall".to_string(),
            created_at_ms: 13,
            signer: "archive-indexer".to_string(),
            signature: b"orphan tombstone signature".to_vec(),
        })
        .unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened
            .open_saved_projection(&root, &saved_after_tombstones.uuid)
            .unwrap();
        assert!(opened.blobs.iter().any(|blob| {
            blob.hash == first_hash
                && blob
                    .archive_tombstone
                    .as_ref()
                    .is_some_and(|tombstone| tombstone.restore_hint == "request current.bin recall")
        }));
        let audit = reopened.audit_view();
        assert!(audit.blob_signatures.iter().any(|blob| {
            blob.blob_hash == second_hash
                && blob.deleted
                && blob.archive_tombstone.as_ref().is_some_and(|tombstone| {
                    tombstone.archive_locator == "tape://set-a/slot-2/deleted.bin"
                })
        }));
        assert!(audit.repository_tombstone_problems.is_empty());
        assert!(audit.repository_tombstones.iter().any(|entry| {
            entry.blob_hash == first_hash
                && entry.attached_to_blob_ref
                && entry.archive_tombstone.restore_hint == "request current.bin recall"
        }));
        assert!(audit.repository_tombstones.iter().any(|entry| {
            entry.blob_hash == second_hash
                && entry.attached_to_blob_ref
                && entry.archive_tombstone.restore_hint == "request deleted.bin recall"
        }));
        assert!(audit.repository_tombstones.iter().any(|entry| {
            entry.blob_hash == orphan_hash.to_string()
                && !entry.attached_to_blob_ref
                && entry.archive_tombstone.archive_locator == "tape://set-a/slot-3/orphan.bin"
        }));
        repo.store()
            .put_named(
                &opendoc_store::ObjectStoreLayout::tombstone_key(&orphan_hash),
                &opendoc_format::encode_record(&opendoc_format::TombstoneRecord {
                    object: opendoc_core::HashRef::parse(
                        "sha256:ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff",
                    )
                    .unwrap(),
                    archive_locator: "tape://set-a/slot-3/wrong.bin".to_string(),
                    restore_hint: "wrong tombstone target".to_string(),
                    created_at_ms: 14,
                    signer: "archive-indexer".to_string(),
                    signature: b"wrong tombstone signature".to_vec(),
                }),
            )
            .unwrap();
        let broken_audit = reopened.audit_view();
        assert!(broken_audit
            .repository_tombstones
            .iter()
            .any(|entry| entry.blob_hash == first_hash));
        assert!(broken_audit
            .repository_tombstones
            .iter()
            .any(|entry| entry.blob_hash == second_hash));
        assert!(!broken_audit
            .repository_tombstones
            .iter()
            .any(|entry| entry.blob_hash == orphan_hash.to_string()));
        assert!(broken_audit
            .repository_tombstone_problems
            .iter()
            .any(|problem| problem.contains("HashMismatch")));
        assert!(matches!(
            reopened.record_blob_archive_tombstone(
                "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
                "tape://missing",
                "missing",
                "archive-indexer",
                b"missing".to_vec(),
            ),
            Err(AppApiError::NotFound(message))
                if message.contains("current state or audit history")
        ));
        assert_eq!(saved.uuid, saved_after_tombstones.uuid);
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn openssh_signing_hook_signs_current_snapshot_and_clears_on_edit() {
        let mut app = OpenDocApp::new_sample();
        let signed = app
            .sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();
        assert_eq!(signed.signature_state, "signed");
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "trusted"
        );
        let inline_id = first_editable_inline_id(&app.document());
        let edited = app
            .update_inline_text(&inline_id, "mutation clears signature")
            .unwrap();
        assert_eq!(edited.signature_state, "unsigned");
        assert!(edited.visible_text.contains("mutation clears signature"));
    }

