    #[test]
    fn document_signature_verification_reports_signed_trusted_untrusted_and_broken() {
        let mut app = OpenDocApp::new_sample();
        assert_eq!(app.verify_current_signatures().unwrap(), "unsigned");

        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();
        assert_eq!(app.verify_current_signatures().unwrap(), "signed");
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "trusted"
        );
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY_ALT)
                .unwrap(),
            "untrusted"
        );

        app.document.title = "tampered title".to_string();
        assert_eq!(app.verify_current_signatures().unwrap(), "broken");
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "broken"
        );
    }

    #[test]
    fn signed_snapshot_persists_signature_sidecar() {
        let root =
            std::env::temp_dir().join(format!("opendoc-app-api-signature-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let signed = app
            .sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();
        assert_eq!(signed.signature_state, "signed");
        let signed = app
            .sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY_ALT, "Second signer")
            .unwrap();
        assert_eq!(signed.signatures.len(), 2);
        assert_ne!(signed.signatures[0].signer, signed.signatures[1].signer);
        let saved = app.save_to_local_repository(&root).unwrap();

        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert_eq!(opened.signature_state, "signed");
        assert_eq!(opened.signatures.len(), 2);
        assert_ne!(opened.signatures[0].signer, opened.signatures[1].signer);
        assert_eq!(
            opened
                .signature
                .as_ref()
                .map(|signature| signature.signer_display.as_str()),
            Some("Alice")
        );
        let audit = reopened.audit_view();
        assert_eq!(audit.signatures.len(), 2);
        assert!(audit
            .signatures
            .iter()
            .any(|signature| signature.signer_display == "Alice"));
        assert!(audit
            .signatures
            .iter()
            .any(|signature| signature.signer_display == "Second signer"));
        assert_eq!(
            reopened
                .verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "trusted"
        );
        assert_eq!(
            reopened
                .verify_current_signature(TEST_ED25519_PRIVATE_KEY_ALT)
                .unwrap(),
            "trusted"
        );
        assert_eq!(reopened.verify_current_signatures().unwrap(), "signed");
        reopened.document.title = "tampered after reopen".to_string();
        assert_eq!(reopened.verify_current_signatures().unwrap(), "broken");
        assert_eq!(
            reopened
                .verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "broken"
        );

        let mut reopened = OpenDocApp::new_sample();
        reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        let edited = reopened.add_paragraph("after signed open");
        assert_eq!(edited.signature_state, "unsigned");
        let _ = std::fs::remove_dir_all(root);
    }

