    #[test]
    fn spreadsheet_sheet_delete_beats_stale_sheet_edits_without_resurrection() {
        let mut workbook = AppSpreadsheetWorkbook::sample();
        workbook.add_sheet_with_id("sheet-scratch", "Scratch");
        let deleted_sheet = workbook
            .sheets
            .iter()
            .find(|sheet| sheet.id == "sheet-scratch")
            .unwrap()
            .clone();
        let envelope = |seq, kind: &str, summary: &str, spreadsheet| AppOperationEnvelope {
            record: AppOperationRecord {
                actor: format!("actor-{seq}"),
                seq,
                kind: kind.to_string(),
                summary: summary.to_string(),
                created_at_ms: 0,
            },
            operation: None,
            spreadsheet: Some(spreadsheet),
            blob: None,
        };

        let warnings = apply_spreadsheet_envelopes(
            &mut workbook,
            &[
                envelope(
                    1,
                    "delete-spreadsheet-sheet",
                    "delete scratch sheet",
                    AppSpreadsheetOperation::DeleteSheet {
                        sheet_id: "sheet-scratch".to_string(),
                        sheet: deleted_sheet,
                        named_ranges: Vec::new(),
                    },
                ),
                envelope(
                    2,
                    "set-spreadsheet-cell",
                    "stale scratch cell edit",
                    AppSpreadsheetOperation::SetCell {
                        sheet_id: "sheet-scratch".to_string(),
                        address: "A1".to_string(),
                        value: "stale".to_string(),
                    },
                ),
                envelope(
                    3,
                    "set-spreadsheet-cell-format",
                    "stale scratch cell format",
                    AppSpreadsheetOperation::SetCellFormat {
                        sheet_id: "sheet-scratch".to_string(),
                        address: "A1".to_string(),
                        property: "bold".to_string(),
                        value: "true".to_string(),
                    },
                ),
                envelope(
                    4,
                    "add-spreadsheet-named-range",
                    "stale scratch named range",
                    AppSpreadsheetOperation::AddNamedRange {
                        sheet_id: "sheet-scratch".to_string(),
                        name: "ScratchRange".to_string(),
                        range: "A1:A2".to_string(),
                    },
                ),
                envelope(
                    5,
                    "set-spreadsheet-basic-filter",
                    "stale scratch filter",
                    AppSpreadsheetOperation::SetBasicFilter {
                        sheet_id: "sheet-scratch".to_string(),
                        range: "A1:B3".to_string(),
                    },
                ),
            ],
        )
        .unwrap();

        assert!(workbook
            .sheets
            .iter()
            .all(|sheet| sheet.id != "sheet-scratch"));
        assert!(workbook
            .named_ranges
            .iter()
            .all(|range| range.sheet_id != "sheet-scratch"));
        assert_eq!(
            warnings
                .iter()
                .filter(|warning| warning.code == "missing-spreadsheet-sheet")
                .count(),
            4
        );
        assert!(warnings
            .iter()
            .all(|warning| warning.message.contains("sheet-scratch")));
        workbook.validate_source().unwrap();
    }

    #[test]
    fn spreadsheet_axis_delete_beats_stale_cell_edits_without_resurrection() {
        let base = AppSpreadsheetWorkbook::sample();
        let envelope =
            |actor: &str, seq, kind: &str, summary: &str, spreadsheet| AppOperationEnvelope {
                record: AppOperationRecord {
                    actor: actor.to_string(),
                    seq,
                    kind: kind.to_string(),
                    summary: summary.to_string(),
                    created_at_ms: 0,
                },
                operation: None,
                spreadsheet: Some(spreadsheet),
                blob: None,
            };
        let deletes = vec![
            envelope(
                "actor-a",
                1,
                "delete-spreadsheet-row",
                "delete row 3",
                AppSpreadsheetOperation::DeleteRow {
                    sheet_id: "sheet-1".to_string(),
                    row: "3".to_string(),
                    payload: empty_deleted_row_payload("3"),
                },
            ),
            envelope(
                "actor-a",
                2,
                "delete-spreadsheet-column",
                "delete column B",
                AppSpreadsheetOperation::DeleteColumn {
                    sheet_id: "sheet-1".to_string(),
                    column: "B".to_string(),
                    payload: empty_deleted_column_payload("B"),
                },
            ),
        ];
        let stale_edits = vec![
            envelope(
                "actor-z",
                1,
                "set-spreadsheet-cell",
                "stale row cell edit",
                AppSpreadsheetOperation::SetCell {
                    sheet_id: "sheet-1".to_string(),
                    address: "A3".to_string(),
                    value: "stale row".to_string(),
                },
            ),
            envelope(
                "actor-z",
                2,
                "set-spreadsheet-cell-format",
                "stale column cell format",
                AppSpreadsheetOperation::SetCellFormat {
                    sheet_id: "sheet-1".to_string(),
                    address: "B2".to_string(),
                    property: "bold".to_string(),
                    value: "true".to_string(),
                },
            ),
            envelope(
                "actor-z",
                3,
                "add-spreadsheet-cell-comment",
                "stale row cell comment",
                AppSpreadsheetOperation::AddCellComment {
                    sheet_id: "sheet-1".to_string(),
                    address: "A3".to_string(),
                    comment_id: "stale-row-comment".to_string(),
                    author: "Reviewer".to_string(),
                    body: "stale".to_string(),
                },
            ),
            envelope(
                "actor-z",
                4,
                "set-spreadsheet-cell-validation",
                "stale column validation",
                AppSpreadsheetOperation::SetCellValidation {
                    sheet_id: "sheet-1".to_string(),
                    address: "B2".to_string(),
                    validation: AppCellValidation::new(
                        "list",
                        vec!["yes".to_string(), "no".to_string()],
                        true,
                    )
                    .unwrap(),
                },
            ),
        ];

        let (merged, warnings) =
            merge_spreadsheet_envelope_streams(base.clone(), &[&deletes, &stale_edits]).unwrap();
        let (reversed, reversed_warnings) =
            merge_spreadsheet_envelope_streams(base, &[&stale_edits, &deletes]).unwrap();

        assert_eq!(merged, reversed);
        assert_eq!(warnings, reversed_warnings);
        let sheet = merged
            .sheets
            .iter()
            .find(|sheet| sheet.id == "sheet-1")
            .unwrap();
        assert!(!sheet.rows.iter().any(|row| row == "3"));
        assert!(!sheet.columns.iter().any(|column| column == "B"));
        assert!(sheet
            .cells
            .iter()
            .all(|cell| !cell.address.ends_with('3') && !cell.address.starts_with('B')));
        assert_eq!(
            warnings
                .iter()
                .filter(|warning| warning.code == "missing-spreadsheet-row")
                .count(),
            2
        );
        assert_eq!(
            warnings
                .iter()
                .filter(|warning| warning.code == "missing-spreadsheet-column")
                .count(),
            2
        );
        merged.validate_source().unwrap();
    }

