    #[test]
    fn spreadsheet_cells_evaluate_persist_and_clear_signatures() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-spreadsheet-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();
        let edited = app.set_spreadsheet_cell("B2", "7").unwrap();
        assert_eq!(edited.signature_state, "unsigned");
        let total = edited.workbook.sheets[0]
            .cells
            .iter()
            .find(|cell| cell.address == "B3")
            .unwrap();
        assert_eq!(total.user_value, "=SUM(B2:B2)");
        assert_eq!(total.computed_value, "7");
        assert_eq!(total.dependencies, vec!["B2"]);

        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        let reopened_total = opened.workbook.sheets[0]
            .cells
            .iter()
            .find(|cell| cell.address == "B3")
            .unwrap();
        assert_eq!(reopened_total.computed_value, "7");
        assert!(opened
            .operations
            .iter()
            .any(|operation| operation.kind == "set-spreadsheet-cell"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn spreadsheet_cell_entry_keeps_noncanonical_typed_values_as_strings() {
        let mut app = OpenDocApp::new_sample();

        let document = app
            .set_spreadsheet_cells(vec![
                ("C1".to_string(), " 7 ".to_string()),
                ("C2".to_string(), "TRUE".to_string()),
                ("C3".to_string(), " =SUM(B2:B2)".to_string()),
                ("C4".to_string(), "7".to_string()),
                ("C5".to_string(), "true".to_string()),
                ("C6".to_string(), "=SUM(B2:B2)".to_string()),
            ])
            .unwrap();
        let sheet = &document.workbook.sheets[0];

        assert_cell_source(sheet, "C1", "string", " 7 ");
        assert_cell_source(sheet, "C2", "bool", "true");
        assert_cell_source(sheet, "C3", "string", " =SUM(B2:B2)");
        assert_cell_source(sheet, "C4", "number", "7");
        assert_cell_source(sheet, "C5", "bool", "true");
        assert_cell_source(sheet, "C6", "formula", "=SUM(B2:B2)");
        assert_cell(sheet, "C1", " 7 ", "string", &[]);
        assert_cell(sheet, "C2", "true", "bool", &[]);
        assert_cell(sheet, "C3", " =SUM(B2:B2)", "string", &[]);
        assert_cell(sheet, "C4", "7", "number", &[]);
        assert_cell(sheet, "C5", "true", "bool", &[]);
        assert_cell(sheet, "C6", "5", "number", &["B2"]);
        document.validate_source().unwrap();
    }

