    #[test]
    fn spreadsheet_multiple_sheets_evaluate_and_persist() {
        let root =
            std::env::temp_dir().join(format!("opendoc-app-api-multisheet-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let with_sheet = app.add_spreadsheet_sheet("Data").unwrap();
        assert_eq!(with_sheet.workbook.sheets.len(), 2);
        let data_sheet_id = with_sheet.workbook.sheets[1].id.clone();
        assert!(data_sheet_id.starts_with("sheet-"));
        let renamed = app
            .rename_spreadsheet_sheet(&data_sheet_id, "Raw Data")
            .unwrap();
        assert_eq!(renamed.workbook.sheets[1].id, data_sheet_id);
        assert_eq!(renamed.workbook.sheets[1].title, "Raw Data");

        let edited = app
            .set_spreadsheet_cell_in_sheet(&data_sheet_id, "A1", "=1+2")
            .unwrap();
        assert_cell(&edited.workbook.sheets[1], "A1", "3", "number", &[]);
        assert!(edited
            .operations
            .iter()
            .any(|operation| operation.summary == format!("set {data_sheet_id}!A1")));
        let bulk_edited = app
            .set_spreadsheet_cells_in_sheet(
                &data_sheet_id,
                vec![
                    ("A2".to_string(), "4".to_string()),
                    ("A3".to_string(), "=A1+A2".to_string()),
                ],
            )
            .unwrap();
        assert_cell(
            &bulk_edited.workbook.sheets[1],
            "A3",
            "7",
            "number",
            &["A1", "A2"],
        );
        assert!(bulk_edited
            .operations
            .iter()
            .any(|operation| operation.summary == format!("set {data_sheet_id}!A3")));

        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert_eq!(opened.workbook.sheets.len(), 2);
        assert_eq!(opened.workbook.sheets[1].title, "Raw Data");
        assert_eq!(opened.workbook.sheets[1].id, data_sheet_id);
        assert_cell(&opened.workbook.sheets[1], "A1", "3", "number", &[]);
        assert!(opened
            .operations
            .iter()
            .any(|operation| operation.kind == "rename-spreadsheet-sheet"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn spreadsheet_sheet_add_records_canonical_title() {
        let mut app = OpenDocApp::new_sample();

        let added = app.add_spreadsheet_sheet(" ").unwrap();
        assert_eq!(added.workbook.sheets[1].title, "Sheet2");
        let sheet_id = added.workbook.sheets[1].id.clone();
        let operation = added
            .operations
            .iter()
            .rev()
            .find(|operation| operation.kind == "add-spreadsheet-sheet")
            .unwrap();
        assert_eq!(operation.summary, format!("add sheet {sheet_id}"));
        let operation_sheet_id =
            app.operation_envelopes
                .iter()
                .rev()
                .find_map(|envelope| match &envelope.spreadsheet {
                    Some(AppSpreadsheetOperation::AddSheet { sheet_id, .. }) => {
                        Some(sheet_id.as_str())
                    }
                    _ => None,
                });
        assert_eq!(operation_sheet_id, Some(sheet_id.as_str()));
        let operation_title =
            app.operation_envelopes
                .iter()
                .rev()
                .find_map(|envelope| match &envelope.spreadsheet {
                    Some(AppSpreadsheetOperation::AddSheet { title, .. }) => Some(title.as_str()),
                    _ => None,
                });
        assert_eq!(operation_title, Some("Sheet2"));

        let mut replayed_workbook = AppSpreadsheetWorkbook::sample();
        let warnings =
            apply_spreadsheet_envelopes(&mut replayed_workbook, &app.operation_envelopes).unwrap();
        assert!(warnings.is_empty());
        assert_eq!(replayed_workbook.sheets[1].title, "Sheet2");
    }

    #[test]
    fn spreadsheet_sheet_delete_removes_current_sheet_and_replays() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-sheet-delete-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let added = app.add_spreadsheet_sheet("Data").unwrap();
        let data_sheet_id = added.workbook.sheets[1].id.clone();
        app.add_spreadsheet_named_range(&data_sheet_id, "raw", "A1:A1")
            .unwrap();
        app.set_spreadsheet_cell_in_sheet(&data_sheet_id, "A1", "13")
            .unwrap();

        let deleted = app.delete_spreadsheet_sheet(&data_sheet_id).unwrap();
        assert_eq!(deleted.workbook.sheets.len(), 1);
        assert!(!deleted
            .workbook
            .sheets
            .iter()
            .any(|sheet| sheet.id == data_sheet_id));
        assert!(deleted.workbook.named_ranges.is_empty());
        assert!(deleted
            .operations
            .iter()
            .any(|operation| operation.kind == "delete-spreadsheet-sheet"));
        let audit = app.audit_view();
        assert!(audit.deleted_sheets.iter().any(|entry| {
            entry.sheet_id == data_sheet_id
                && entry.operation.kind == "delete-spreadsheet-sheet"
                && entry
                    .operation
                    .summary
                    .contains(&format!("delete sheet {data_sheet_id}"))
        }));
        let (_, retained_named_ranges) = app
            .deleted_sheet_restore_payload(&data_sheet_id)
            .expect("deleted sheet restore payload is retained before save");
        assert!(retained_named_ranges
            .iter()
            .any(|range| range.name == "RAW"));

        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert_eq!(opened.workbook.sheets.len(), 1);
        assert!(!opened
            .workbook
            .sheets
            .iter()
            .any(|sheet| sheet.id == data_sheet_id));
        assert!(opened.workbook.named_ranges.is_empty());
        let reopened_audit = reopened.audit_view();
        assert!(reopened_audit
            .deleted_sheets
            .iter()
            .any(|entry| entry.sheet_id == data_sheet_id));
        let (_, reopened_named_ranges) = reopened
            .deleted_sheet_restore_payload(&data_sheet_id)
            .expect("deleted sheet restore payload is retained after open");
        assert!(reopened_named_ranges
            .iter()
            .any(|range| range.name == "RAW"));

        let restored = reopened.restore_spreadsheet_sheet(&data_sheet_id).unwrap();
        assert!(restored
            .workbook
            .sheets
            .iter()
            .any(|sheet| sheet.id == data_sheet_id
                && sheet
                    .cells
                    .iter()
                    .any(|cell| cell.address == "A1" && cell.user_value == "13")));
        assert!(restored
            .workbook
            .named_ranges
            .iter()
            .any(|range| range.name == "RAW" && range.sheet_id == data_sheet_id));
        assert!(restored
            .operations
            .iter()
            .any(|operation| operation.kind == "restore-spreadsheet-sheet"));
        assert!(!reopened
            .audit_view()
            .deleted_sheets
            .iter()
            .any(|entry| entry.sheet_id == data_sheet_id));
        let _ = std::fs::remove_dir_all(root);
    }

