    #[test]
    fn spreadsheet_axis_delete_degrades_formula_refs_but_keeps_graph_anchors() {
        let mut app = OpenDocApp::new_sample();
        app.set_spreadsheet_cell("A1", "7").unwrap();
        app.set_spreadsheet_cell("B2", "5").unwrap();
        app.set_spreadsheet_cell("C2", "=A1+B2").unwrap();

        let row_deleted = app.delete_spreadsheet_row("sheet-1", "1").unwrap();
        let row_formula = row_deleted.workbook.sheets[0]
            .cells
            .iter()
            .find(|cell| cell.address == "C2")
            .unwrap();
        assert_eq!(row_formula.user_value, "=A1+B2");
        assert_eq!(row_formula.computed_kind, "error");
        assert_eq!(row_formula.computed_value, "#REF!");
        assert_eq!(
            graph_entry(&row_deleted.workbook.dependency_graph, "sheet-1", "C2").dependencies,
            vec!["A1", "B2"]
        );
        assert_eq!(
            graph_entry(&row_deleted.workbook.dependency_graph, "sheet-1", "A1").dependents,
            vec!["C2"]
        );

        let column_deleted = app.delete_spreadsheet_column("sheet-1", "A").unwrap();
        let column_formula = column_deleted.workbook.sheets[0]
            .cells
            .iter()
            .find(|cell| cell.address == "C2")
            .unwrap();
        assert_eq!(column_formula.user_value, "=A1+B2");
        assert_eq!(column_formula.computed_kind, "error");
        assert_eq!(column_formula.computed_value, "#REF!");
        assert_eq!(
            graph_entry(&column_deleted.workbook.dependency_graph, "sheet-1", "A1").dependents,
            vec!["C2"]
        );
    }

    #[test]
