    #[test]
    fn spreadsheet_cell_validation_persists_replays_and_is_signed_source_state() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-cell-validation-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();

        let validated = app
            .set_spreadsheet_cell_validation(
                "sheet-1",
                "B2",
                "list",
                vec!["Yes".to_string(), "No".to_string()],
                false,
            )
            .unwrap();
        let cell = validated.workbook.sheets[0]
            .cells
            .iter()
            .find(|cell| cell.address == "B2")
            .unwrap();
        assert_eq!(
            cell.validation.as_ref().unwrap().values,
            vec!["Yes".to_string(), "No".to_string()]
        );
        assert!(validated
            .operations
            .iter()
            .any(|operation| operation.kind == "set-spreadsheet-cell-validation"));

        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();
        app.workbook.sheets[0]
            .cells
            .iter_mut()
            .find(|cell| cell.address == "B2")
            .unwrap()
            .validation
            .as_mut()
            .unwrap()
            .strict = true;
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "broken"
        );

        app.set_spreadsheet_cell_validation(
            "sheet-1",
            "B2",
            "list",
            vec!["Yes".to_string(), "No".to_string()],
            false,
        )
        .unwrap();
        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        let reopened_validation = opened.workbook.sheets[0]
            .cells
            .iter()
            .find(|cell| cell.address == "B2")
            .and_then(|cell| cell.validation.as_ref())
            .unwrap();
        assert_eq!(reopened_validation.kind, "list");
        assert!(!reopened_validation.strict);

        let cleared = reopened
            .clear_spreadsheet_cell_validation("sheet-1", "B2")
            .unwrap();
        assert!(cleared.workbook.sheets[0]
            .cells
            .iter()
            .find(|cell| cell.address == "B2")
            .unwrap()
            .validation
            .is_none());
        assert!(cleared
            .operations
            .iter()
            .any(|operation| operation.kind == "clear-spreadsheet-cell-validation"));
        let deleted_validation = reopened
            .audit_view()
            .deleted_cell_validations
            .into_iter()
            .find(|entry| entry.sheet_id == "sheet-1" && entry.address == "B2")
            .expect("deleted cell validation audit entry");
        assert_eq!(
            deleted_validation.validation.values,
            vec!["Yes".to_string(), "No".to_string()]
        );

        let cleared_saved = reopened.save_to_local_repository(&root).unwrap();
        let mut reopened_cleared = OpenDocApp::new_sample();
        reopened_cleared
            .open_saved_projection(&root, &cleared_saved.uuid)
            .unwrap();
        assert!(reopened_cleared
            .audit_view()
            .deleted_cell_validations
            .iter()
            .any(|entry| entry.sheet_id == "sheet-1" && entry.address == "B2"));
        let restored = reopened_cleared
            .restore_spreadsheet_cell_validation("sheet-1", "B2")
            .unwrap();
        let restored_validation = restored.workbook.sheets[0]
            .cells
            .iter()
            .find(|cell| cell.address == "B2")
            .and_then(|cell| cell.validation.as_ref())
            .unwrap();
        assert_eq!(
            restored_validation.values,
            vec!["Yes".to_string(), "No".to_string()]
        );
        assert!(reopened_cleared
            .audit_view()
            .deleted_cell_validations
            .is_empty());
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn spreadsheet_merged_cells_persist_replay_and_are_signed_source_state() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-merged-cells-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();

        let merged = app.merge_spreadsheet_cells("sheet-1", "A1:B1").unwrap();
        assert_eq!(merged.workbook.sheets[0].merges[0].range, "A1:B1");
        assert!(merged
            .operations
            .iter()
            .any(|operation| operation.kind == "merge-spreadsheet-cells"));
        let overlap = app.merge_spreadsheet_cells("sheet-1", "B1:B2").unwrap_err();
        assert!(overlap.to_string().contains("overlaps"));
        let single = app.merge_spreadsheet_cells("sheet-1", "A1").unwrap_err();
        assert!(single.to_string().contains("at least two cells"));

        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();
        app.workbook.sheets[0].merges.clear();
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "broken"
        );

        app.merge_spreadsheet_cells("sheet-1", "A1:B1").unwrap();
        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert_eq!(opened.workbook.sheets[0].merges[0].range, "A1:B1");

        let unmerged = reopened
            .unmerge_spreadsheet_cells("sheet-1", "A1:B1")
            .unwrap();
        assert!(unmerged.workbook.sheets[0].merges.is_empty());
        assert!(unmerged
            .operations
            .iter()
            .any(|operation| operation.kind == "unmerge-spreadsheet-cells"));
        let deleted_merge = reopened
            .audit_view()
            .deleted_merges
            .into_iter()
            .find(|entry| entry.sheet_id == "sheet-1" && entry.merge.range == "A1:B1")
            .expect("deleted merge audit entry");
        assert_eq!(deleted_merge.merge.id, "merge-a1-b1");

        let unmerged_saved = reopened.save_to_local_repository(&root).unwrap();
        let mut reopened_unmerged = OpenDocApp::new_sample();
        reopened_unmerged
            .open_saved_projection(&root, &unmerged_saved.uuid)
            .unwrap();
        assert!(reopened_unmerged
            .audit_view()
            .deleted_merges
            .iter()
            .any(|entry| entry.sheet_id == "sheet-1" && entry.merge.range == "A1:B1"));
        let restored = reopened_unmerged
            .restore_spreadsheet_merge("sheet-1", "A1:B1")
            .unwrap();
        assert_eq!(restored.workbook.sheets[0].merges[0].range, "A1:B1");
        assert!(reopened_unmerged.audit_view().deleted_merges.is_empty());
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn spreadsheet_basic_filter_persists_replay_and_is_signed_source_state() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-basic-filter-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();

        let filtered = app
            .set_spreadsheet_basic_filter("sheet-1", "A1:B3")
            .unwrap();
        assert_eq!(filtered.workbook.sheets[0].filters[0].range, "A1:B3");
        assert!(filtered
            .operations
            .iter()
            .any(|operation| operation.kind == "set-spreadsheet-basic-filter"));
        let filter_options = app
            .set_spreadsheet_basic_filter_options(
                "sheet-1",
                vec![AppSheetFilterCriterion {
                    column: " a ".to_string(),
                    condition: " text_contains ".to_string(),
                    value: "Item".to_string(),
                }],
                vec![AppSheetFilterSortSpec {
                    column: " b ".to_string(),
                    descending: false,
                }],
            )
            .unwrap();
        assert_eq!(
            filter_options.workbook.sheets[0].filters[0].criteria[0].column,
            "A"
        );
        assert_eq!(
            filter_options.workbook.sheets[0].filters[0].criteria[0].condition,
            "text_contains"
        );
        assert_eq!(
            filter_options.workbook.sheets[0].filters[0].criteria[0].value,
            "Item"
        );
        assert_eq!(
            filter_options.workbook.sheets[0].filters[0].sort_specs[0].column,
            "B"
        );
        assert!(filter_options
            .operations
            .iter()
            .any(|operation| operation.kind == "set-spreadsheet-basic-filter-options"));

        let err = app
            .set_spreadsheet_basic_filter_options(
                "sheet-1",
                vec![
                    AppSheetFilterCriterion {
                        column: "A".to_string(),
                        condition: "text_contains".to_string(),
                        value: "Item".to_string(),
                    },
                    AppSheetFilterCriterion {
                        column: " a ".to_string(),
                        condition: "text_equals".to_string(),
                        value: "Other".to_string(),
                    },
                ],
                Vec::new(),
            )
            .unwrap_err()
            .to_string();
        assert!(err.contains("duplicate filter criterion column A"));

        let err = app
            .set_spreadsheet_basic_filter_options(
                "sheet-1",
                Vec::new(),
                vec![
                    AppSheetFilterSortSpec {
                        column: "B".to_string(),
                        descending: false,
                    },
                    AppSheetFilterSortSpec {
                        column: " b ".to_string(),
                        descending: true,
                    },
                ],
            )
            .unwrap_err()
            .to_string();
        assert!(err.contains("duplicate filter sort column B"));

        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();
        app.workbook.sheets[0].filters.clear();
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "broken"
        );

        app.set_spreadsheet_basic_filter("sheet-1", "A1:B3")
            .unwrap();
        app.set_spreadsheet_basic_filter_options(
            "sheet-1",
            vec![AppSheetFilterCriterion {
                column: "A".to_string(),
                condition: "text_contains".to_string(),
                value: "Item".to_string(),
            }],
            vec![AppSheetFilterSortSpec {
                column: "B".to_string(),
                descending: false,
            }],
        )
        .unwrap();
        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert_eq!(opened.workbook.sheets[0].filters[0].range, "A1:B3");
        assert_eq!(
            opened.workbook.sheets[0].filters[0].criteria[0].condition,
            "text_contains"
        );
        assert!(!opened.workbook.sheets[0].filters[0].sort_specs[0].descending);

        let cleared = reopened.clear_spreadsheet_basic_filter("sheet-1").unwrap();
        assert!(cleared.workbook.sheets[0].filters.is_empty());
        assert!(cleared
            .operations
            .iter()
            .any(|operation| operation.kind == "clear-spreadsheet-basic-filter"));
        let deleted_filter = reopened
            .audit_view()
            .deleted_basic_filters
            .into_iter()
            .find(|entry| entry.sheet_id == "sheet-1")
            .expect("deleted basic filter audit entry");
        assert_eq!(deleted_filter.filter.range, "A1:B3");
        assert_eq!(deleted_filter.filter.criteria[0].condition, "text_contains");

        let cleared_saved = reopened.save_to_local_repository(&root).unwrap();
        let mut reopened_cleared = OpenDocApp::new_sample();
        reopened_cleared
            .open_saved_projection(&root, &cleared_saved.uuid)
            .unwrap();
        assert!(reopened_cleared
            .audit_view()
            .deleted_basic_filters
            .iter()
            .any(|entry| entry.sheet_id == "sheet-1" && entry.filter.range == "A1:B3"));
        let restored = reopened_cleared
            .restore_spreadsheet_basic_filter("sheet-1")
            .unwrap();
        assert_eq!(restored.workbook.sheets[0].filters[0].range, "A1:B3");
        assert_eq!(
            restored.workbook.sheets[0].filters[0].criteria[0].value,
            "Item"
        );
        assert!(reopened_cleared
            .audit_view()
            .deleted_basic_filters
            .is_empty());
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn spreadsheet_protected_ranges_persist_replay_and_are_signed_source_state() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-protected-ranges-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();

        assert!(matches!(
            app.add_spreadsheet_protected_range("sheet-1", "A1:B2", " ", true),
            Err(AppApiError::Format(message))
                if message == "protected range description is empty"
        ));

        let protected = app
            .add_spreadsheet_protected_range("sheet-1", "A1:B2", "Review only", true)
            .unwrap();
        let protected_range = &protected.workbook.sheets[0].protected_ranges[0];
        assert_eq!(protected_range.range, "A1:B2");
        assert_eq!(protected_range.description, "Review only");
        assert!(protected_range.warning_only);
        assert!(protected
            .operations
            .iter()
            .any(|operation| operation.kind == "add-spreadsheet-protected-range"));
        let updated = app
            .update_spreadsheet_protected_range("sheet-1", "A1:B2", "Editors warned", false)
            .unwrap();
        let updated_range = &updated.workbook.sheets[0].protected_ranges[0];
        assert_eq!(updated_range.description, "Editors warned");
        assert!(updated_range.warning_only);
        assert!(updated.warnings.iter().any(|warning| {
            warning.code == "protected-range-warning-only"
                && warning
                    .message
                    .contains("sheet-1!A1:B2 was downgraded to warning-only")
        }));
        assert!(updated
            .operations
            .iter()
            .any(|operation| operation.kind == "update-spreadsheet-protected-range"));
        match app
            .operation_envelopes
            .last()
            .and_then(|envelope| envelope.spreadsheet.as_ref())
        {
            Some(AppSpreadsheetOperation::UpdateProtectedRange { warning_only, .. }) => {
                assert!(warning_only)
            }
            other => panic!("expected protected range update operation, got {other:?}"),
        }
        assert!(matches!(
            app.update_spreadsheet_protected_range("sheet-1", "C1:C2", "Missing", true),
            Err(AppApiError::NotFound(_))
        ));
        assert!(matches!(
            app.update_spreadsheet_protected_range("sheet-1", "A1:B2", " ", true),
            Err(AppApiError::Format(message))
                if message == "protected range description is empty"
        ));

        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();
        app.workbook.sheets[0].protected_ranges[0].description = "Tampered".to_string();
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "broken"
        );

        app.update_spreadsheet_protected_range("sheet-1", "A1:B2", "Review only", true)
            .unwrap();
        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert_eq!(
            opened.workbook.sheets[0].protected_ranges[0].description,
            "Review only"
        );

        let deleted = reopened
            .delete_spreadsheet_protected_range("sheet-1", "A1:B2")
            .unwrap();
        assert!(deleted.workbook.sheets[0].protected_ranges.is_empty());
        assert!(deleted
            .operations
            .iter()
            .any(|operation| operation.kind == "delete-spreadsheet-protected-range"));
        let deleted_audit = reopened.audit_view();
        let deleted_entry = deleted_audit
            .deleted_protected_ranges
            .iter()
            .find(|entry| entry.sheet_id == "sheet-1" && entry.protected_range.range == "A1:B2")
            .expect("deleted protected range audit entry");
        assert_eq!(deleted_entry.protected_range.description, "Review only");
        assert!(deleted_entry.protected_range.warning_only);

        let deleted_saved = reopened.save_to_local_repository(&root).unwrap();
        let mut reopened_deleted = OpenDocApp::new_sample();
        reopened_deleted
            .open_saved_projection(&root, &deleted_saved.uuid)
            .unwrap();
        assert!(reopened_deleted
            .audit_view()
            .deleted_protected_ranges
            .iter()
            .any(|entry| {
                entry.sheet_id == "sheet-1" && entry.protected_range.range == "A1:B2"
            }));
        let restored = reopened_deleted
            .restore_spreadsheet_protected_range("sheet-1", "A1:B2")
            .unwrap();
        assert_eq!(
            restored.workbook.sheets[0].protected_ranges[0].description,
            "Review only"
        );
        assert!(restored.workbook.sheets[0].protected_ranges[0].warning_only);
        assert!(reopened_deleted
            .audit_view()
            .deleted_protected_ranges
            .is_empty());

        let import_err = OpenDocApp::new_sample()
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 1, "title": "Sheet1" },
                        "protectedRanges": [{
                            "protectedRangeId": 1,
                            "range": {
                                "sheetId": 1,
                                "startRowIndex": 0,
                                "endRowIndex": 1,
                                "startColumnIndex": 0,
                                "endColumnIndex": 1
                            },
                            "description": " ",
                            "warningOnly": true
                        }]
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(import_err.contains("protected range description is empty"));

        let imported_enforced = OpenDocApp::new_sample()
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 1, "title": "Sheet1" },
                        "protectedRanges": [{
                            "protectedRangeId": 2,
                            "range": {
                                "sheetId": 1,
                                "startRowIndex": 0,
                                "endRowIndex": 1,
                                "startColumnIndex": 0,
                                "endColumnIndex": 1
                            },
                            "description": "Imported enforced range",
                            "warningOnly": false
                        }]
                    }]
                }"#,
            )
            .unwrap();
        assert!(imported_enforced.workbook.sheets[0].protected_ranges[0].warning_only);
        assert!(imported_enforced.warnings.iter().any(|warning| {
            warning.code == "protected-range-warning-only"
                && warning
                    .message
                    .contains("sheet-1!A1 was downgraded to warning-only")
        }));

        let mut malformed = OpenDocApp::new_sample();
        malformed.workbook.sheets[0]
            .protected_ranges
            .push(AppSheetProtectedRange {
                id: String::new(),
                range: "A1:B2".to_string(),
                description: "Review only".to_string(),
                warning_only: true,
            });
        let export_err = malformed
            .export_google_sheets_json_text()
            .unwrap_err()
            .to_string();
        assert!(export_err.contains("protected range id is empty"));

        let mut enforced = OpenDocApp::new_sample();
        enforced.workbook.sheets[0]
            .protected_ranges
            .push(AppSheetProtectedRange {
                id: "protected-enforced".to_string(),
                range: "A1:B2".to_string(),
                description: "Server-only enforcement".to_string(),
                warning_only: false,
            });
        let export_err = enforced
            .export_google_sheets_json_text()
            .unwrap_err()
            .to_string();
        assert!(export_err.contains("protected range protected-enforced is not warning-only"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn spreadsheet_cell_format_persists_and_is_signed_source_state() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-cell-format-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        assert!(matches!(
            app.set_spreadsheet_cell_format("sheet-1", "B2", "text_color", "red"),
            Err(AppApiError::Format(message)) if message == "invalid sheet color red"
        ));

        let formatted = app
            .set_spreadsheet_cell_format("sheet-1", "B2", "bold", "true")
            .unwrap();
        let cell = formatted.workbook.sheets[0]
            .cells
            .iter()
            .find(|cell| cell.address == "B2")
            .unwrap();
        assert!(cell.format.bold);
        assert!(formatted
            .operations
            .iter()
            .any(|operation| operation.kind == "set-spreadsheet-cell-format"));

        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();
        app.workbook.sheets[0]
            .cells
            .iter_mut()
            .find(|cell| cell.address == "B2")
            .unwrap()
            .format
            .bold = false;
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "broken"
        );

        app.set_spreadsheet_cell_format("sheet-1", "B2", "bold", "true")
            .unwrap();
        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        let reopened_cell = opened.workbook.sheets[0]
            .cells
            .iter()
            .find(|cell| cell.address == "B2")
            .unwrap();
        assert!(reopened_cell.format.bold);

        let mut malformed = OpenDocApp::new_sample();
        malformed.workbook.sheets[0]
            .cell_mut_or_insert("A1")
            .format
            .text_color = Some("red".to_string());
        let export_err = malformed
            .export_google_sheets_json_text()
            .unwrap_err()
            .to_string();
        assert!(export_err.contains("invalid sheet color red"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn signatures_exclude_spreadsheet_axis_and_formula_projection_cache() {
        let mut app = OpenDocApp::new_sample();
        app.set_spreadsheet_cell("C1", "2").unwrap();
        app.set_spreadsheet_cell("C2", "=C1+1").unwrap();
        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();

        app.workbook.sheets[0].row_axes[0].id = "row-projection-only".to_string();
        app.workbook.sheets[0].column_axes[0].id = "col-projection-only".to_string();
        let formula = app.workbook.sheets[0]
            .cells
            .iter_mut()
            .find(|cell| cell.address == "C2")
            .unwrap();
        formula.computed_kind = "projection-only".to_string();
        formula.computed_value = "999".to_string();
        formula.dependencies = vec!["projection-only".to_string()];
        app.workbook.dependency_graph.push(AppCellDependency {
            sheet_id: "sheet-1".to_string(),
            address: "A1".to_string(),
            dependencies: vec!["projection-only".to_string()],
            dependents: vec!["projection-only".to_string()],
            invalidation_order: vec!["projection-only".to_string()],
        });
        app.repository_root = Some(PathBuf::from("/tmp/projection-only"));
        app.repository_backend = Some("flat".to_string());
        app.repository_namespace = Some("bucket/projection-only".to_string());
        app.recent_documents.push(AppRecentDocument {
            uuid: app.document.uuid.to_string(),
            title: app.document.title.clone(),
            doi: None,
            repository_root: "/tmp/projection-only".to_string(),
            repository_backend: "flat".to_string(),
            repository_namespace: Some("bucket/projection-only".to_string()),
            last_manifest: Some("sha256:projection-only".to_string()),
            updated_at_ms: 1,
        });

        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "trusted"
        );

        let formula = app.workbook.sheets[0]
            .cells
            .iter_mut()
            .find(|cell| cell.address == "C2")
            .unwrap();
        formula.user_value = "=C1+2".to_string();
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "broken"
        );
    }

