    #[test]
    fn spreadsheet_formula_errors_project_deterministic_warnings_and_repair() {
        let mut app = OpenDocApp::new_sample();
        let broken = app.set_spreadsheet_cell("D6", "=NOPE(B2)").unwrap();
        assert_cell(&broken.workbook.sheets[0], "D6", "#NAME?", "error", &[]);
        assert!(broken.warnings.iter().any(|warning| {
            warning.code == "spreadsheet-formula-error"
                && warning.message == "formula sheet-1!D6 evaluated to #NAME"
        }));

        let repaired = app.set_spreadsheet_cell("D6", "=SUM(B2:B2)").unwrap();
        assert_cell(&repaired.workbook.sheets[0], "D6", "5", "number", &["B2"]);
        assert!(!repaired
            .warnings
            .iter()
            .any(|warning| warning.code == "spreadsheet-formula-error"));
    }

