    #[test]
    fn spreadsheet_formula_engine_handles_paired_correlation_ranges() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-correlation-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        for (address, value) in [
            ("A1", "1"),
            ("A2", "2"),
            ("A3", "3"),
            ("B1", "2"),
            ("B2", "4"),
            ("B3", "6"),
            ("C1", "6"),
            ("C2", "6"),
            ("C3", "6"),
        ] {
            app.set_spreadsheet_cell(address, value).unwrap();
        }
        app.set_spreadsheet_cell("D1", "=ROUND(CORREL(A1:A3,B1:B3),3)")
            .unwrap();
        app.set_spreadsheet_cell("D2", "=ROUND(PEARSON(A1:A3,B1:B3),3)")
            .unwrap();
        app.set_spreadsheet_cell("D3", "=CORREL(A1:A2,B1:B3)")
            .unwrap();
        app.set_spreadsheet_cell("D4", "=CORREL(A1:A1,B1:B1)")
            .unwrap();
        let edited = app
            .set_spreadsheet_cell("D5", "=PEARSON(A1:A3,C1:C3)")
            .unwrap();
        let sheet = &edited.workbook.sheets[0];
        assert_cell(
            sheet,
            "D1",
            "1",
            "number",
            &["A1", "A2", "A3", "B1", "B2", "B3"],
        );
        assert_cell(
            sheet,
            "D2",
            "1",
            "number",
            &["A1", "A2", "A3", "B1", "B2", "B3"],
        );
        assert_cell(sheet, "D3", "#VALUE!", "error", &[]);
        assert_cell(sheet, "D4", "#DIV/0!", "error", &[]);
        assert_cell(sheet, "D5", "#DIV/0!", "error", &[]);

        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        let sheet = &opened.workbook.sheets[0];
        assert_cell(
            sheet,
            "D1",
            "1",
            "number",
            &["A1", "A2", "A3", "B1", "B2", "B3"],
        );
        assert_cell(
            sheet,
            "D2",
            "1",
            "number",
            &["A1", "A2", "A3", "B1", "B2", "B3"],
        );
        assert_cell(sheet, "D3", "#VALUE!", "error", &[]);
        assert_cell(sheet, "D4", "#DIV/0!", "error", &[]);
        assert_cell(sheet, "D5", "#DIV/0!", "error", &[]);
        let _ = std::fs::remove_dir_all(root);
    }

