    #[test]
    fn spreadsheet_named_ranges_evaluate_persist_and_are_signed_source_state() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-named-range-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();

        assert!(matches!(
            app.add_spreadsheet_named_range("sheet-1", "A1", "B2:B3"),
            Err(AppApiError::Format(_))
        ));
        assert!(matches!(
            app.add_spreadsheet_named_range("sheet-1", "qty", "not-a-range"),
            Err(AppApiError::Format(_))
        ));

        app.add_spreadsheet_named_range("sheet-1", "qty", "B2:B3")
            .unwrap();
        let evaluated = app.set_spreadsheet_cell("C1", "=SUM(QTY)").unwrap();
        assert_eq!(evaluated.workbook.named_ranges[0].name, "QTY");
        assert_eq!(evaluated.workbook.named_ranges[0].range, "B2:B3");
        assert_cell(
            &evaluated.workbook.sheets[0],
            "C1",
            "10",
            "number",
            &["B2", "B3"],
        );
        assert_eq!(
            graph_entry(&evaluated.workbook.dependency_graph, "sheet-1", "B2").dependents,
            vec!["B3", "C1"]
        );
        let updated = app
            .update_spreadsheet_named_range("sheet-1", "qty", "B2:B2")
            .unwrap();
        assert_eq!(updated.workbook.named_ranges[0].range, "B2");
        assert_cell(&updated.workbook.sheets[0], "C1", "5", "number", &["B2"]);
        assert!(updated
            .operations
            .iter()
            .any(|operation| operation.kind == "update-spreadsheet-named-range"));
        assert!(matches!(
            app.update_spreadsheet_named_range("sheet-1", "missing", "B2:B2"),
            Err(AppApiError::NotFound(_))
        ));

        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();
        app.workbook.named_ranges[0].range = "B2:B3".to_string();
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "broken"
        );

        app.update_spreadsheet_named_range("sheet-1", "qty", "B2:B3")
            .unwrap();
        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert_eq!(opened.workbook.named_ranges[0].name, "QTY");
        assert_cell(
            &opened.workbook.sheets[0],
            "C1",
            "10",
            "number",
            &["B2", "B3"],
        );
        let deleted = reopened.delete_spreadsheet_named_range("qty").unwrap();
        assert!(deleted.workbook.named_ranges.is_empty());
        assert_cell(&deleted.workbook.sheets[0], "C1", "#NAME?", "error", &[]);
        assert!(deleted
            .operations
            .iter()
            .any(|operation| operation.kind == "delete-spreadsheet-named-range"));
        let audit = reopened.audit_view();
        assert!(audit.deleted_named_ranges.iter().any(|entry| {
            entry.name == "QTY"
                && entry.range.name == "QTY"
                && entry.operation.kind == "delete-spreadsheet-named-range"
        }));
        let restored = reopened.restore_spreadsheet_named_range("qty").unwrap();
        assert!(restored
            .workbook
            .named_ranges
            .iter()
            .any(|range| range.name == "QTY" && range.range == "B2:B3"));
        assert_cell(
            &restored.workbook.sheets[0],
            "C1",
            "10",
            "number",
            &["B2", "B3"],
        );
        assert!(restored
            .operations
            .iter()
            .any(|operation| operation.kind == "restore-spreadsheet-named-range"));
        assert!(reopened.audit_view().deleted_named_ranges.is_empty());

        let import_err = OpenDocApp::new_sample()
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 7, "title": "Sheet1" }
                    }],
                    "namedRanges": [{
                        "namedRangeId": "named-missing-sheet",
                        "name": "QTY",
                        "range": {
                            "sheetId": 99,
                            "startRowIndex": 0,
                            "endRowIndex": 1,
                            "startColumnIndex": 0,
                            "endColumnIndex": 1
                        }
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(import_err.contains("named range references unknown sheetId 99"));

        let mut malformed = OpenDocApp::new_sample();
        malformed.workbook.named_ranges.push(AppNamedRange {
            id: "named-missing-sheet".to_string(),
            name: "QTY".to_string(),
            sheet_id: "missing-sheet".to_string(),
            range: "A1".to_string(),
        });
        let export_err = malformed
            .export_google_sheets_json_text()
            .unwrap_err()
            .to_string();
        assert!(export_err.contains("references missing sheet missing-sheet"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn malformed_google_sheets_sheet_identity_does_not_replace_current_workbook() {
        let mut app = OpenDocApp::new_sample();
        app.set_spreadsheet_cell("A1", "Current workbook").unwrap();
        let before = app.document();

        let err = app
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 7, "title": "Sheet A" }
                    }, {
                        "properties": { "sheetId": 7, "title": "Sheet B" }
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(err.contains("duplicate Google Sheets sheetId 7"), "{err}");
        assert_eq!(app.document(), before);

        let err = app
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 8, "title": "Same Title" }
                    }, {
                        "properties": { "sheetId": 9, "title": "Same Title" }
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("duplicate Google Sheets title Same Title"),
            "{err}"
        );
        assert_eq!(app.document(), before);
    }

