    #[test]
    fn malformed_google_sheets_cell_payloads_do_not_replace_current_workbook() {
        let mut app = OpenDocApp::new_sample();
        app.set_spreadsheet_cell("A1", "Current workbook").unwrap();
        let before = app.document();

        let err = app
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 7, "title": "Sheet1" },
                        "data": [{
                            "rowData": [{ "values": [{
                                "userEnteredValue": { "formulaValue": "SUM(A1:A2)" }
                            }] }]
                        }]
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("formula cell A1 source does not start with ="),
            "{err}"
        );
        assert_eq!(app.document(), before);

        let err = app
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 7, "title": "Sheet1" },
                        "data": [{
                            "rowData": [{ "values": [{
                                "userEnteredValue": { "formulaValue": " =SUM(A1:A2)" }
                            }] }]
                        }]
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("formula cell A1 source does not start with ="),
            "{err}"
        );
        assert_eq!(app.document(), before);

        let err = app
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 7, "title": "Sheet1" },
                        "data": [{
                            "rowData": [{ "values": [{
                                "userEnteredValue": {
                                    "numberValue": 7,
                                    "stringValue": "seven"
                                }
                            }] }]
                        }]
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("userEnteredValue has multiple value kinds"),
            "{err}"
        );
        assert_eq!(app.document(), before);

        let err = app
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 7, "title": "Sheet1" },
                        "data": [{
                            "rowData": [{ "values": [{
                                "userEnteredValue": { "numberValue": "7" }
                            }] }]
                        }]
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(err.contains("numberValue must be a number"), "{err}");
        assert_eq!(app.document(), before);

        let err = app
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 7, "title": "Sheet1" },
                        "data": [{
                            "rowData": [{ "values": [{
                                "userEnteredValue": { "stringValue": "x" },
                                "opendocCellComments": [{
                                    "id": "comment-1",
                                    "author": "Reviewer",
                                    "body": "One",
                                    "deleted": false
                                }, {
                                    "id": "comment-1",
                                    "author": "Reviewer",
                                    "body": "Two",
                                    "deleted": false
                                }]
                            }] }]
                        }]
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("duplicate Google Sheets cell comment id comment-1"),
            "{err}"
        );
        assert_eq!(app.document(), before);

        let err = app
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 7, "title": "Sheet1" },
                        "data": [{
                            "rowData": [{ "values": [{
                                "userEnteredValue": { "stringValue": "x" },
                                "userEnteredFormat": {
                                    "textFormat": { "bold": "true" }
                                }
                            }] }]
                        }]
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(err.contains("bold must be a boolean"), "{err}");
        assert_eq!(app.document(), before);

        let err = app
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 7, "title": "Sheet1" },
                        "data": [{
                            "rowData": [{ "values": [{
                                "userEnteredValue": { "stringValue": "x" },
                                "dataValidation": {
                                    "condition": {
                                        "type": "ONE_OF_LIST",
                                        "values": ["Yes"]
                                    }
                                }
                            }] }]
                        }]
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("dataValidation value 0 must be an object"),
            "{err}"
        );
        assert_eq!(app.document(), before);

        let err = app
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 7, "title": "Sheet1" },
                        "data": [{
                            "startRow": 0,
                            "startColumn": 0,
                            "rowData": [{ "values": [{
                                "userEnteredValue": { "stringValue": "first" }
                            }] }]
                        }, {
                            "startRow": 0,
                            "startColumn": 0,
                            "rowData": [{ "values": [{
                                "userEnteredValue": { "stringValue": "second" }
                            }] }]
                        }]
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(err.contains("duplicate Google Sheets cell A1"), "{err}");
        assert_eq!(app.document(), before);
    }

    #[test]
    fn malformed_google_sheets_filter_payloads_do_not_replace_current_workbook() {
        let mut app = OpenDocApp::new_sample();
        app.set_spreadsheet_cell("A1", "Current workbook").unwrap();
        let before = app.document();

        let err = app
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 7, "title": "Sheet1" },
                        "basicFilter": {
                            "criteria": {
                                "0": {
                                    "condition": {
                                        "type": "TEXT_CONTAINS",
                                        "values": [{ "userEnteredValue": "x" }]
                                    }
                                }
                            }
                        }
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(err.contains("basicFilter missing range"), "{err}");
        assert_eq!(app.document(), before);

        let err = app
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 7, "title": "Sheet1" },
                        "basicFilter": {
                            "range": {
                                "sheetId": 7,
                                "startRowIndex": 0,
                                "endRowIndex": 2,
                                "startColumnIndex": 0,
                                "endColumnIndex": 2
                            },
                            "criteria": {
                                "bad": {
                                    "condition": {
                                        "type": "TEXT_CONTAINS",
                                        "values": [{ "userEnteredValue": "x" }]
                                    }
                                }
                            }
                        }
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("basicFilter criteria key bad is not a column offset"),
            "{err}"
        );
        assert_eq!(app.document(), before);

        let err = app
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 7, "title": "Sheet1" },
                        "basicFilter": {
                            "range": {
                                "sheetId": 7,
                                "startRowIndex": 0,
                                "endRowIndex": 2,
                                "startColumnIndex": 0,
                                "endColumnIndex": 2
                            },
                            "criteria": {
                                "0": {
                                    "condition": {
                                        "type": "TEXT_CONTAINS",
                                        "values": []
                                    }
                                }
                            }
                        }
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("filter condition has no userEnteredValue"),
            "{err}"
        );
        assert_eq!(app.document(), before);

        let err = app
            .import_google_sheets_json_text(
                r#"{
                    "sheets": [{
                        "properties": { "sheetId": 7, "title": "Sheet1" },
                        "basicFilter": {
                            "range": {
                                "sheetId": 7,
                                "startRowIndex": 0,
                                "endRowIndex": 2,
                                "startColumnIndex": 0,
                                "endColumnIndex": 2
                            },
                            "sortSpecs": [{
                                "dimensionIndex": 1,
                                "sortOrder": "SIDEWAYS"
                            }]
                        }
                    }]
                }"#,
            )
            .unwrap_err()
            .to_string();
        assert!(err.contains("unsupported sort order SIDEWAYS"), "{err}");
        assert_eq!(app.document(), before);
    }

    #[test]
    fn google_sheets_export_validates_workbook_source_before_serializing() {
        let mut workbook = AppSpreadsheetWorkbook::sample();
        workbook.title = " Export Workbook ".to_string();
        let err = export_google_sheets_workbook(&workbook)
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("spreadsheet workbook title has surrounding whitespace"),
            "{err}"
        );

        let mut workbook = AppSpreadsheetWorkbook::sample();
        workbook.sheets[0].title = " Sheet1 ".to_string();
        let err = export_google_sheets_workbook(&workbook)
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("spreadsheet sheet sheet-1 title has surrounding whitespace"),
            "{err}"
        );
    }

    #[test]
