    #[test]
    fn bibliography_projection_updates_with_citation_source_state() {
        let mut app = OpenDocApp::new_sample();

        let initial = app.document();
        assert!(initial
            .citations
            .bibliography
            .iter()
            .any(|entry| entry.reference_id == "ref-doe-2020"
                && entry.text == "Doe (2020). Example Article. doi:10.0000/example"));

        let edited = app
            .update_bibliography_reference(
                "ref-doe-2020",
                "Updated Article",
                Some("2024".to_string()),
            )
            .unwrap();
        assert!(edited
            .citations
            .bibliography
            .iter()
            .any(|entry| entry.reference_id == "ref-doe-2020"
                && entry.text == "Doe (2024). Updated Article. doi:10.0000/example"));

        let styled = app.set_citation_style("ieee", "en-US").unwrap();
        assert!(styled
            .citations
            .bibliography
            .iter()
            .any(|entry| entry.reference_id == "ref-doe-2020"
                && entry.text == "[1] Doe. Updated Article. 2024"));

        let deleted = app.delete_bibliography_reference("ref-doe-2020").unwrap();
        assert!(deleted.citations.bibliography.is_empty());
        assert!(deleted
            .citations
            .references
            .iter()
            .any(|reference| reference.id == "ref-doe-2020" && reference.deleted));
    }

    #[test]
    fn bibliography_reference_update_rerenders_all_dependent_citation_labels() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-citation-dependent-rerender-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let after_inline_id = first_editable_inline_id(&app.document());

        app.insert_citation(
            "ref-doe-2020",
            Some(after_inline_id.clone()),
            Some("17".to_string()),
            Some("page".to_string()),
            Some("see".to_string()),
            None,
            false,
        )
        .unwrap();
        let second_anchor = first_editable_inline_id(&app.document());
        app.insert_citation(
            "ref-doe-2020",
            Some(second_anchor),
            Some("29".to_string()),
            Some("page".to_string()),
            Some("compare".to_string()),
            None,
            false,
        )
        .unwrap();

        let edited = app
            .update_bibliography_reference_metadata(
                "ref-doe-2020",
                "Shared Reference",
                vec!["Shared Author".to_string()],
                Some("2029".to_string()),
                Some("10.2029/shared".to_string()),
                None,
            )
            .unwrap();
        assert!(edited
            .visible_text
            .contains("(see Shared Author 2029, page 17)"));
        assert!(edited
            .visible_text
            .contains("(compare Shared Author 2029, page 29)"));
        let dependent_labels = edited
            .citations
            .citations
            .iter()
            .filter(|citation| {
                !citation.deleted
                    && citation
                        .items
                        .iter()
                        .any(|item| item.reference_id == "ref-doe-2020")
            })
            .collect::<Vec<_>>();
        assert!(
            dependent_labels.len() >= 3,
            "expected sample and inserted citation labels to depend on ref-doe-2020"
        );
        assert!(dependent_labels.iter().all(|citation| citation
            .rendered_cache
            .as_deref()
            .is_some_and(|label| label.contains("Shared Author 2029"))));

        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert!(opened
            .visible_text
            .contains("(see Shared Author 2029, page 17)"));
        assert!(opened
            .visible_text
            .contains("(compare Shared Author 2029, page 29)"));
        assert!(opened
            .citations
            .citations
            .iter()
            .filter(|citation| {
                !citation.deleted
                    && citation
                        .items
                        .iter()
                        .any(|item| item.reference_id == "ref-doe-2020")
            })
            .all(|citation| citation
                .rendered_cache
                .as_deref()
                .is_some_and(|label| label.contains("Shared Author 2029"))));
        let _ = std::fs::remove_dir_all(root);
    }

