    #[test]
    fn signatures_exclude_citation_rendering_projection_cache() {
        let mut app = OpenDocApp::new_sample();
        app.set_citation_style("ieee", "en-US").unwrap();
        let signed = app
            .sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();
        assert_eq!(signed.signature_state, "signed");

        for citation in &mut app.document.citation_database.citations {
            citation.rendered_cache = Some("(projection changed)".to_string());
        }
        if let Some(block) = app.document.blocks.iter_mut().find(|block| {
            block
                .content
                .iter()
                .any(|inline| matches!(inline, Inline::Citation { .. }))
        }) {
            for inline in &mut block.content {
                if let Inline::Citation { rendered_cache, .. } = inline {
                    *rendered_cache = Some("(inline projection changed)".to_string());
                }
            }
        }
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "trusted"
        );

        app.document.citation_database.style = "apa-7th".to_string();
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "broken"
        );
    }

    #[test]
    fn signatures_exclude_warning_and_import_provenance_payloads() {
        let mut app = OpenDocApp::new_sample();
        app.document.warnings.push(ModelWarning {
            code: "import-provenance".to_string(),
            message: "imported from external converter".to_string(),
        });
        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "trusted"
        );

        app.document.warnings[0].message = "converter note changed".to_string();
        app.document.warnings.push(ModelWarning {
            code: "degraded-view".to_string(),
            message: "view-only warning changed".to_string(),
        });
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "trusted"
        );

        app.document.title = "Authored title changed".to_string();
        assert_eq!(
            app.verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "broken"
        );
    }

