    #[test]
    fn signatures_include_equation_source() {
        let mut inline_app = OpenDocApp::new_sample();
        inline_app
            .sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();
        let inline_equation = inline_app
            .document
            .blocks
            .iter_mut()
            .flat_map(|block| block.content.iter_mut())
            .find_map(|inline| match inline {
                Inline::Equation { equation, .. } => Some(equation),
                _ => None,
            })
            .expect("sample inline equation exists");
        inline_equation.source = "E=mc^3".to_string();
        assert_eq!(
            inline_app
                .verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "broken"
        );

        let mut block_app = OpenDocApp::new_sample();
        block_app.add_equation_block("x=1").unwrap();
        block_app
            .sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();
        let block_equation = block_app
            .document
            .blocks
            .iter_mut()
            .find_map(|block| match &mut block.kind {
                BlockKind::EquationBlock { equation } => Some(equation),
                _ => None,
            })
            .expect("block equation exists");
        block_equation.source = "x=2".to_string();
        assert_eq!(
            block_app
                .verify_current_signature(TEST_ED25519_PRIVATE_KEY)
                .unwrap(),
            "broken"
        );
    }

    #[test]
    fn citation_reference_delete_hides_current_state_and_survives_audit() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-citation-delete-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        app.sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Alice")
            .unwrap();

        let deleted = app.delete_bibliography_reference("ref-doe-2020").unwrap();
        assert_eq!(deleted.signature_state, "unsigned");
        assert!(deleted
            .citations
            .references
            .iter()
            .any(|reference| reference.id == "ref-doe-2020" && reference.deleted));
        assert!(deleted.visible_text.contains("[cite-intro]"));
        assert!(deleted
            .operations
            .iter()
            .any(|operation| operation.kind == "delete-bibliography-reference"));

        let audit = app.audit_view();
        assert!(audit
            .deleted_references
            .iter()
            .any(|reference| reference.id == "ref-doe-2020" && reference.deleted));

        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert!(opened
            .citations
            .references
            .iter()
            .any(|reference| reference.id == "ref-doe-2020" && reference.deleted));
        assert!(opened.visible_text.contains("[cite-intro]"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
