    #[test]
    fn accepting_suggestions_applies_source_changes_and_persists() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-accept-suggestion-source-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();

        let insert_id = app
            .add_suggestion("Reviewer", " accepted text")
            .unwrap()
            .suggestions
            .last()
            .unwrap()
            .id
            .clone();
        let inserted = app.accept_suggestion(&insert_id, "Alice").unwrap();
        assert!(inserted.visible_text.contains("accepted text"));
        assert!(inserted
            .suggestions
            .iter()
            .any(|suggestion| suggestion.id == insert_id && suggestion.state == "accepted"));

        let delete_id = first_editable_inline_id(&app.document());
        let delete_suggestion_id = app
            .add_delete_suggestion("Reviewer", &delete_id)
            .unwrap()
            .suggestions
            .last()
            .unwrap()
            .id
            .clone();
        let deleted = app
            .accept_suggestion(&delete_suggestion_id, "Alice")
            .unwrap();
        assert!(!deleted
            .blocks
            .iter()
            .flat_map(|block| block.content.iter())
            .any(|inline| inline.id == delete_id));

        let format_id = first_editable_inline_id(&app.document());
        let format_suggestion_id = app
            .add_format_suggestion("Reviewer", &format_id, "bold", None)
            .unwrap()
            .suggestions
            .last()
            .unwrap()
            .id
            .clone();
        let formatted = app
            .accept_suggestion(&format_suggestion_id, "Alice")
            .unwrap();
        assert!(formatted
            .blocks
            .iter()
            .flat_map(|block| block.content.iter())
            .find(|inline| inline.id == format_id)
            .is_some_and(|inline| inline.marks.iter().any(|mark| mark == "bold:both")));

        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert!(opened.visible_text.contains("accepted text"));
        assert!(opened
            .suggestions
            .iter()
            .any(|suggestion| suggestion.id == insert_id && suggestion.state == "accepted"));
        assert!(opened
            .blocks
            .iter()
            .flat_map(|block| block.content.iter())
            .find(|inline| inline.id == format_id)
            .is_some_and(|inline| inline.marks.iter().any(|mark| mark == "bold:both")));
        let _ = std::fs::remove_dir_all(root);
    }

