    #[test]
    fn text_mark_ranges_can_be_removed_and_persisted() {
        let root = std::env::temp_dir().join(format!(
            "opendoc-app-api-remove-mark-range-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let start_inline_id = first_editable_inline_id(&app.document());
        let linked = app
            .add_link("Remove range endpoint", "https://example.invalid")
            .unwrap();
        let end_inline_id = linked
            .blocks
            .iter()
            .flat_map(|block| block.content.iter())
            .find(|inline| inline.kind == "link")
            .map(|inline| inline.id.clone())
            .expect("link inline was added");

        app.add_text_mark_range(&start_inline_id, &end_inline_id, "italic", None)
            .unwrap();
        let removed = app
            .remove_text_mark_range(
                format!(" {end_inline_id} "),
                format!(" {start_inline_id} "),
                "italic",
                None,
            )
            .unwrap();
        let removed_inlines: Vec<_> = removed
            .blocks
            .iter()
            .flat_map(|block| block.content.iter())
            .filter(|inline| inline.id == start_inline_id || inline.id == end_inline_id)
            .collect();
        assert_eq!(removed_inlines.len(), 2);
        assert!(removed_inlines
            .iter()
            .all(|inline| !inline.marks.iter().any(|mark| mark == "italic:both")));
        assert!(
            removed
                .operations
                .iter()
                .filter(|operation| operation.kind == "remove-mark")
                .count()
                >= 2
        );

        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        let reopened_unmarked: Vec<_> = opened
            .blocks
            .iter()
            .flat_map(|block| block.content.iter())
            .filter(|inline| inline.id == start_inline_id || inline.id == end_inline_id)
            .collect();
        assert_eq!(reopened_unmarked.len(), 2);
        assert!(reopened_unmarked
            .iter()
            .all(|inline| !inline.marks.iter().any(|mark| mark == "italic:both")));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn mark_commands_reject_invalid_payloads() {
        let mut app = OpenDocApp::new_sample();
        let inline_id = first_editable_inline_id(&app.document());
        let initial_operation_count = app.document().operations.len();

        let error = app.add_text_mark(&inline_id, "color", None).unwrap_err();
        assert!(matches!(
            error,
            AppApiError::Format(message) if message == "mark value is missing"
        ));

        let error = app
            .add_text_mark(&inline_id, "bold", Some("true".to_string()))
            .unwrap_err();
        assert!(matches!(
            error,
            AppApiError::Format(message) if message == "boolean mark has value"
        ));

        let error = app
            .add_format_suggestion("Reviewer", &inline_id, "background", Some(" ".to_string()))
            .unwrap_err();
        assert!(matches!(
            error,
            AppApiError::Format(message) if message == "mark value is empty"
        ));

        assert_eq!(app.document().operations.len(), initial_operation_count);
    }

    #[test]
    fn block_level_schema_nodes_are_projected_and_persisted() {
        let root =
            std::env::temp_dir().join(format!("opendoc-app-api-blocks-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let mut app = OpenDocApp::new_sample();
        let invalid_list_item = app.add_list_item("Too deep", 9, false);
        assert!(matches!(
            invalid_list_item,
            Err(AppApiError::Format(message)) if message == "list item level 9 is outside 0..=8"
        ));
        app.add_list_item("Checklist item", 1, false).unwrap();
        let empty_block_equation = app.add_equation_block(" ");
        assert!(matches!(
            empty_block_equation,
            Err(AppApiError::Format(message)) if message == "block equation source is empty"
        ));
        app.add_equation_block(" \\alpha + \\beta ").unwrap();
        app.add_page_break();
        let equation_block_id = app
            .document()
            .blocks
            .iter()
            .find(|block| block.kind == "equation-block")
            .map(|block| block.id.clone())
            .unwrap();
        let signed = app
            .sign_with_openssh_private_key(TEST_ED25519_PRIVATE_KEY, "Equation Signer")
            .unwrap();
        assert_eq!(signed.signature_state, "signed");
        let updated = app
            .update_block_equation_source(&equation_block_id, " \\gamma ")
            .unwrap();
        assert_eq!(updated.signature_state, "unsigned");
        let empty_block_equation = app.update_block_equation_source(&equation_block_id, " ");
        assert!(matches!(
            empty_block_equation,
            Err(AppApiError::Format(message)) if message == "block equation source is empty"
        ));

        let saved = app.save_to_local_repository(&root).unwrap();
        assert!(saved.blocks.iter().any(|block| {
            block.kind == "list-item" && block.level == Some(1) && block.ordered == Some(false)
        }));
        assert!(saved.blocks.iter().any(|block| {
            block.kind == "equation-block" && block.equation_source.as_deref() == Some("\\gamma")
        }));
        assert!(saved.blocks.iter().any(|block| block.kind == "page-break"));

        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert!(opened.blocks.iter().any(|block| {
            block.kind == "list-item" && block.level == Some(1) && block.ordered == Some(false)
        }));
        assert!(opened.blocks.iter().any(|block| {
            block.kind == "equation-block" && block.equation_source.as_deref() == Some("\\gamma")
        }));
        assert!(opened.blocks.iter().any(|block| block.kind == "page-break"));
        assert!(opened.visible_text.contains("\\gamma"));
        assert!(opened
            .operations
            .iter()
            .any(|operation| operation.kind == "update-block-equation-source"));
        let _ = std::fs::remove_dir_all(root);
    }

