    #[test]
    fn unsupported_legacy_doc_import_aborts_without_replacing_current_document() {
        let path = std::env::temp_dir().join(format!(
            "opendoc-app-api-unsupported-legacy-doc-{}.doc",
            std::process::id()
        ));
        let _ = std::fs::remove_file(&path);
        std::fs::write(&path, b"not a supported legacy Word binary").unwrap();

        let mut app = OpenDocApp::new_sample();
        let before = app.document();
        let before_operation_count = before.operations.len();
        let err = app.import_doc_or_docx_path(&path).unwrap_err();

        assert!(matches!(
            err,
            AppApiError::Import(message)
                if message
                    == "UnsupportedStructure(\"legacy .doc import requires an OLE compound document or RTF payload\")"
        ));
        let after = app.document();
        assert_eq!(after.uuid, before.uuid);
        assert_eq!(after.title, before.title);
        assert_eq!(after.visible_text, before.visible_text);
        assert_eq!(after.blocks, before.blocks);
        assert_eq!(after.operations.len(), before_operation_count);
        assert!(!after
            .operations
            .iter()
            .any(|operation| operation.kind == "import-doc-or-docx"));
        let _ = std::fs::remove_file(path);
    }

