    #[test]
    fn docx_image_import_keeps_content_addressed_blob_bytes() {
        if !command_available("zip") || !command_available("unzip") {
            return;
        }
        let root =
            std::env::temp_dir().join(format!("opendoc-app-api-docx-image-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let path = root.with_extension("docx");
        let _ = std::fs::remove_file(&path);
        let image_bytes = b"fake-png-bytes";
        create_docx_zip_with_image(&root, &path, image_bytes);
        let expected_hash = digest_bytes("sha256", image_bytes).unwrap().to_string();

        let mut app = OpenDocApp::new_sample();
        let imported = app.import_doc_or_docx_path(&path).unwrap();
        let image = imported
            .blocks
            .iter()
            .find(|block| block.kind == "image")
            .expect("DOCX image imports as image block");
        assert_eq!(image.blob_hash.as_deref(), Some(expected_hash.as_str()));
        assert_eq!(
            image.alt_text.as_deref(),
            Some("Imported & described figure")
        );
        assert_eq!(imported.blobs.len(), 1);
        assert_eq!(imported.blobs[0].name, "image1.png");
        assert_eq!(imported.blobs[0].media_type, "image/png");
        assert_eq!(imported.blobs[0].hash, expected_hash);
        assert!(imported.blobs[0].available);
        assert_eq!(imported.blobs[0].signature_state, "unsigned");
        assert!(!imported.warnings.iter().any(|warning| {
            warning.code == "image-blob-reference-restored"
                && warning.message.contains(&imported.blobs[0].hash)
        }));
        assert_eq!(
            app.blob_bytes.get(&imported.blobs[0].hash).unwrap(),
            image_bytes
        );
        assert!(imported
            .operations
            .iter()
            .any(|operation| operation.kind == "import-doc-or-docx"));

        let saved = app.save_to_local_repository(&root).unwrap();
        let mut reopened = OpenDocApp::new_sample();
        let opened = reopened.open_saved_projection(&root, &saved.uuid).unwrap();
        assert!(opened.blocks.iter().any(|block| {
            block.kind == "image"
                && block.blob_hash.as_deref() == Some(imported.blobs[0].hash.as_str())
                && block.alt_text.as_deref() == Some("Imported & described figure")
        }));
        assert_eq!(opened.blobs.len(), 1);
        assert_eq!(opened.blobs[0].hash, imported.blobs[0].hash);
        assert!(opened.blobs[0].available);

        let _ = std::fs::remove_dir_all(root);
        let _ = std::fs::remove_file(path);
    }

