    fn create_docx_zip_with_image(root: &std::path::Path, path: &std::path::Path, bytes: &[u8]) {
        let _ = std::fs::remove_dir_all(root);
        std::fs::create_dir_all(root.join("_rels")).unwrap();
        std::fs::create_dir_all(root.join("word/_rels")).unwrap();
        std::fs::create_dir_all(root.join("word/media")).unwrap();
        std::fs::write(
            root.join("[Content_Types].xml"),
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
  <Default Extension="xml" ContentType="application/xml"/>
  <Default Extension="png" ContentType="image/png"/>
  <Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
</Types>"#,
        )
        .unwrap();
        std::fs::write(
            root.join("_rels/.rels"),
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
</Relationships>"#,
        )
        .unwrap();
        std::fs::write(
            root.join("word/_rels/document.xml.rels"),
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rIdImage1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/image1.png"/>
</Relationships>"#,
        )
        .unwrap();
        std::fs::write(
            root.join("word/document.xml"),
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"
  xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"
  xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing"
  xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"
  xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture">
  <w:body>
    <w:p><w:r><w:t>Before image</w:t></w:r></w:p>
    <w:p><w:r><w:drawing><wp:inline><wp:docPr id="1" name="Picture 1" descr="Imported &amp; described figure"/><a:graphic><a:graphicData><pic:pic><pic:blipFill><a:blip r:embed="rIdImage1"/></pic:blipFill></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>
    <w:p><w:r><w:t>After image</w:t></w:r></w:p>
  </w:body>
</w:document>"#,
        )
        .unwrap();
        std::fs::write(root.join("word/media/image1.png"), bytes).unwrap();
        let output = std::process::Command::new("zip")
            .args(["-qr"])
            .arg(path)
            .arg(".")
            .current_dir(root)
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "zip failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

