    fn assert_candidate_merge_preserves_spreadsheet_filter_options(
        kind: TestRepositoryKind,
        root: &std::path::Path,
    ) {
        let _ = std::fs::remove_dir_all(root);
        let mut base = OpenDocApp::new_sample();
        base.actor_id = "actor-base".to_string();
        base.set_spreadsheet_basic_filter("sheet-1", "A1:B3")
            .unwrap();
        let saved_base = kind.save(&mut base, root);

        let mut current = OpenDocApp::new_sample();
        current.actor_id = "actor-current-filter".to_string();
        kind.open(&mut current, root, &saved_base.uuid);

        let mut candidate = OpenDocApp::new_sample();
        candidate.actor_id = "actor-candidate-filter".to_string();
        kind.open(&mut candidate, root, &saved_base.uuid);

        current.set_spreadsheet_cell("B2", "13").unwrap();
        kind.save(&mut current, root);

        candidate
            .set_spreadsheet_basic_filter_options(
                "sheet-1",
                vec![AppSheetFilterCriterion {
                    column: "A".to_string(),
                    condition: "text_contains".to_string(),
                    value: "Item".to_string(),
                }],
                vec![AppSheetFilterSortSpec {
                    column: "B".to_string(),
                    descending: true,
                }],
            )
            .unwrap();
        kind.save_candidate(&mut candidate, root);

        kind.assert_candidate_has_unmerged_operations(
            &OpenDocApp::new_sample(),
            root,
            &saved_base.uuid,
        );

        let mut merger = OpenDocApp::new_sample();
        let merged = kind.merge(&mut merger, root, &saved_base.uuid);
        let sheet = &merged.workbook.sheets[0];
        assert!(sheet
            .cells
            .iter()
            .any(|cell| cell.address == "B2" && cell.user_value == "13"));
        let filter = sheet.filters.first().expect("basic filter survives merge");
        assert_eq!(filter.range, "A1:B3");
        assert_eq!(filter.criteria.len(), 1);
        assert_eq!(filter.criteria[0].column, "A");
        assert_eq!(filter.criteria[0].condition, "text_contains");
        assert_eq!(filter.criteria[0].value, "Item");
        assert_eq!(filter.sort_specs.len(), 1);
        assert_eq!(filter.sort_specs[0].column, "B");
        assert!(filter.sort_specs[0].descending);
        assert!(merged.operations.iter().any(|operation| {
            operation.actor == "actor-candidate-filter"
                && operation.kind == "set-spreadsheet-basic-filter-options"
        }));

        let reopened = kind.open(&mut OpenDocApp::new_sample(), root, &saved_base.uuid);
        let reopened_filter = reopened.workbook.sheets[0]
            .filters
            .first()
            .expect("reopened basic filter survives merge");
        assert_eq!(reopened_filter.criteria, filter.criteria);
        assert_eq!(reopened_filter.sort_specs, filter.sort_specs);

        let second_pass = kind.merge(&mut merger, root, &saved_base.uuid);
        assert_eq!(second_pass.workbook.sheets[0].filters, sheet.filters);
        let _ = std::fs::remove_dir_all(root);
    }

    fn assert_candidate_merge_preserves_spreadsheet_structural_features(
        kind: TestRepositoryKind,
        root: &std::path::Path,
    ) {
        let _ = std::fs::remove_dir_all(root);
        let mut base = OpenDocApp::new_sample();
        base.actor_id = "actor-base".to_string();
        let saved_base = kind.save(&mut base, root);

        let mut current = OpenDocApp::new_sample();
        current.actor_id = "actor-current-structure".to_string();
        kind.open(&mut current, root, &saved_base.uuid);

        let mut candidate = OpenDocApp::new_sample();
        candidate.actor_id = "actor-candidate-structure".to_string();
        kind.open(&mut candidate, root, &saved_base.uuid);

        current.set_spreadsheet_cell("A2", "9").unwrap();
        current.set_spreadsheet_cell("C2", "=A2+B2").unwrap();
        kind.save(&mut current, root);

        candidate
            .set_spreadsheet_frozen_axes("sheet-1", 2, 1)
            .unwrap();
        candidate
            .set_spreadsheet_cell_validation(
                "sheet-1",
                "A2",
                "list",
                vec!["9".to_string(), "10".to_string()],
                false,
            )
            .unwrap();
        candidate
            .merge_spreadsheet_cells("sheet-1", "A1:B1")
            .unwrap();
        candidate
            .add_spreadsheet_protected_range("sheet-1", "A2:C3", "Review before edit", true)
            .unwrap();
        kind.save_candidate(&mut candidate, root);

        kind.assert_candidate_has_unmerged_operations(
            &OpenDocApp::new_sample(),
            root,
            &saved_base.uuid,
        );

        let mut merger = OpenDocApp::new_sample();
        let merged = kind.merge(&mut merger, root, &saved_base.uuid);
        assert_spreadsheet_structural_merge_result(&merged);
        assert!(merged.operations.iter().any(|operation| {
            operation.actor == "actor-current-structure"
                && operation.kind == "set-spreadsheet-cell"
                && operation.summary == "set C2"
        }));
        assert!(merged.operations.iter().any(|operation| {
            operation.actor == "actor-candidate-structure"
                && operation.kind == "merge-spreadsheet-cells"
        }));
        assert!(merged.operations.iter().any(|operation| {
            operation.actor == "actor-candidate-structure"
                && operation.kind == "add-spreadsheet-protected-range"
        }));

        let reopened = kind.open(&mut OpenDocApp::new_sample(), root, &saved_base.uuid);
        assert_spreadsheet_structural_merge_result(&reopened);

        let second_pass = kind.merge(&mut merger, root, &saved_base.uuid);
        assert_eq!(second_pass.workbook, merged.workbook);
        let _ = std::fs::remove_dir_all(root);
    }

    fn assert_spreadsheet_structural_merge_result(document: &AppDocument) {
        let sheet = &document.workbook.sheets[0];
        assert_eq!(sheet.frozen_rows, 2);
        assert_eq!(sheet.frozen_columns, 1);
        assert_cell(sheet, "A2", "9", "number", &[]);
        assert_cell(sheet, "C2", "14", "number", &["A2", "B2"]);
        let validation = sheet
            .cells
            .iter()
            .find(|cell| cell.address == "A2")
            .and_then(|cell| cell.validation.as_ref())
            .expect("candidate validation survives structural merge");
        assert_eq!(validation.kind, "list");
        assert_eq!(validation.values, vec!["9", "10"]);
        assert!(!validation.strict);
        assert!(sheet
            .merges
            .iter()
            .any(|merged_range| merged_range.range == "A1:B1"));
        assert!(sheet.protected_ranges.iter().any(|protected_range| {
            protected_range.range == "A2:C3"
                && protected_range.description == "Review before edit"
                && protected_range.warning_only
        }));
        assert_eq!(
            graph_entry(&document.workbook.dependency_graph, "sheet-1", "A2").dependents,
            vec!["C2"]
        );
    }

    fn assert_candidate_merge_persists_structural_spreadsheet_warnings(
        kind: TestRepositoryKind,
        root: &std::path::Path,
    ) {
        let _ = std::fs::remove_dir_all(root);
        let mut base = OpenDocApp::new_sample();
        base.actor_id = "actor-base".to_string();
        let saved_base = kind.save(&mut base, root);

        let mut current = OpenDocApp::new_sample();
        current.actor_id = "actor-current".to_string();
        kind.open(&mut current, root, &saved_base.uuid);

        let mut candidate = OpenDocApp::new_sample();
        candidate.actor_id = "actor-candidate".to_string();
        kind.open(&mut candidate, root, &saved_base.uuid);

        current.set_spreadsheet_cell("B2", "11").unwrap();
        kind.save(&mut current, root);

        candidate.push_spreadsheet_operation(
            "add-spreadsheet-row",
            "stale candidate row add sheet",
            AppSpreadsheetOperation::AddRow {
                sheet_id: "missing-sheet".to_string(),
                row: "4".to_string(),
            },
        );
        candidate.push_spreadsheet_operation(
            "set-spreadsheet-cell",
            "stale candidate cell edit sheet",
            AppSpreadsheetOperation::SetCell {
                sheet_id: "missing-sheet".to_string(),
                address: "A1".to_string(),
                value: "lost".to_string(),
            },
        );
        candidate.push_spreadsheet_operation(
            "add-spreadsheet-named-range",
            "stale candidate named range sheet",
            AppSpreadsheetOperation::AddNamedRange {
                sheet_id: "missing-sheet".to_string(),
                name: "MISSINGSHEETRANGE".to_string(),
                range: "B2:B3".to_string(),
            },
        );
        candidate.push_spreadsheet_operation(
            "unmerge-spreadsheet-cells",
            "stale candidate unmerge sheet",
            AppSpreadsheetOperation::UnmergeCells {
                sheet_id: "missing-sheet".to_string(),
                range: "A1:B1".to_string(),
                merge: AppSheetMerge {
                    id: "merge-a1-b1".to_string(),
                    range: "A1:B1".to_string(),
                },
            },
        );
        candidate.push_spreadsheet_operation(
            "delete-spreadsheet-protected-range",
            "stale candidate protected range sheet",
            AppSpreadsheetOperation::DeleteProtectedRange {
                sheet_id: "missing-sheet".to_string(),
                range: "B2:C3".to_string(),
                protected_range: AppSheetProtectedRange {
                    id: "protected-b2-c3".to_string(),
                    range: "B2:C3".to_string(),
                    description: "Review only".to_string(),
                    warning_only: true,
                },
            },
        );
        candidate.push_spreadsheet_operation(
            "set-spreadsheet-basic-filter-options",
            "malformed candidate filter options",
            AppSpreadsheetOperation::SetBasicFilterOptions {
                sheet_id: "sheet-1".to_string(),
                criteria: vec![AppSheetFilterCriterion {
                    column: "A".to_string(),
                    condition: "text_contains".to_string(),
                    value: "Item".to_string(),
                }],
                sort_specs: vec![AppSheetFilterSortSpec {
                    column: "B".to_string(),
                    descending: false,
                }],
            },
        );
        candidate.push_spreadsheet_operation(
            "delete-spreadsheet-sheet",
            "stale candidate last sheet delete",
            AppSpreadsheetOperation::DeleteSheet {
                sheet_id: "sheet-1".to_string(),
                sheet: AppSpreadsheetWorkbook::sample().sheets[0].clone(),
                named_ranges: Vec::new(),
            },
        );
        candidate.push_spreadsheet_operation(
            "delete-spreadsheet-row",
            "stale candidate missing row delete",
            AppSpreadsheetOperation::DeleteRow {
                sheet_id: "sheet-1".to_string(),
                row: "99".to_string(),
                payload: empty_deleted_row_payload("99"),
            },
        );
        candidate.push_spreadsheet_operation(
            "delete-spreadsheet-column",
            "stale candidate missing column delete",
            AppSpreadsheetOperation::DeleteColumn {
                sheet_id: "sheet-1".to_string(),
                column: "Z".to_string(),
                payload: empty_deleted_column_payload("Z"),
            },
        );
        candidate.push_spreadsheet_operation(
            "update-spreadsheet-cell-comment",
            "stale candidate missing comment update",
            AppSpreadsheetOperation::UpdateCellComment {
                comment_id: "missing-comment".to_string(),
                body: "Replacement".to_string(),
            },
        );
        candidate.push_spreadsheet_operation(
            "delete-spreadsheet-cell-comment",
            "stale candidate missing comment delete",
            AppSpreadsheetOperation::DeleteCellComment {
                comment_id: "missing-comment".to_string(),
            },
        );
        candidate.push_spreadsheet_operation(
            "add-spreadsheet-sheet",
            "conflicting candidate duplicate sheet",
            AppSpreadsheetOperation::AddSheet {
                sheet_id: "sheet-1".to_string(),
                title: "Conflicting Sheet".to_string(),
            },
        );
        candidate.push_spreadsheet_operation(
            "add-spreadsheet-sheet",
            "aggregate-invalid duplicate title sheet",
            AppSpreadsheetOperation::AddSheet {
                sheet_id: "sheet-duplicate-title".to_string(),
                title: "Sheet1".to_string(),
            },
        );
        kind.save_candidate(&mut candidate, root);

        let mut merger = OpenDocApp::new_sample();
        let merged = kind.merge(&mut merger, root, &saved_base.uuid);
        let warning_codes = merged
            .warnings
            .iter()
            .map(|warning| warning.code.as_str())
            .collect::<BTreeSet<_>>();
        assert!(warning_codes.contains("missing-spreadsheet-sheet"));
        assert!(warning_codes.contains("invalid-spreadsheet-filter-options"));
        assert!(warning_codes.contains("invalid-spreadsheet-sheet-delete"));
        assert!(warning_codes.contains("missing-spreadsheet-row"));
        assert!(warning_codes.contains("missing-spreadsheet-column"));
        assert!(warning_codes.contains("missing-spreadsheet-cell-comment"));
        assert!(warning_codes.contains("duplicate-spreadsheet-sheet"));
        assert!(warning_codes.contains("invalid-spreadsheet-source"));
        assert!(merged.workbook.sheets[0]
            .cells
            .iter()
            .any(|cell| cell.address == "B2" && cell.user_value == "11"));
        assert!(!merged
            .workbook
            .sheets
            .iter()
            .any(|sheet| sheet.id == "sheet-duplicate-title"));

        let reopened = kind.open(&mut OpenDocApp::new_sample(), root, &saved_base.uuid);
        let reopened_codes = reopened
            .warnings
            .iter()
            .map(|warning| warning.code.as_str())
            .collect::<BTreeSet<_>>();
        assert_eq!(reopened_codes, warning_codes);
        let _ = std::fs::remove_dir_all(root);
    }

    fn assert_repository_merges_concurrent_sheet_adds_without_id_collision(
        kind: TestRepositoryKind,
        root: &std::path::Path,
    ) {
        let _ = std::fs::remove_dir_all(root);
        let mut base = OpenDocApp::new_sample();
        let saved_base = kind.save(&mut base, root);

        let mut current = OpenDocApp::new_sample();
        current.actor_id = "actor-current-sheet".to_string();
        kind.open(&mut current, root, &saved_base.uuid);
        let mut candidate = OpenDocApp::new_sample();
        candidate.actor_id = "actor-candidate-sheet".to_string();
        kind.open(&mut candidate, root, &saved_base.uuid);

        let current_doc = current.add_spreadsheet_sheet("Budget").unwrap();
        let current_sheet_id = current_doc.workbook.sheets[1].id.clone();
        kind.save(&mut current, root);
        let candidate_doc = candidate.add_spreadsheet_sheet("Data").unwrap();
        let candidate_sheet_id = candidate_doc.workbook.sheets[1].id.clone();
        assert_ne!(current_sheet_id, candidate_sheet_id);
        kind.save_candidate(&mut candidate, root);

        let mut merger = OpenDocApp::new_sample();
        let merged = kind.merge(&mut merger, root, &saved_base.uuid);
        assert!(merged
            .workbook
            .sheets
            .iter()
            .any(|sheet| sheet.id == current_sheet_id && sheet.title == "Budget"));
        assert!(merged
            .workbook
            .sheets
            .iter()
            .any(|sheet| sheet.id == candidate_sheet_id && sheet.title == "Data"));
        assert!(!merged
            .warnings
            .iter()
            .any(|warning| warning.code == "duplicate-spreadsheet-sheet"));

        let reopened = kind.open(&mut OpenDocApp::new_sample(), root, &saved_base.uuid);
        assert!(reopened
            .workbook
            .sheets
            .iter()
            .any(|sheet| sheet.id == current_sheet_id && sheet.title == "Budget"));
        assert!(reopened
            .workbook
            .sheets
            .iter()
            .any(|sheet| sheet.id == candidate_sheet_id && sheet.title == "Data"));
        let _ = std::fs::remove_dir_all(root);
    }

    fn assert_missing_blob_keeps_exact_byte_signature_sidecar_trust(
        kind: TestRepositoryKind,
        root: &std::path::Path,
    ) {
        let _ = std::fs::remove_dir_all(root);
        let mut app = OpenDocApp::new_sample();
        let with_blob = app
            .add_binary_blob(
                "signed-shallow.fastq",
                "text/x-fastq",
                b"@read-1\nACGT\n+\n!!!!\n".to_vec(),
            )
            .unwrap();
        let blob_hash = opendoc_core::HashRef::parse(&with_blob.blobs[0].hash).unwrap();
        let signed = app
            .sign_blob_with_openssh_private_key(
                &with_blob.blobs[0].hash,
                TEST_ED25519_PRIVATE_KEY,
                "Blob Signer",
            )
            .unwrap();
        assert_eq!(signed.blobs[0].signature_state, "signed");
        let typed_signed = app
            .sign_fastq_blob_with_openssh_private_key(
                &with_blob.blobs[0].hash,
                "sequence",
                TEST_ED25519_PRIVATE_KEY,
                "FASTQ Signer",
            )
            .unwrap();
        assert!(typed_signed.blobs[0]
            .typed_signatures
            .iter()
            .any(|signature| {
                signature.profile == "opendoc.fastq.sequence.v0"
                    && signature.signature_state == "signed"
                    && signature.signature.signer_display == "FASTQ Signer"
            }));

        let saved = kind.save(&mut app, root);
        kind.write_tombstone_and_assert_blob_signature(root, &blob_hash);
        kind.remove_blob_object(root, &blob_hash);
        kind.assert_manifest_dependency_audit_reports_missing_blob(root, &saved.uuid, &blob_hash);

        let mut shallow = OpenDocApp::new_sample();
        let opened = kind.open(&mut shallow, root, &saved.uuid);
        assert!(!opened.blobs[0].available);
        assert_eq!(opened.blobs[0].signature_state, "signed");
        assert_eq!(opened.blobs[0].signatures.len(), 1);
        assert_eq!(opened.blobs[0].signatures[0].signer_display, "Blob Signer");
        assert!(opened.blobs[0].typed_signatures.iter().any(|signature| {
            signature.profile == "opendoc.fastq.sequence.v0"
                && signature.signature_state == "untrusted"
                && signature.signature.signer_display == "FASTQ Signer"
        }));
        assert!(opened.blobs[0].archive_tombstone.is_some());
        assert!(opened
            .warnings
            .iter()
            .any(|warning| warning.code == "missing-blob"));

        let audit = shallow.audit_view();
        let audit_blob = audit
            .blob_signatures
            .iter()
            .find(|blob| blob.blob_hash == opened.blobs[0].hash)
            .expect("audit exposes signed missing blob");
        assert_eq!(audit_blob.signature_state, "signed");
        assert_eq!(audit_blob.signatures.len(), 1);
        assert!(audit_blob.typed_signatures.iter().any(|signature| {
            signature.profile == "opendoc.fastq.sequence.v0"
                && signature.signature_state == "untrusted"
                && signature.signature.signer_display == "FASTQ Signer"
        }));
        assert!(audit_blob.archive_tombstone.is_some());
        let _ = std::fs::remove_dir_all(root);
    }

    fn assert_corrupt_blob_signature_sidecar_degrades_to_warning(
        kind: TestRepositoryKind,
        root: &std::path::Path,
    ) {
        let _ = std::fs::remove_dir_all(root);
        let mut app = OpenDocApp::new_sample();
        let with_blob = app
            .add_binary_blob(
                "corrupt-signature.bin",
                "application/octet-stream",
                b"bytes".to_vec(),
            )
            .unwrap();
        let blob_hash = opendoc_core::HashRef::parse(&with_blob.blobs[0].hash).unwrap();
        app.sign_blob_with_openssh_private_key(
            &with_blob.blobs[0].hash,
            TEST_ED25519_PRIVATE_KEY,
            "Blob Signer",
        )
        .unwrap();
        let saved = kind.save(&mut app, root);
        kind.overwrite_blob_signature_sidecar(root, &blob_hash, b"not a canonical signature");

        let opened = kind.open(&mut OpenDocApp::new_sample(), root, &saved.uuid);
        assert!(opened.is_open);
        assert_eq!(opened.blobs[0].signature_state, "unsigned");
        assert!(opened.blobs[0].signatures.is_empty());
        assert!(opened.warnings.iter().any(|warning| {
            warning.code == "invalid-blob-signature-sidecar"
                && warning.message.contains("corrupt-signature.bin")
        }));
        let _ = std::fs::remove_dir_all(root);
    }

