    fn assert_deleted_corrupt_blob_signature_sidecar_degrades_to_warning(
        kind: TestRepositoryKind,
        root: &std::path::Path,
    ) {
        let _ = std::fs::remove_dir_all(root);
        let mut app = OpenDocApp::new_sample();
        let with_blob = app
            .add_binary_blob(
                "deleted-corrupt-signature.bin",
                "application/octet-stream",
                b"bytes".to_vec(),
            )
            .unwrap();
        let blob_hash = with_blob.blobs[0].hash.clone();
        let parsed_hash = opendoc_core::HashRef::parse(&blob_hash).unwrap();
        app.sign_blob_with_openssh_private_key(
            &blob_hash,
            TEST_ED25519_PRIVATE_KEY,
            "Deleted Blob Signer",
        )
        .unwrap();
        app.delete_binary_blob(&blob_hash).unwrap();
        let saved = kind.save(&mut app, root);
        kind.overwrite_blob_signature_sidecar(root, &parsed_hash, b"not a canonical signature");

        let mut reopened_app = OpenDocApp::new_sample();
        let opened = kind.open(&mut reopened_app, root, &saved.uuid);
        assert!(opened.is_open);
        assert!(opened.blobs.is_empty());
        assert!(opened.warnings.iter().any(|warning| {
            warning.code == "invalid-blob-signature-sidecar"
                && warning.message.contains("deleted-corrupt-signature.bin")
        }));
        let audit = reopened_app.audit_view();
        let deleted_blob = audit
            .blob_signatures
            .iter()
            .find(|blob| blob.blob_hash == blob_hash)
            .expect("deleted blob remains recoverable after corrupt sidecar");
        assert!(deleted_blob.deleted);
        assert_eq!(deleted_blob.signature_state, "unsigned");
        assert!(deleted_blob.signatures.is_empty());
        let _ = std::fs::remove_dir_all(root);
    }

