        let saved_base = kind.save(&mut base, root);

        let mut candidate = OpenDocApp::new_sample();
        candidate.actor_id = "actor-b".to_string();
        kind.open(&mut candidate, root, &saved_base.uuid);
        candidate
            .record_blob_archive_tombstone(
                &blob_hash,
                "tape://candidate/archive.txt",
                "request candidate archive recall",
                "candidate-indexer",
                b"candidate tombstone signature".to_vec(),
            )
